window.__D("text/keter-shem-tov/c001",{"p":[[300010174,"קמה\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> שרוב ענותנותו של האדם גורם שנתרחק מעבודת הש\"י, שמצד שפלותו אינו מאמין כי האדם גורם ע\"י תפלתו ותורתו שפע אל כל העולמות, וגם המלאכים ניזונין ע\"י תורתו ותפלתו. שאלו היה מאמין זה כמה היה עובד ה' בשמחה וביראה מרוב כל, והיה נזהר בכל אות ותנועה ומלה לאומרה כדקא יאות. וגם לתת לב אל מה שאמר שלמה ע\"ה אם תשכבון בין שפתים, שהקב\"ה שומר ושוקד על שפתי האדם לנושקה כשהוא אומרה בתורה ותפלה בדחילו ורחימו. ואם ישים אליו לבו, בוודאי מי &lt;הוא&gt; זה האיש אשר לא יאחזנו רתת וזיע שהמלך גדול ונורא שומר ושוקד על שפתים של אדם נבזה חדל אישים <span data-k=\"sm\">[וכיו\"ב]</span>.\n<b>והוא</b> מעין <span data-k=\"sm\">[מה]</span> שארז\"ל ענותנותו של ר' זכרי' גרם חורבן כו'. כך האדם ראוי לשום לב ולומר כי הוא סולם מוצב ארצה וראשו מגיע השמימה, וכל תנועותיו ועסקיו ודבורו <span data-k=\"sm\">[והלוכו]</span> עושה רושם למעלה <span data-k=\"sm\">[למעלה]</span>, בוודאי יזהר בכל דרכיו ועסקיו שיהיה לשם שמים, משא\"כ כשחושב האדם מה אני ספון לפגום או לתקן למעלה ולמטה שיהיה נרשם <span data-k=\"sm\">[כל]</span> עסקי למעלה, ובזה הולך בשרירות לבו ויאמר אך שלום יהיה לי. ובאמת זה אינו, כי האדם ע\"י מעשיו הטובים הוא דבוק בו ית' ממש, וכמ\"ש והלכת בדרכיו, וע\"י שהוא רחום למטה נתעורר מדה זו של רחום למעלה בכל העולמות, וכמ\"ש דע מה למעלה ממך, ר\"ל ממך תדע איזה מדה שנתעורר בך שכך הוא למעלה. וז\"ש ונתן לך רחמים ורחמך.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י עקב קעב</b>,<b> ג (תרלג</b>,<b> ב)</b>\n<i>האדם גורם ע\"י כו'</i> – זח\"א קלד, ב. שם קפה, א. שם רכט, ב. זח\"ב רא, א. ועוד. <i>המלאכים ניזונין כו'</i> – זח\"א יח, ב. זח\"ב קלב, א. שם קלא, ב. <i>עובד ה' בשמחה כו'</i> – ע\"פ תבוא כח, מז. <i>אם תשכבון גו'</i> – תהלים סח, יד. <i>ענותנותו של ר\"ז כו'</i> – גיטין נו, א. <i>סולם גו'</i> – ויצא כח, יב. <i>הולך בשרירות כו'</i> – ע\"פ נצבים כט, יח. <i>והלכת בדרכיו</i> – תבוא כח, ט. <i>דע מה כו'</i> – אבות פ\"ב מ\"א. <i>ונתן לך רחמים גו'</i> – ראה יג, יח.\n----- הערות וציונים -----\n<i>שרוב ענותנותו של אדם גורם כו'</i> – ראה לעיל סוף סי' סח (ובהערות שם), ולקמן סי' שצד בד\"ה וענין הזה. לקו\"י טו, א (סי' קנה).\n<i>אינו מאמין כו'</i> – ראה לעיל ריש סי' פ העיקר הוא האמונה כו' וגם יאמין כו'.\n<i>לתת לב אל מה שאמר כו'</i> – ראה לעיל סי' מד-א. וראה תניא פמ\"ו.\n<i>מה שאמר שלמה ע\"ה</i> – צ\"ע דהוא פסוק בלמנצח לדוד. ואולי חסר כאן וקאי על פסוק ישקני מנשיקות פיהו (שה\"ש א, ב) שנדרש ביחד עם פסוק אם תשכבון גו' לעיל בסי' מד-א, וכן בתוי\"י ר\"פ ויגש (לב, ד).\n<i>וכל תנועותיו כו' עושה רושם למעלה</i> – ראה זח\"א קכה, ב. זח\"ג מד, רע\"א בר\"מ, ושם צב, סע\"א ואילך, קי, ב וקיב, ב. ועוד. וראה לקמן בהוספות סי' עח ובהערות שם.\n<i>וע\"י שהוא רחום כו'</i> – ראה זח\"ג צב, ריש ע\"ב. צוה\"ר סי' קיב.\n<i>וכמ\"ש דע כו'</i> – ראה צוה\"ר סי' קמב. או\"ת סי' ש, ובהוספות שם סי' יט."]]],[300010175,"קמו\n\n<b>קושיא</b> <span data-k=\"sm\">[</span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;מהבעש\"ט&gt; בענין מה שאמרו <span data-k=\"sm\">[בש\"ס]</span> בכל יום בת קול יוצאת מהר חורב ומכרזת אוי להם לבריות מעלבונה של תורה, וכן מ\"ש אמר שומר, שדרשו שהוא כרוז <span data-k=\"sm\">[וכנ\"ל]</span>, &lt;וק'&gt; שאם אין שומע <span data-k=\"sm\">[את]</span> הכרוז למה מכריזין, ואם יש שומע קשה שהחוש מכחישו, כי מי זה יאמר ששמע כרוזין מלמעלה, ואף אם ימצא א' שאומר ששומע, מי הוא הפתי אשר יאמין לדבריו &lt;וידינהו כנביא שקר&gt;, וא\"כ לאיזה תועלת הוא הכרוז ללא יועיל.\n<b>&lt;ותירץ&gt;</b> <span data-k=\"sm\">[ותירוצו הוא על דרך זה, הגם שאין זה לשונו]</span> דאיתא בש\"ס <span data-k=\"sm\">[דחגיגה דף ה' ע\"ב]</span> רבי יהושע בן חנניה הוי קאי קמי קיסר אחוי ליה אפקורוסא עמא דאהדרינהו מריה לאפיה מיניה, אחוי ליה עוד ידו נטויה וכו' מאן דלא ידע במחוג ליחוי קמי מלכא <span data-k=\"sm\">[וכו']</span>. ויש להבין <span data-k=\"sm\">[זה הענין]</span> למה &lt;לא דברו במפורש&gt; <span data-k=\"sm\">[דברו ברמז ולא ע\"י דיבור מפורש]</span>, וגם לאיזה תועלת מביא הש\"ס זה.\n[<b>ונ\"ל</b>] &lt;ופי'&gt; דיוצא לנו מזה רמז מוסר בענין הכרוזין שלמעלה, שאינו דיבור, כי אין אומר ואין דברים שם למעלה &lt;אלא עולם המחשבה&gt;, כי הדיבור הוא גשמי, וראיה לזה כי מלכותא דארעא כעין מלכותא דרקיע, ואין דרך ארץ לדבר המלך עם שריו ועבדיו ויועציו <span data-k=\"sm\">[ועבדיו]</span> כי אם ברמז, וכאשר שגם עתה במלכות ישמעאל הנהגתו כך.\n<b>וזה</b> שהודיענו הש\"ס שגם הכרוזין היוצאין ממלך מלכו של עולם הוא ברמז, וצריך לידע במחוג רמז הכרוז ע\"י המחשבה שבאין לאדם בכל יום הרהורי תשובה שהוא מחמת הכרוז, או ע\"י שאר דברים הנודעים למי שעיני שכל לו, שלא יהיה מכלל אלו הנאמר &lt;בהם&gt; אל תהיו כסוס כפרד אין הבין במתג ורסן כו', רק כשנתעורר בעולם איזה פחד ויראה ידעו שמרמזין להם מלמעלה שידבקו בשרש היראה וכנ\"ל, וכשנתעורר איזה שמחה בעולם ידבק בשמחת עבודת ה' וכיוצא בזה, ישמע חכם ויוסיף לקח <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ראה קעד</b>,<b> ג (תרמ</b>,<b> א)</b>\n<i>בכל יום ב\"ק כו'</i> – אבות פ\"ו מ\"ב. <i>אמר שומר</i> – ישעי' כא, יב. <i>שדרשו שהוא כרוז</i> – זח\"ב קל, ב. <i>אין אומר ואין דברים</i> – ע\"פ תהלים יט, ד. <i>מלכותא דארעא כו'</i> – ברכות נח, א. <i>אל תהיו כסוס גו'</i> – תהלים לב, ט. <i>ישמע חכם גו'</i> – משלי א, ה.\n----- הערות וציונים -----\nראה לקמן סי' קעה, רנה, שס, ובהוספות סי' קא וקב ובהערות שם. רג\"כ מדל\"י סי' ט (י). לקו\"י לז, שלהי ע\"ג (סי' רפא). עיין דרך חיים לאדה\"א פ\"א. להעיר שעיקר הפירוש איתא בס' חרדים, מצות התשובה פ\"ז ד\"ה סגולה ששית (ומשם בשל\"ה מס' יומא, עמוד התשובה רמג, ב (עד, סע\"ב ואילך)).\n<i>כשנתעורר בעולם כו'</i> – ראה לעיל סי' קיא-ב ולקמן סי' רז-א."]]],[300010176,"קמז\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי בשם </span><i>מורי</i><span data-k=\"sm\">]</span> פירוש רצון יראיו יעשה ואת שועתם ישמע ויושיעם. דקשה, אם כבר עשה רצון יראיו מה צריך עוד לשמוע שועתם להושיעם, ועל כל פנים איפכא הוי ליה למימר ששומע שועתם ורצון יריאיו יעשה. וביאר, כי מצינו מדתו ית' ששומע לכל הקוראים אותו, או לטובה או לרעה ח\"ו, כמרז\"ל גנבא אפום מחתרתא רחמנא קריא, &lt;וכמש\"ל על הלואי אותי עזבו ותורתי שמרו&gt;. וכי תימא, אם כן מה הפרש יש בין צדיק לרשע. וביאר, כי יש הפרש גדול ביניהם. כי הגנב נשמע תפלתו שיוכל לגנוב, ואח\"כ שנתפס על גניבתו חוזר וקורא לו ית' שוב לא נענה מאחר שבחר בזה. משא\"כ הצדיק המתפלל על איזה דבר, גם שיודע ה' שאין זה לטובתו, מכל מקום ה' עושה מבוקשו. וז\"ש רצון יריאיו יעשה, ואחר כך כשרואה שאין זה טובתו חוזר וקורא אל ה', ואז ברחמיו ית' שועתם ישמע ויושיעם מכל מקום, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ שפטים קעח</b>,<b> רע</b>\"<b>א (תרנא</b>,<b> ב)</b>\n<i>רצון יראיו כו'</i> – תהלים קמה, יט. <i>גנבא אפום כו'</i> – ברכות סג, א (גי' הע\"י).\n----- הערות וציונים -----\n<i>וכמש\"ל על כו'</i> – לפי הנראה צריכים לפענח \"וכמו שנתבאר לעיל\", וקאי על לעיל סי' ג. ברם קשה, שהרי השמיט שם ענין זה, לכן נראה שצ\"ל \"וכמו שיתבאר לקמן\", וקאי על ההמשך בתוי\"י, תיכף אחרי מאמר הבעש\"ט, שמביא שם ביאור בשם הרב מו\"ה יואל שתפלת הגנב נשמעת דאם לא כן אין בחירה כשלא יוכל לעשות רע, ועוד כי מזה שרואה שתפלה מועלת גם להרע לזולתו יתן לב להתפלל שיוכל לעשות טוב, ועפ\"ז ביאר המדרש הלואי אותי עזבו ותורתי שמרו, עיי\"ש והוא ביאור הבעש\"ט המובא לעיל סי' ג."]]],[300010177,"קמח\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> בפסוק על מה שוא בראת, שהוא טענת היצה\"ר, והיה התשובה כל בני אדם. כי בעת רדת נשמה קדושה מלמעלה לגוף האדם, נתעורר קטרוג מלמעלה מס\"מ לומר מעתה לא יוכל לפעול פעולתו להסטין ולפתות מאחר שזה יחזיר העולם למוטב, וא\"כ למה נברא לריק, עד שנותנים לו נגד זה איש <span data-k=\"sm\">[בלע]</span> &lt;בליעל&gt; תלמיד חכם שידין יהודאין שנברא ג\"כ אשר יתלוצץ מזה האיש השלם. ומי שירצה ידבק בזה או בזה והבחירה חפשית.\n<b>ונודע</b> מה שאמרו חז\"ל <span data-k=\"sm\">[דבר צוה לאלף דור, ראה שאין העולם מתקיים בלי תורה. . .]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שפטים קפב</b>,<b> רע</b>\"<b>ג (תרסו</b>,<b> ב)</b>\n<i>על מה גו' כל בני אדם</i> – תהלים פט, מח. <i>דבר צוה גו'</i> – תהלים קה, ח. <i>ראה שאין כו'</i> – רש\"י חגיגה יד, רע\"א ד\"ה קודם.\n----- הערות וציונים -----\n<i>ת\"ח שידין יהודאין</i> – להעיר מזח\"ג רנג, רע\"א.\n<i>ונודע מרז\"ל כו'</i> – זו התחלה מהמשך ארוך שם לבאר הנ\"ל.\n<i>והבחירה חפשית</i> – ראה לעיל סי' ז."]]],[300010178,"קמט\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[אין בין חמץ למצה אלא משהו . . . וזה המשהו דוחה את האדם מהקדושה אל הקליפות, כמו שכתוב וסרתם ועבדתם אלהים אחרים, כמו ששמעתי בשם </span><i>מורי</i><span data-k=\"sm\"> ש\"ן. וכן כתב בחובות הלבבות, בשער הכניעה פ\"י, וזה לשונו]</span> הנכנע נמשך אחר החכמה כמ\"ש הולך את חכמים יחכם <span data-k=\"sm\">[וכמו שכתוב ידרך ענוים במשפט וילמד ענוים דרכו]</span>, ומי שהוא גבה לב לא תתקיים בידו החכמה שמתנשא מלכת אחר החכמה <span data-k=\"sm\">[והתורה]</span>, שנאמר רשע כגובה אפו בל ידרוש <span data-k=\"sm\">[אלהים וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שפטים קפה</b>,<b> ג (תרעו</b>,<b> ב)</b>\n<i>אין בין כו' אלא משהו</i> – זח\"ג רנב, א. <i>וסרתם גו'</i> – עקב יא, טז. <i>בחובה\"ל </i>. .<i> פ\"י</i> – אות ד. <i>הולך גו'</i> – משלי יג, כ. <i>ידרך ענוים גו'</i> – תהלים כה, ט. <i>רשע כגובה גו'</i> – תהלים י, ד.\n----- הערות וציונים -----\n<i>כמש\"כ וסרתם ועבדתם</i> – הובא בצוה\"ר סי' עו: כאשר האדם מפריד א\"ע מהשי\"ת מיד הוא עובד ע\"ז ולא יש דבר ממוצע, וזה וסרתם ועבדתם. והובא במאור עינים ר\"פ שמות, וכתב שם דפירוש זה היה מרגלא בפומיה דהריבעש\"ט נבג\"מ זי\"ע. וראה מדל\"י סי' קצט. ולהעיר מספרי על פסוק זה (הובא בפרש\"י); שבת קמט, א מאי תלמודא אר\"ח כו' (ע\"פ פירוש הערוך, ערך פן); רמב\"ם סה\"מ מל\"ת יו\"ד; ומו\"נ ח\"ג הערה בסוף פנ\"א."]]],[300010179,"קנ\n\n[<b>אין</b> <span data-k=\"sm\">להקב\"ה בעולמו אלא ד' אמות של הלכה וכו', וביאר </span><i>מורי</i><span data-k=\"sm\"> זלה\"ה]</span> בכל עסקי עוה\"ז יש בו תכלית פנימי <span data-k=\"sm\">[וכו' יעו\"ש]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י תצא קפט</b>,<b> ריש ע</b>\"<b>ב (תרפט</b>,<b> א)</b>\n<i>אין להקב\"ה כו'</i> – ברכות ח, א.\n----- הערות וציונים -----\nראה לעיל סי' עו. להעיר מלעיל סי' נג."]]],[300010180,"קנא\n\n<b>יש</b> דעייל ונפיק, וכמ\"ש ויעל אברם ממצרים, שירד ועלה עם כל מדריגות תחתונות, משא\"כ סוג ב' &lt;היורדים אינן יכולים לעלות&gt; <span data-k=\"sm\">[היורד ואינו יכול לעלות ר\"ל].</span>\n<b>וכמו</b> ששמעתי <span data-k=\"sm\">[</span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;הבעש\"ט זלה\"ה&gt; משל <span data-k=\"sm\">[נגד ב' כיתות הנ\"ל]</span> שהיה &lt;מעבר&gt; בדרך יער מושב ליסטים והיה סכנה מאד לכל עובר דרך שם, ונזדמן שהלכו שנים <span data-k=\"sm\">[דרך היער ההוא]</span>, א' היה שכור <span data-k=\"sm\">[כשכרותו של לוט]</span>, וא' היה בדעת מיושבת, ולשניהם פגעו הלסטים וחמסו וגזלו, הכום ופצעום, ונשאר להם רק נפשם לשלל. ובעברם משם ולהלן פגעו אנשים לאלו השנים. וקצת מהם שאלו לזה השכור איך עבר דרך היער, בשלום או לא, והשיבו שלום אין שום סכנה כלל. ושאלו מה הכאות וחבורות ופצעים, ואינו יודע להשיב. וקצת שאלו לזה הפקח, ואמר ח\"ו שיזהרו כי יש שם ליסטים, והאריך באזהרתו להם. והנפקותא בזה, שזה הפקח ידע להזהיר אחרים שלא ילכו שם כי אם בזריזות מזויינים וכיוצא, משא\"כ זה השכור אינו יודע להזהיר כלל.\n<b>וכך</b> הצדיק עובד ה' יודע ממלחמות היצה\"ר ומלסטים שבדרך עובד ה' שהוא מסוכן, ותמיד חיי צער יחיה איך להנצל ממצודתו, ויודע להזהיר אחרים מסכנות ליסטים, <span data-k=\"sm\">[זה יוסיף דעת יוסיף מכאוב]</span>. משא\"כ הרשע ששמח בשמחת יצה\"ר תמיד ואומר שלום כי אין שום סכנה בזה העולם.\n<b>וכן</b> בעוה\"ב הם ב' הפכים, כי לצדיק לשמחה יחשב לו שנפטר מזה העולם, שלכך נקרא מיתת הצדיק פטירה, שנפטר מצער עוה\"ז מעלמא דשקרא, ובבואו לעוה\"ב לשמחה יחשב לו. משא\"כ הרשע ששם יראה פנקסו פתוח והחשבון ערוך ליתן דין וחשבון.",[["","","----- מקורות ומראה מקומות -----\n<i>יש</i> . . <i>ממורי משל</i>: <b>תוי</b>\"<b>י ר</b>\"<b>פ שמות לו</b>,<b> א (קלג</b>,<b> א)</b>; <i>משל וכו'</i>: <b>שם ר</b>\"<b>פ תבוא קצד</b>,<b> ג (תשו</b>,<b> ב)</b>\n<i>יש דעייל ונפיק</i> – זח\"א ס\"ת קמז, סע\"ב. <i>ויעל אברם ממצרים</i> – לך לך יג, א. <i>חיי צער יחיה</i> – ע\"פ אבות פ\"ו מ\"ד. <i>יוסיף דעת כו'</i> – ע\"פ קהלת א, יח. <i>פנקסו פתוח כו'</i> – ע\"פ אבות פ\"ג מט\"ז.\n----- הערות וציונים -----\nהרכיב כאן הרישא מפ' שמות והמשל מפ' כי תבוא. בפ' תבוא הביא המשל נגד ב' כיתות הנזכרים שם – הרשעים הרודפים אחר יצה\"ר ותשוקת חמדת עוה\"ז והצדיקים שתמיד טרודים במלחמת יצה\"ר ואינם נותנים שמחה בלבם מעוה\"ז. אבל בפ' שמות הביא אותו משל (בקיצור) בנדון דשם.\n<i>כי לצדיק לשמחה יחשב</i> – ראה פי' הכותב לעין יעקב ברכות לא, א."]]],[300010181,"קנב-א\n\n<b>&lt;כתב</b> המחבר הרב הגאון מ' יעקב יוסף הכהן זלה\"ה וז\"ל:&gt; ואלה הדברים ששמעתי <i>ממורי</i> &lt;הבעש\"ט&gt; זלה\"ה, וכתבתי רק ראשי פרקים <span data-k=\"sm\">[כי יראתי, וגם מחמת השכחה]</span>.\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פירוש הש\"ס דר\"ה, נושא עון, חד אמר נושא וחד אמר כובש ועון עצמו אינו נמחק <span data-k=\"sm\">[וכו']</span> וכך היא המדה. וביאר, כי אלו ג' קוין חג\"ת מתפשטין מן רום המעלות עד התהום מקום הקליפה, וחסד במקום הקדושה למעלה הוא ענג, וכשנתפשט למטה בקליפה הוא זנות. וז\"ש למעלה מענג ולמטה מנגע. וקו התפארת בהתפשטו למטה במקום הקליפה היא הגאוה, וקו הגבורה למטה הוא כעס ועבודה זרה. והוא כשלהבת קשורה בגחלת זה בזה עד למעלה, רק למטה הוא בלי דעת, בסוד נשים דעתן קלה, שהרשעים הם בחינת נוקבא דעתן קלה עליהם, ולמעלה הוא עם הדעת שנותן דעתו שיתענג יותר בעבודת הש\"י ולא במקום הטינופת. ובחינת התשובה הוא הדעת כו', וכמו ששמעתי האומר אחטא ואשוב כו'. ובזה יובן נושא עון כו' ועון עצמו אינו נמחק, כי דבר גשמי ומאוס אינו יכול לעלות למעלה במקום שורש התענוג כו', וכך היא המדה, ר\"ל מדת רב חסד שהוא התענוג שהוא חסד התענוג נתלבש זה בתוך זה כו'. וחד אמר כובש כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>סוף ס</b>'<b> תוי</b>\"<b>י ר</b>,<b> ג</b>-<b>ד (תשכז</b>,<b> א אות א)</b>\n<i>הש\"ס דר\"ה</i> – ר\"ה יז, א. <i>למעלה מענג ולמטה מנגע</i> – ס\"י פ\"ב מ\"ד. <i>כשלהבת קשורה בגחלת</i> – ס\"י פ\"א מ\"ו. זח\"ג ע, א. שם רמו, א. <i>נשים דעתן קלה</i> – שבת לג, ב. <i>האומר אחטא כו'</i> – יומא פה, ב.\n----- הערות וציונים -----\n<i>אלו ג' קוין חג\"ת</i> – ראה לעיל סי' צט.\n<i>מתפשטין </i>. .<i> עד התהום מקום הקליפה</i> – דזלעו\"ז יש עשרה כתרי דמסאבותא כמבואר בזח\"ג מא, ב ושם ע, א.\n<i>בקליפה הוא זנות </i>. .<i> גאוה </i>. .<i> כעס וע\"ז</i> – ראה צוה\"ר סי' יד וסי' פז ובהערות שם. וראה לקמן סי' קסג.\n<i>כעס וע\"ז</i> – להעיר ממחז\"ל כל הכועס כאילו עע\"ז (זח\"א כז, ב. זח\"ג קעט, א ורלד, ב. הלכות דעות פ\"ב ה\"ג) וביאורו בתניא, אגה\"ק סי' כה, ומש\"כ באו\"ת סי' שמט.\n<i>בסוד נשים דעתן קלה כו'</i> – ראה ע\"ח שמ\"ח פ\"ב.\n<i>ובחי' התשובה הוא הדעת כו'</i> – ראה לעיל סי' קכד ובהערות שם.\n<i>מדת רב חסד</i> – ראה זח\"ג קלג, ב ושם קמ, ב. ומבואר בתניא, אגה\"ק סי' יו\"ד ושם סוף סי' יג עיי\"ש."]]],[300010182,"קנב-ב\n\n<b>עוד</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פירוש פסוקי תהלים <span data-k=\"sm\">[סימן לו]</span> יתיצב על דרך לא טוב רע לא ימאס <span data-k=\"sm\">[וגו']</span>, ואגב ביאר עוד המשך הפסוקים נאם פשע לרשע וגו' אין פחד אלהים לנגד עיניו, והטעם שסילק הש\"י פחד ממנו, כי החליק אליו בעיניו, שיהיה הכל חלק וישר בעיניו, כדי למצוא עונו לשנוא, ר\"ל שישיג וימצא העון ויהיה מקום להש\"י לשנוא אותו רשע, וסילק הבחירה ממנו.\n<b>דברי</b> פיו און ומרמה, ר\"ל שאינו טועה לומר על רע טוב רק במרמה כו', חדל להשכיל להיטיב, ר\"ל גם כשעולה לפעמים במחשבתו להשכיל להטיב, שיחקור וישכיל אם הוא דרך טוב להיטיב, מיד חדל ומונע פן ישוב כו'.\n<b>און</b> יחשוב על משכבו, כי האדם נקרא עולה ויורד, כי לפעמים מונע הש\"י מן האדם דרכי עבודת ה' כדי שיטריח יותר ויקבל שכר, ואז און יחשוב על משכבו <span data-k=\"sm\">[וכו', דשמעתי ממנו]</span> &lt;דפי' הבעש\"ט&gt; טעם שכתב הרמב\"ן כשרוצה הש\"י לענוש הרשע נזדמן לו איזה חטא כדי שיענש <span data-k=\"sm\">[וכו']</span>. והקשה <span data-k=\"sm\">[</span><i>מורי</i><span data-k=\"sm\">]</span> אם כן אין בחירה <span data-k=\"sm\">[וכו']</span>. ותירץ, כי החיות רצוא ושוב, ונקרא קטנות וגדלות, וכשהוא בקטנות עלול לעבירה בסוד אין אדם עובר עבירה אא\"כ כו', וכמ\"ש בעץ חיים בסופו, אם כן החטא והעונש בא כאחד. וז\"ש און יחשוב על משכבו, בקטנות.\n<b>יתיצב</b> על דרך לא טוב, כי מהפך מעשה הצדיקים שהם אור לחושך, ומעשה הרשעים חושך לאור, כמ\"ש במכילתא מסירת המן בפני אחשורוש שחשב פרעה לצדיק מרישא לסיפא שניצל אברהם בזכות ישמעאל כו' עד עמלק הצדיק וישראל בהיפך. וז\"ש רע לא ימאס. וככה עושין הרשעים בכל דור להפך <span data-k=\"sm\">[וכו']</span>. וז\"ש יתיצב על דרך לא טוב וגו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>סוף ס</b>'<b> תוי</b>\"<b>י ר</b>,<b> ג</b>-<b>ד (תשכז</b>,<b> א אות ב)</b>\n<i>יתיצב גו'</i> – תהלים לו, ה. <i>נאם פשע גו' כי החליק גו'</i> – תהלים לו, ב-ג. <i>דברי פיו גו' און יחשוב גו'</i> – תהלים לו, ד-ה. <i>החיות רצו\"ש</i> – יחזקאל א, יד. <i>אין אדם עובר כו'</i> – סוטה ג, א. <i>בע\"ח בסופו</i> – סוף שער נ. <i>מסירת המן בפני אחשורוש כו'</i> – ר' אס\"ר ז, יב.\n----- הערות וציונים -----\n<i>רק במרמה</i> – ראה לעיל סי' עח-ב.\n<i>האדם נקרא עולה ויורד כו'</i> – ראה לעיל סי' לז והנסמן שם.\n<i>וכשהוא בקטנות עלול כו'</i> – להעיר מצוה\"ר סוף סי' קא."]]],[300010183,"קנג-א\n\n[<b>ביאור</b> <span data-k=\"sm\">מה ש]</span>שמעתי <i>ממורי</i> &lt;הבעש\"ט&gt; ורשמתי ראשי פרקים כי יראתי <span data-k=\"sm\">[וכו']</span>, פסוק אל יתהלל חכם בחכמתו עשיר בעשרו כ\"א בזאת וגו' השכל וידוע אותי <span data-k=\"sm\">[וגו']</span>. והקשה מאי בחכמתו בעשרו. וביאר כי היא מדה מגונה המתפאר את עצמו, וכמ\"ש בספרא דשלמה מלכא, מובא בזוהר, סימן דלא ידע כלום שבוחי <span data-k=\"sm\">[וכו']</span>, וכשהוא רוצה להתפאר ולשבח את עצמו והיינו משום שנתפשט מדת התפארת בעולם, &lt;וכן מדת אהבה בהתפשטותה, הצדיק אוהב מצוה והרשע אוהב דבר עבירה; וכן יראה, הצדיק הוא ירא ה' והרשע ירא שלא יעני ע\"כ אינו נותן צדקה&gt;, וכשמתפשט &lt;מדת הת\"ת&gt; ויורד עד אדם זה שהוא בקליפה אז רוצה לשבח ולפאר א\"ע, רק שהוא גנאי כנ\"ל, ועושה תחבולה לפאר לאחרים שיצא מזה תפארת לעצמו, כגון פלוני חכם מאד שלא נצחו שום אדם כ\"א אני, וכן גבור ועשיר. וז\"ש אל יתהלל חכם בחכמתו של אחר כדי שיצא מזה שבח לעצמו, כ\"א בזאת יתהלל שיתן לב שנתפשט מדת הת\"ת שבעולם עד מדריגה אחרונה הנקרא זאת, והחכם יבין שנתפשט מדה זו השכל וידוע אותי, משא\"כ הטפש לוקח תפארת לעצמו וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>סוף ס</b>'<b> תוי</b>\"<b>י ר</b>,<b> ג</b>-<b>ד (תשכח</b>,<b> א אות ג)</b>\n<i>אל יתהלל גו'</i> – ירמי' ט, כב. <i>מובא בזוהר</i> – זח\"ג קצג, ב. <i>מדריגה אחרונה הנק' זאת</i> – זח\"ג רצז, ב (וראה זח\"א צג, סע\"ב)\n----- הערות וציונים -----\n<i>לפאר לאחרים שיצא מזה תפארת לעצמו</i> – להעיר מלעיל סי' סב לחקור כו' צריך שיהיה זה יותר חכם כו'.\n<i>כ\"א בזאת יתהלל כו'</i> – ראה תקוזו\"ח קיא, א-ב, ושם: ומי שמכיר אותו בזאת כאלו מכיר אותו בעליונים ובתחתונים בעבור שהיא כלולה מהעליונים והיא יחוד וקשר כולם והיא מתלבשת בכל התחתונים כו' וע\"ז אמר הנביא . . כי אם בזאת גו'.\n<i>שנתפשט כו' עד מדריגה אחרונה הנקרא זאת</i> – כלומר עד מלכות שנק' זאת (ראה לעיל סי' קכו), ועיין לקמן סי' קעט. ועיין תוי\"י פ' שפטים קפ, סע\"ג (תרס, ב) שמעתי ממורי זלה\"ה אל יתהלל חכם בחכמתו כי מצד השבירה שנפלה ממדת תפארת בתוך הקליפה אדם מתפאר וכו'."]]],[300010184,"קנג-ב\n\n<b>עוד</b> שמעתי <i>ממורי</i> &lt;הבעש\"ט&gt; ביאור ש\"ס אין לגבי משה מלתא זוטרתי היא, והקושיא מפורסמת הא לישראל אמר זה. וביאר, דכתב המהרש\"א את ה' אלקיך תירא לרבות תלמידי חכמים, כי אין בור ירא חטא, וע\"י שהוא &lt;ירא מן&gt; ת\"ח בא ליראת ה', ושפיר דרשו לרבות ת\"ח <span data-k=\"sm\">[וכו']</span>. והנה במשה מצינו ויראו מגשת אליו, אם כן כבר נכנסו ליראת תלמידי חכמים, אז בנקל יוכלו לבוא ליראת ה'. וז\"ש אין לגבי משה <span data-k=\"sm\">[זוטרתי]</span>, ר\"ל מאחר שכבר נכנסו ביראת ת\"ח שהיא לגבי משה שנאמר ויראו מגשת אליו, א\"כ זוטרתי לבוא ג\"כ ליראת ה', שזה נמשך מזה, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>סוף ס</b>'<b> תוי</b>\"<b>י ר</b>,<b> ג</b>-<b>ד (תשכח</b>,<b> א אות ד)</b>\n<i>אין לגבי משה כו'</i> – ברכות לג, ב. <i>דכתב המהרש\"א</i> – ב\"ק מא, ב ד\"ה כיון. <i>את ה' גו'</i> – ואתחנן ו, יג. <i>את </i>. .<i> לרבות ת\"ח</i> – ב\"ק מא, ב. פסחים כב, ב. <i>אין בור כו'</i> – אבות פ\"ב מ\"ה. <i>ויראו מגשת אליו</i> – כי תשא לד, ל.\n----- הערות וציונים -----\nראה לעיל סוף סי' לח ולקמן סי' קפא.\n<i>מלתא זוטרתי</i> – ביאור באו\"א ראה לעיל סי' לא."]]],[300010185,"קנג-ג\n\n<b>ושמעתי</b> ממנו משל למלך שנהג ליכנס בין עניים לפקח בעסקם. וא' היה משיב תמיד כל מה שאדם עושה בין טוב בין רע הכל עושה לעצמו. וחרה למלך על שאינו מחזיק לו טובה ומשיב לו כך, וצוה לעשות תרנגול מפוטם בסם המות ונתן לו, והשיב ג\"כ כך. ולקח העני זה לביתו שהיה בקצה העיר והצניעו. לימים בא המלך עיף ויגע מצידת חיה ועוף, ובקש מעני זה שבא אצלו ליתן לו שום דבר מאכל, ונתן לו זה התרנגול לאכול, וכשרצה לאכול אמרו הרופאים שעמו בדוק תחלה, ונמצא סם המות, ובא הדבר למלך והתנצל שהוא ממנו, ואז הודה המלך שאמת אתו, והמוסר היוצא מזה כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>סוף ס</b>'<b> תוי</b>\"<b>י ר</b>,<b> ג</b>-<b>ד (תשכח</b>,<b> א סוף אות ד)</b>\n----- הערות וציונים -----\n<i>המוסר היוצא מזה כו'</i> – צ\"ע מהו. בס' בעש\"ט פ' ראה הג' ב מציע לקשר משל זה עם המאמר הסמוך לו בתוי\"י ומובא לקמן סי' רחצ שגם הוא סתום ואינו מבואר עיי\"ש. ואולי י\"ל – בדרך אפשר בעלמא (ראה מ\"מ לזח\"א ד, ב סוף ד\"ה לאינון תרעין) ובדוחק – דהמוסר הוא להמבואר בדא\"ח בענין יש מי שאוהב (ראה תורה אור לאדה\"ז פ' וארא נו, א ושם פ' ויקהל קיד, סע\"ג ואילך. ביאורי הזוהר לאדה\"א פ' אמור פא, א-ב. תורת שמואל תרל\"ג לאדמו\"ר מוהר\"ש קעב ואילך. ועוד), כלומר לא מיבעיא אלו הנזכרים בתקו\"ז ת\"ו כב, סע\"א או אלו הנזכרים שם ת\"ל עג, ב עליהם נאמר דלגרמייהו עבדין, אלא אפילו הוא צדיק גמור כו' הוא דבר בפ\"ע ירא ה' ואוהבו כו' שמתדבק בו באהבה רבה כו' זה האוהב שהוא יש ולא אפס כו' (תניא פל\"ה עיי\"ש)."]]],[300010186,"קנד\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> ביאור למה ע\"י מכת בכורות יצאו ממצרים. <span data-k=\"sm\">[וביאר בארוכה, ומפני עומק המושג כתבתי ראשי פרקים]</span>. כי בכור נקרא דבר חידוש הנאמר בראש, והוא דבר שכל ומשכיל <span data-k=\"sm\">[שישכיל]</span> בשכלו הקודש איך לנהוג בעבודת הש\"י, רק בכור השפחה שהם הקליפות מבדילין בין השכל ובין קונו &lt;כו'&gt; <span data-k=\"sm\">[וזה היה סיבת גלות מצרים, ר\"ל מצ\"ר ים]</span> וכאשר לקו בכור השפחה והוסר הקליפה ממילא יצאו מהגלות &lt;כו'&gt; <span data-k=\"sm\">[ולכך הוקדשו בכורי ישראל שהוא השכל, אלא שאי אפשר שיהיו על מדריגה א' כי החיות רצוא ושוב בסוד קטנות וגדלות, וזהו שעשו עגל ולקח הש\"י תמורת בכורים שבט לוי, כי אותיות לו\"י וכו'. וזהו ג' בחינות קהת גרשון ומררי וכו' וכאשר האדם בסוד הקטנות ויודע מזה מוליד נשמת גרים, כי ג' הוא ג' קוים דרך ר' עלמין דכסופין וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> רע</b>\"<b>א (תשכח</b>,<b> ב אות ו)</b>\n<i>בכור השפחה שהם הקליפות</i> – זח\"ב לז, סע\"ב ומ\"מ שם. <i>וכאשר לקו כו' יצאו מהגלות</i> – זח\"ב לח, רע\"א. שם מח, ריש ע\"ב. <i>החיות רצו\"ש</i> – יחזקאל א, יד. <i>ולקח הש\"י תמורת בכורים שבט לוי</i> – במדבר ג, יב. <i>ר' עלמין דכסופין</i> – זח\"א קכד, ב.\n----- הערות וציונים -----\nלקמן סי' שצז במילואו.\n<i>ובכור נקרא דבר חידוש כו'</i> – להעיר משער המצות, פ' יתרו (ובלקו\"ת ושער הפסוקים פ' וירא) בענין לרבות אחיך הגדול (הובא בצוה\"ר סי' צ).\n<i>בכור </i>. .<i> דבר שכל ומשכיל</i> – להעיר מזח\"ג רסב, א שהוא בחי' חכמה.\n<i>וזה היה סיבת גלות מצרים</i> – דהיינו גלות הדעת כמבואר בשער הפסוקים ובלקו\"ת להאריז\"ל, פ' וישב ופ' שמות. שער הכונות, ענין הפסח דרוש א. פע\"ח שער חג המצות פ\"א. ולקמן סי' שע.\n<i>אלא שא\"א שיהיו על מדרגה א' כו'</i> – ראה לעיל סי' קנב-ב ובהערות שם.\n<i>אותיות לו\"י וכו' וזהו ג' בחינות קהת גרשון ומררי כו'</i> – אינו מבואר. ואולי כונתו למש\"כ בתוי\"י ר\"פ נשא קיח, ג (תמד, א): בבני לו\"י שהוא לשון חיבור אינו רק ג' סוגים, כי קהת הוא לשון ולו יקהת עמים (ויחי מט, י) שפירש רש\"י לשון אסיפה . . וז\"ש תחלה קהת שיאספו יחד ראשי העם ויחזרו בתשובה סוג א', ואז נשא את ראש בני גרשון גם הם שהם יתר העם הנחשב כגרים נגד ראשי העם שישמעו לקולם שהוא סוג ב', ואח\"כ כשאינו שומע לקולם ע\"כ ישמעו בסוג ג' הנקרא מררי שימררו חייהם של שכניהם סוג ג' הנ\"ל, ואז ודאי יצטער בצרתו כאילו בא עליו כי הוא מסוג לוי וחיבור וישוב בתשובה ושוב א\"צ לסוג ד' וק\"ל.\n<i>כאשר האדם בסוד קטנות ויודע מזה מוליד נשמת גרים</i> – ראה קדושת לוי, שה\"ש ד\"ה לריח שמניך (סה, א): למה ברא השם ית' זה שיפול צדיק ממדריגתו . . דבר זה אמר הבעש\"ט ז\"ל ומורי הצדיק מו' דוב בער זצ\"ל שמזה שנופל הצדיק ממדריגתו ומתחזק לחזור ולשוב לאיתנו מזה נבראו נשמות, והוא כמו מי שרוצה להעלות את חבירו מטיט ורפש שצריך גם הוא לירד סמוך להטיט ורפש להעלות אותו, כמו כן מזה נבראו נשמות גרים ממה שהצדיק נופל ממדריגתו ומתחזק א\"ע לעבוד השי\"ת ולחזור ולשוב אל מקומו עכ\"ד. וראה לקמן סי' שנו. ולהעיר מאו\"ת פ' תצא סי' קעה (והוא במדל\"י סי' סז (פ), אלא ששם חסר וגם לא נזכר שהוא מהבעש\"ט) ושם סי' תנא (והוא בלקו\"י סי' ריג). ועיי\"ע בענין הולדת נשמות גרים בס' קהלת יעקב ערך גרים אות א-ד."]]],[300010187,"קנה\n\n[<b>שמעתי</b> <i>ממורי</i><span data-k=\"sm\"> פירוש הש\"ס]</span> ושבתם וראיתם בין צדיק לרשע בין עובד ה' לאשר לא עבדו, ופריך הש\"ס היינו צדיק היינו עובד, היינו רשע היינו לא עובד, אלא אינו דומה שונה פרקו ק' פעמים לשונה פרקו ק\"א פעמים. &lt;וקשה&gt; <span data-k=\"sm\">[ויש לדקדק]</span> וכי בשביל שחסר א' יהיה נקרא רשע לא עובד. וביאר ע\"פ משל, בא יבא ברנה נושא אלומותיו, אם יסוד תורתו ועבודתו ליוהרא, גם שהוא עובד אינו כלום מאחר שחסר ממנו אחד, &lt;פי'&gt; שיכוין לשמו ית' סוד אחד האמיתי, ובזה <span data-k=\"sm\">[יובן]</span> גם שהוא עובד ה' מ\"מ מקרי לא עובד, והטעם, שאינו דומה שונה ק' פעמים לשונה מאה פעמים ואחד, שחסר אחד <span data-k=\"sm\">[והבן, ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> א (תשכח</b>,<b> ב אות ז)</b>\n<i>ושבתם גו'</i> – מלאכי ג, יח. <i>ופריך הש\"ס כו'</i> – חגיגה ט, ב. <i>בא יבא גו'</i> – תהלים קכו, ו.\n----- הערות וציונים -----\n<i>ויש להבין כו' לא עובד</i> – להעיר מתניא פט\"ו, ולקו\"ת לאדה\"ז פ' ראה כב, ג.\n<i>בא יבא ברנה כו'</i> – ראה לעיל סי' ל ובהערות שם.\n<i>שחסר אחד</i> – ראה דמ\"א, פ' אחרי ד\"ה והנה יש, בשם הבעש\"ט: ואחד היינו שמכניס בלימודו האחד שהוא אלופו של עולם, והוא תורה לשמה והוא אלוף בינה."]]],[300010188,"קנו\n\n<b>עוד</b> שמעתי בשם <i>מורי</i> &lt;הבעש\"ט&gt;, כשהלך בנסיעה הידועה הראה לו רבו במקום זה היה מרומז הנסיעה שהיו נוסעין ישראל במדבר במסע זה, וכל נסיעות האדם מרומז בתורה כו'. וכן כשנשברה לו הספינה והיה בעצבות גדול, ובא רבו ותמה עליו והראה לו באיזה עולמות הוא עכשיו, והיו שמות אהיה &lt;וצרופי אהיה&gt; וכו', ואז התחזק בלבו למתקן בשרשן כידוע לו <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> א (תשכח</b>,<b> ב אות ח)</b>\n----- הערות וציונים -----\n<i>בנסיעה הידועה</i> – הנסיעה לארה\"ק תוב\"ב שלא עלתה לו, ונזכרת בשבחי הבעש\"ט, וגם כ\"ק אדה\"ז מרמזת אליה באגרות קודש – אדה\"ז סי' קטז.\n<i>וכל נסיעות האדם מרומז בתורה</i> – ראה לקמן בהוספות סי' ל מדמ\"א פ' מסעי (הובא לקמן בהערות לסי' קעח עיי\"ש)."]]],[300010189,"קנז\n\n<b>בש\"ס</b> חשיב דברים העושה אותן ניצול מחיבוט הקבר, וחד מהן אם מת בערב שבת <span data-k=\"sm\">[וכו']</span>. והקשה <span data-k=\"sm\">[</span><i>מורי</i><span data-k=\"sm\">]</span> &lt;הבעש\"ט&gt; הא כוונת הש\"ס להשמיענו איך לעשות תקנה להנצל מחיבוט הקבר, משא\"כ בזה שימות בע\"ש אין זה בידו לעשות. וביאר, שהוא מוסר גדול שימות בע\"ש, ר\"ל לפנות א\"ע מכל עסקי עוה\"ז כאלו מת כדי לעשות הכנה לשבת, ובזה ניצול מחיבוט הקבר הנ\"ל, וישמע חכם ויוסיף לקח, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> א (תשכט</b>,<b> א ריש אות יא)</b>\n<i>ישמע חכם גו'</i> – משלי א, ה.\n----- הערות וציונים -----\n<i>בש\"ס חשיב דברים כו'</i> – מס' חיבוט הקבר פ\"ג.\n<i>וחד מהן אם מת בע\"ש</i> – ראה כתובות קג, ב (ואדר\"נ פכ\"ה) מת בערב שבת סימן יפה לו, ופרש\"י שם. להעיר שבמס' חיבוט הקבר פ\"ג: אמרו ז\"ל הדר בא\"י ומת בערב שבת אינו רואה דין הקבר; ועיין בחס\"ל מעיין ה נהר ג מש\"כ על זה. ולהעיר משער הכונות להאריז\"ל, ענין יום הו' בעצמו (כד, ב. וכן בסוף ס' שער מאמרי רז\"ל, ובשער הגלגולים הקדמה כג): שאמר לי מורי ז\"ל שקבל מאדם אחד גדול שאמר לו שקבלה היתה בידו מרבותיו שכל מי שנקבר בע\"ש אחר שעה ה' מן היום שאין לו חיבוט הקבר כו' עיי\"ש. ומסיים שמורי ז\"ל הודה לדבריו והסכים אליהם. ובהגהות הרש\"ו שם: נראה מדברי הרב ז\"ל שאפילו נקבר בחו\"ל.\n<i>לפנות א\"ע מכל עסקי עוה\"ז</i> – להעיר משבט מוסר פ\"כ דעיקר חבוט הקבר בא על מי שמשמח עצמו בעוה\"ז כו'.\n<i>לעשות הכנה לשבת</i> – להעיר מע\"ז ג, א מי שטרח בע\"ש כו', ובנ\"ד זח\"א קצו, ב מאן דלא אתקין כו'."]]],[300010190,"קנח\n\n<b>בפ'</b> לך לך <span data-k=\"sm\">[מארצך וגו']</span> ביאור סוד אותיות א\"ב וגו' ומנצפ\"ך, שיורד אות א' מהחיות כו' ומלובש במנצפ\"ך שהוא דינין, וצריך להעלותן, ואות ל' הוא &lt;כ\"ו&gt; <span data-k=\"sm\">[וכו']</span>, ואות ך' הוא סוף מנצפ\"ך כו'. וזהו ענין תחיית המתים ומשיח, שהוא בסוד הדעת, והוא סוד עוה\"ב. והנה ע\"י מעשי האדם הממשיך על עצמו בעוה\"ז ע\"י בינה שלו שמבין לעשות כל מעשיו בבינה ודעת כו', <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> א (תשכט</b>,<b> א סוף אות יא)</b>\n<i>לך לך גו'</i> – לך לך יב, א. <i>במנצפ\"ך שהוא דינין</i> – ע\"ח שי\"ח פ\"ה. שם שכ\"ה פ\"ב. <i>ואות ל' הוא כ\"ו </i>– פרדס רמונים שער האותיות פט\"ו. פע\"ח שער הסליחות פ\"ח. של\"ה תושב\"כ עקב שעא, א (פ, א).\n----- הערות וציונים -----\n<i>במנצפ\"ך שהוא דינין</i> – ראה פרדס רמונים, שער האותיות פכ\"ו. תניא, שהיוה\"א ספ\"ד.\n<i>ואות ך' הוא סוף מנצפ\"ך</i> – עיין של\"ה, מס' פסחים בסוף ענין מצה עשירה (כח, סע\"ב ואילך).\n<i>ענין תחה\"מ ומשיח שהוא בסוד הדעת</i> – ראה לקמן סי' שע."]]],[300010191,"קנט\n\n<b>עוד</b> &lt;פי' הבעש\"ט&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\"> ביאור פסוק תהלים סי' קט]</span> ותפלתו תהיה לחטאה, יהיו בניו יתומים ואשתו אלמנה <span data-k=\"sm\">[וגו']</span> ינקש כו'. והקשה מה <span data-k=\"sm\">[זה]</span> עונש לרשע שתהיה אשתו ובניו וגו'. וביאר ש\"ס תלמוד גדול שמביא לידי מעשה <span data-k=\"sm\">[וכו']</span>, והקשה א\"כ משמע דמעשה גדול <span data-k=\"sm\">[וכו']</span>, וביאר כי תלמוד יש בו שניהם, כי העוסק בתורת עולה כאלו הקריב עולה, אם כן שניהם בידו, משא\"כ מעשה הוא לבד, <span data-k=\"sm\">[וכו']</span>.\n<b>והנה</b> נפש הוא מלבוש לרוח ורוח מלבוש הנשמה, א\"כ נפש נגד רוח נקרא אשתו, וכן רוח נקרא נגד נשמה אשתו <span data-k=\"sm\">[וכו']</span>, וכמו שצדיק ממנו בולע <span data-k=\"sm\">[וכו']</span> הכי נמי אמר דוד המלך ע\"ה נגד דואג ואחיתופל שלמדו על כל פנים תורה שהוא מיין נוקבין לתפלה, וכמ\"ש מוהרש\"א שכל התורה הוא הכנה ליראה הנקראת תפלה <span data-k=\"sm\">[וכו']</span>, ובתפלה משפיעין למתפלל מיין דוכרין נגד מיין נוקבין, וכשלמד לשמה כמו שהיה מיין נוקבין כך הוא מיין דוכרין, משא\"כ כשלמד שלא לשמה כך משפיעין לו בתפלה, ואז תפלתו לחטאה, שמבלבלין אותו בתפלתו במחשבות זרות, ואז אשתו, שהיא נפש, היא אלמנה, שאינה מלבוש לרוח להיות מיין נוקבין, וגם בניו שהם מע\"שים טובים הם יתומים, כי התורה שנקראת מע\"שה כנ\"ל אחר שהיה שלא לשמה הם נע ונד דלא פרחית לעילא, והם יתומים <span data-k=\"sm\">[וגו']</span>. ינקש נושה לכל אשר לו, כי היצה\"ר מלוה לו להמציא לו איזה מצוה שיעשה להתפאר או שילמוד תורה <span data-k=\"sm\">[שנקראת מעשה]</span> להתפאר, וכך משפיעין לו מיין דוכרין מלמעלה רבות רעות וצרות, ואז היצה\"ר, נושה שלו, בא להפרע מן הלוה, וז\"ש ינקש נושה לכל אשר לו רחמנא לשזבן כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> א (תשכט</b>,<b> ב אות יב)</b>\n<i>ותפלתו תהי' גו'</i> – תהלים קט, ז. <i>יהיו בניו גו'</i> – שם ט. <i>ינקש גו'</i> – שם יא. <i>תלמוד גדול כו'</i> – קידושין מ, ב. <i>העוסק בתורת עולה כו'</i> – מנחות קי, א. <i>נפש הוא כו' הנשמה</i> – זח\"א פג, ב. <i>שצדיק ממנו בולע</i> – ברכות ז, ב. <i>אמר דוד המלך ע\"ה נגד דואג כו'</i> – רד\"ק לתהלים קט, ו. <i>וכמ\"ש מוהרש\"א</i> – ? ה\"ה דברי רש\"י יומא עב, ב ד\"ה ותרעא. <i>דלא פרחית לעילא</i> – תקו\"ז ת\"י כה, ב.\n----- הערות וציונים -----\n<i>תפלתו לחטאה</i> – ראה לעיל סי' קכ.\n<i>שמבלבלין אותו כו'</i> – ראה מדל\"י סי' פד (צה), וכן שם סי' ד (ג) ומז (נג), ע\"פ זח\"ב רמה, ב.\n<i>בניו שהם מע\"ט</i> – להעיר מתנחומא נח ב.\n<i>היצה\"ר מלוה כו' להתפאר</i> – ראה צוה\"ר סי' עד."]]],[300010192,"קס\n\n<b>עוד</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;מהבעש\"ט&gt; ביאור סוד א\"ב כו' ואיך שצריך לעשות בכל תיבה הכנעה והבדלה והמתקה, ר\"ל כי דיני ש\"ך ופ\"ר הרמוז בתיבת אדני דפתיחת תפלת י\"ח, כל הכוונות שיש שם צריך לכוין בכל תיבה ודיבור להמתיק הדינין. כי אות א' הוא סוד פלא, ונתלבש באות ב' שהוא ב' אלפין, <span data-k=\"sm\">[וכן באות ג' ג' אלפין]</span>, עד אות ת' ד' מאות אלפין, וכל <span data-k=\"sm\">[מה]</span> שנתרחק האות נתרחק מהחיות ונתלבש בקליפות עד מלכות שבמלכות ששם מחשבות <span data-k=\"sm\">[רעות ו]</span>זרות <span data-k=\"sm\">[וכו']</span>. וכאשר יתן אל לבו גלות השכינה שהיא ניצוץ השכינה מלובש בתוך כיעור הקליפות <span data-k=\"sm\">[הזה]</span>, יתחרד חרדה גדולה, ואז יתפרדו כל פועלי און ונעשה יחוד יראה עם נורא ונתברר ניצוץ הקדוש ונתחבר למעלה אל החיות בסוד והחיות רצוא ושוב, והוא גאולה מהשביה. וזהו הכנעה, כאילו <span data-k=\"sm\">[הוא]</span> אינו מדבר רק השכינה. והבדלה להפריד הקליפות כו'. והמתקה להעלותן להמתיקן בשרשן כו', <span data-k=\"sm\">[ודפח\"ח]</span>. ושמור כלל גדול זה <span data-k=\"sm\">[והבן]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> א (תשכט</b>,<b> ב אות יג)</b>\n<i>דיני ש\"ך ופ\"ר הרמוז בתיבת אדני כו'</i> – פע\"ח שער העמידה פ\"א. <i>אות א' הוא סוד פלא</i> – זח\"ג קצג, ב. תקו\"ז ת\"ע קלה, א. <i>יתפרדו גו'</i> – תהלים צב, י. <i>והחיות רצו\"ש</i> – יחזקאל א, יד.\n----- הערות וציונים -----\nראה לקמן סי' קסג.\n<i>הכנעה הבדלה והמתקה</i> – ראה לעיל סי' כח-א ולקמן סי' שב-א. ועיין לקמן סי' קפח ובהערות שם.\n<i>אות א' כו' וכל מה שנתרחק כו'</i> – ראה לעיל סי' מה ובהערות שם.\n<i>גלות השכינה כו' גאולה מהשביה</i> – ראה לעיל סי' נג, ולקמן סי' רכב ורפז.\n<i>יחוד יראה עם נורא</i> – ראה לעיל סי' צג-ג ובהערות שם."]]],[300010193,"קסא\n\n<b>עוד</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;מהבעש\"ט&gt; ביאור דברי התוס' <span data-k=\"sm\">[בפ\"א דשבת]</span> הדן דין אמת לאמתו לאפוקי דין מרומה <span data-k=\"sm\">[וכו']</span>. כי ב' מדות חסד וגבורה לווין זה לזה ונכללין זה מזה, וכאשר מתחברין זה לזה נעשה תפארת כו', וע\"י הדיינים שהם סוד ג' רישין כו', לכך צריך שיהיו שונאי בצ\"ע שהוא אותיות שניות מן האבות אברהם כו', וכאשר מברר ומייחד במחשבה, נעשה אמת לאמתו. והנה למטה יש ג\"כ סוספיתא דדהבא וכספא, שהם חוטפין וגוזלין זה מזה, וע\"י הדיין נתברר כנ\"ל, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> א (תשל</b>,<b> א אות יד)</b>\n<i>התוס'</i> – שבת י, א ד\"ה דין. <i>שונאי בצ\"ע</i> – יתרו יח, כא. <i>סוספיתא דדהבא</i> – זח\"ב רכד, ב. שם רלו, ריש ע\"ב. <i>וכספא</i> – זח\"ג קא, ריש ע\"ב.\n----- הערות וציונים -----\n<i>וכאשר מתחברין זל\"ז נעשה תפארת</i> – זח\"ג כח, סע\"א ושם שב, א.\n<i>וע\"י הדיינים כו'</i> – ראה דמ\"א פ' וירא ד\"ה או יאמר וירא גו' וירא והנה גו': כל הענין שאחריו משתעי מענין דיינים ודיניהם כו' וע\"ד הסוד כו' והוא שכתב הזוה\"ק מאן אינון שלשה אנשים אברהם יצחק ויעקב (זח\"א צח, א במדה\"נ ושם צח, ב) וכמו ששמעתי בפירוש מן אא\"ז נ\"ע זלל\"ה כי אברהם יצחק ויעקב הם תלת דיינים והסימן הוא כי אותיות שניות מן שמות האבות הוא בצע והוא רמז על הדיינים שצ\"ל שונאי בצע כו'. ועוד שם בד\"ה והנה שלשה אנשים: ע\"ד דאיתא בזוה\"ק והנה שלשה אנשים אילין תלת רישין והיינו ג' מדות חג\"ת כידוע.\n<i>סוד ג' רישין</i> – ראה זח\"ג רפט, ב וע\"ח שי\"ט פ\"ט.\n<i>מברר ומייחד במחשבה</i> – להעיר מזח\"ב רנד, סע\"ב דבמחשבה אתברירו, ומבואר בע\"ח שי\"ט ספ\"ה ושם של\"ט פ\"א, ובלקו\"י סי' קנה."]]],[300010194,"קסב\n\n[<b>עוד</b> <span data-k=\"sm\">שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;מהבעש\"ט&gt; ביאור התוס' <span data-k=\"sm\">[דפ\"ק דר\"ה]</span> בשם ירושלמי יומא חד בעי איכוון, כי צריך להעלות במחשבתו ממטה למעלה בסוד רפ\"ח ניצוצין כו', וכל מ\"ז הוא במלכות שבמלכות, ובבוא המ\"ז צריך לפחד ולירא ממנה, וע\"י היראה מחבר יראה עם נורא ומברר ניצוץ הקדושה מתוך הקליפה שהיא המ\"ז.\n<b>והנה</b> זה התנא שהיה מחשבתו ברורה וצלולה ממחשבות זרות לא מצא <span data-k=\"sm\">[מקום]</span> להעלות ממטה למעלה כ\"א ע\"י שעלה מחשבתו לימנות קורות ביתו או אפרוחים כו', ובפרטות אלו צריך לימוד כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> ריש ע</b>\"<b>ב (תשל</b>,<b> א אות טו)</b>\n<i>התוס' דפ\"ק דר\"ה</i> – דף טז, ב ד\"ה ועיון תפלה. <i>בשם ירושלמי</i> – ברכות פ\"ב סה\"ד.\n----- הערות וציונים -----\nראה לעיל סי' קס (ובהערות שם) ולקמן סי' קסג."]]],[300010195,"קסג\n\n<b>עוד</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;מהבעש\"ט&gt; ביאור הפסוק ויאמר אל שרי אשתו הנה נא ידעתי כי אשה יפת מראה את וגו' <span data-k=\"sm\">[והרגו אותי וגו']</span> אמרי נא אחותי את <span data-k=\"sm\">[וגו']</span>, וחיתה נפשי בגללך. והקשה, נ\"א מיותר, ושאר ספיקות. וביאר, כי נא פירושו שירדה מלכות נ' מדריגות מן החיות היא א', שירדה כל כך וחשקה לחזור להתקרב אל החיות שהיא א' כו'. והנה קודם הפורעניות באה המחשבה <span data-k=\"sm\">[רעה ו]</span>זרה, כמו מחשבת זנות או מחשבות עבודה זרה, רק שמחשבת זנות מורה על אחרים ומחשבת עבודה זרה על עצמו, או זה עונש מיתה משמים <span data-k=\"sm\">[וזה כו']</span>. והתקנה לתקן מחשבה זו, שיתן <span data-k=\"sm\">[לב]</span> &lt;דעתו&gt; שיש בתוך המ\"ז זו ניצוץ השכינה <span data-k=\"sm\">[שבתוך הקליפה מחמת השבירה]</span> כנודע, וישתף עצמו עם השכינה ויראה ורעד יבוא <span data-k=\"sm\">[בו]</span>, ואז יתפרדו כל פועלי און ונעשה יחוד יראה ונורא ונצול גם הוא ממיתה.\n<b>ובזה</b> יובן הנה נא ידעתי כי אשת יפת מראה את וגו', שע\"י שנכנס בו מחשבת זנות ועי\"ז חש והרגו אותי, לכך אמרי נא אחותי את, וכמ\"ש בזוהר אמור לחכמה אחותי <span data-k=\"sm\">[את וכו']</span>. ודרש זה מיתור א\"ת, ר\"ל שישתף א\"ע עם השכינה שנקראת אחותי, ועי\"ז וחיתה נפשי בגללך <span data-k=\"sm\">[ודפח\"ח. . .]</span>.\n<b>ובזה</b> ביאר אם ככה את עשה לי וגו', שיש לכוין שם בקדושת כתר ככ\"ה ר\"ת כ'תר כ'ל ה'כתרים, והוא סגולה <span data-k=\"sm\">[נפלאה]</span> להעלות הנשמות ממעמקים כו', <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> ב (תשל</b>,<b> א אות טז)</b>\n<i>ויאמר אל שרי גו' אמרי נא גו'</i> – לך לך יב, יא-יג. <i>וישתף עצמו עם השכינה</i> – זח\"ג קי, ב. <i>ויראה ורעד</i> – ע\"פ תהלים נה, ו. <i>יתפרדו גו'</i> – תהלים צב, י. <i>וכמ\"ש בזוהר</i> – זח\"א פא, סע\"ב. <i>אמור לחכמה גו'</i> – משלי ז, ד. <i>אם ככה גו'</i> – בהעלתך יא, טו.\n----- הערות וציונים -----\nראה לעיל סי' קס.\n<i>שירדה מלכות כו'</i> – ראה לעיל סי' מה ובהערות שם.\n<i>או זה עונש מיתה משמים כו'</i> – ראה צ\"פ פ' בא לז, ד (קמב, ב): דשמעתי ממורי פירוש הפסוק פן יהרגוני על דבר אשתי (וירא כ, יא בצירוף לשון תולדת כו, ז) כי בעלות לאדם מחשבות רעות אז דנין אותו (ראה זח\"ב רמה, ב) וכאשר נפלה עליו מורא ופחד עי\"ז נעשה יחוד נורא ויראה ואז יתפרדו כל פועלי און וכו' ודפח\"ח. ובבפ\"י פ' נח כ, רע\"ג (קב, ב): דשמעתי ממורי פי' הפסוק עתה ידעתי כי אשה יפת מראה את ועתה פן יהרגוני וכו', כי כאשר נכנס בו הרהורי אשה הוא בסכנת מות וכו' והתקנה שידע שהשכינה היא בתוך הקליפות ויתחרד חרדה גדולה ואז נעשה יחוד יראה ונורא ונתפרדו כל פועלי און וניצול וכו' ודפח\"ח.\n<i>שיש בתוך המ\"ז זו ניצוץ השכינה</i> – ראה מדל\"י סי' קז (קיח) [וקטע משם לקמן סי' שצה-ב].\n<i>שבתוך הקליפה מחמת השבירה</i> – ראה לעיל סי' קס, ומדל\"י סי' עח (פט).\n<i>וישתף עצמו עם השכינה</i> – ראה מדל\"י סי' מ (מג).\n<i>יחוד יראה ונורא</i> – ראה לעיל בהערות לסי' צג-א.\n<i>כמ\"ש בזוהר כו'</i> – ראה ג\"כ זח\"א קיא, סע\"ב ואילך."]]],[300010196,"קסד-א\n\n[<b>עוד</b> <span data-k=\"sm\">שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;מהבעש\"ט&gt; כשרואה שיש עליו איזה דינין, אזי ילמוד בבוקר בדביקה וחשיקה שידבק את עצמו אל פנימיות אור א\"ס שבתוך האותיות כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> ב (תשל</b>,<b> ב אות יז)</b>\n<i>ד' אמות של הלכה</i> – ברכות ח, א. <i>שהוא מלכות</i> – זח\"ג ר\"מ כז, ב. תקו\"ז יז, א.\n----- הערות וציונים -----\n<i>כשרואה שיש עליו איזה דינין</i> – ראה לעיל סי' צד ובהערות שם."]]],[300010197,"קסד-ב\n\n<b>עוד</b> <span data-k=\"sm\">[שמעתי </span><i>ממנו</i><span data-k=\"sm\">]</span> &lt;פי'&gt; שיעשה אלו ד' אמות של הלכה שהוא מלכות שירדה כו' ויוציא ס\"ת וג' דיינין בסוד ג' רישין ג' אהיה כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>שם</b>\n----- הערות וציונים -----\n<i>עוד שמעתי כו'</i> – לכאורה זה מאמר בפ\"ע, אבל לפי המבואר לעיל סס\"י עו בענין ד' אמות של הלכה שאור המקיף הבית להציל מכל הקליפה נקרא אהי\"ה, י\"ל דשייך להנ\"ל.\n<i>הלכה שהוא מלכות</i> – ראה זח\"ב קטז, ריש ע\"ב וזח\"ג רפא, סע\"ב.\n<i>ג' דיינין בסוד כו'</i> – להעיר מסידור האריז\"ל להר\"ש, סדר המלקות (ח\"ג דף מח, ב).\n<i>בסוד ג' רישין</i> – ראה לעיל סי' קסא.\n<i>ג' אהי'</i> – במילוי יודי\"ן ובמלוי אלפי\"ן ובמלוי ההי\"ן; ראה ע\"ח שט\"ז פ' ב-ג."]]],[300010198,"קסה\n\n<b>מורי</b> &lt;הבעש\"ט&gt; עשה עליית נשמה וראה איך מיכאל אפוטרופסא רבא דישראל המליץ עבור ישראל שכל חוב שלהם הוא הכל זכות, כי כל שעושין פסלנות ושאר דברי חוב הכל כדי שיוכל לעשות שידוך עם תלמיד חכם או לעשות צדקה וכיוצא בזה, הכל מוכרחים כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י רב</b>,<b> ב [השמטה מפ</b>'<b> דברים] (תריד</b>,<b> ב)</b>\n<i>מיכאל אפוטרופסא רבא דישראל</i> – זח\"ב רנד, א (ושם קלט, א).\n----- הערות וציונים -----\nזהו קטע מסי' רצז דלקמן, עיי\"ש."]]],[300010199,"קסו\n\n<b>&lt;צעק</b> לבם אל ה'&gt; צריך אדם ללמוד ולהרגיל א\"ע שיתפלל אפילו זמירות בקול נמוך, ויצעק בלחש <span data-k=\"sm\">[ויאמר הדבר בין בזמירות ובין בלימוד]</span> בכל כוחו, &lt;וכן בלימוד, שנאמר&gt; <span data-k=\"sm\">[כדכתיב]</span> כל עצמותי תאמרנה וגו', והצעקה שתהיה מחמת דביקות תהיה בלחש.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ב</b>,<b> ג (סי</b>'<b> ו) [צוה</b>\"<b>ר סי</b>'<b> לג]</b>\n<i>צעק לבם גו'</i> – איכה ב, יח. <i>כל עצמותי גו'</i> – תהלים לה, י.\n----- הערות וציונים -----\n<i>בקול נמוך ויצעק בלחש</i> – ראה ברכות כד, ב (המשמיע קולו כו') ושם לא, א (עה\"פ וקולה לא ישמע). אליהו רבה פכ\"ח. זח\"א רט, סע\"ב ואילך (ובהג' החיד\"א שם). זח\"ב רב, א. ס' בית אלקים להמבי\"ט שער התפלה פ\"ו. של\"ה, עניני תפלה ערך קול. ובריש שער הכונות, ופע\"ח שער עולם העשי' פ\"א שהאריז\"ל לא היה מרים בקולו בתפלתו אפילו בזמירות ובתפלה דמיושב כו' עיי\"ש. ועיין בנו\"כ השו\"ע או\"ח סי' קא סעיף ב. וראה לקמן סוף סי' רכו וסי' רלג.\n<i>בכל כחו כדכתיב כו'</i> – ראה עירובין נד, רע\"א. וראה צוה\"ר סי' לד, לה, נא, סוף סי' נח, ס, וסוף סי' עה.\n<i>והצעקה כו' בלחש</i> – להעיר מזח\"א רי, רע\"א. וראה זח\"ב יט, סע\"ב. ולקמן סס\"י רכו וסי' רלג."]]],[300010200,"קסז\n\n<b>בדורותינו</b> שאנו במעט השכל, מאד מאד צריך להתחזק &lt;ביראת ה'&gt; <span data-k=\"sm\">[ביראתו ית']</span>, ולהתבודד מחשבתו תמיד ביראה ובאימה. ואפילו בעת הלימוד טוב לנוח מעט בכל פעם מלמודו ולהתבודד מחשבתו, ואף שמחמת זה יתבטל קצת מלמודו, כי לא המדרש כו'.<i>[ftnref_1_יט]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ג</b>,<b> ב (סי</b>'<b> כט)</b>\n<i>לא המדרש כו'</i> – אבות פ\"א מי\"ז. <i>וכמ\"ש בגמרא</i> – ברכות כ, א. <i>ואם הראשונים כאנשים וכו'</i> – שבת קיב, ב.\n----- שולי הגליון -----\n[ftn_1_יט]) <i>במקורו יש המשך</i>: וכמ\"ש בגמרא דורות הראשונים שמסרו נפשם על קדושת השם מגודל דביקותם נעשה להם נסים, ובדורות האחרונים אע\"פ שלומדים תורה יותר הרבה מהראשונים לא זכו כ\"כ לניסים, וקל וחומר בן בנו של קו\"ח שאנחנו בדורות הללו שנתמעטו הלבבות מכל וכל, ואם הראשונים כאנשים וכו', פשיטא שההכרח לנו להתחזק ביראתו ואהבתו ית' בדביקות גדול.\n----- הערות וציונים -----\nעיין היטב בס' צוה\"ר סי' כט-ל ובהערות שם."]]],[300010201,"קסח\n\n<b>יחשוב</b> קודם התפלה שהוא מוכן למות מאותה תפלה מחמת הכוונה, ויש מכוונים כ\"כ עד שעל פי דרך הטבע הי' יכול למות בחמשה או ששה תיבות שאומר לפניו יתברך, וכשיחשוב כך בוודאי יאמר בלבו למה לי איזה פניה וגאוה באותה תפלה, כיון שבדעתו למות אפי' אחר &lt;כמה&gt; <span data-k=\"sm\">[ב' וג']</span> תיבות. ובאמת שהוא חסד גדול שהשי\"ת נותן לו כח ומשלים התפלה והוא חי.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ג</b>,<b> ב (סי</b>'<b> לא) [צוה</b>\"<b>ר סי</b>'<b> מב]</b>\n----- הערות וציונים -----\n<i>מוכן למות כו'</i> – להעיר מהכוונות למס\"נ בק\"ש (זח\"א קכד, ב במדה\"נ. תקו\"ז י, ב. ב\"ח טאו\"ח ריש סי' סא. ועוד) ובנפ\"א (זח\"ב ר, ב ושם רב, ב. זו\"ח תרומה מב, א. שער הכונות ופע\"ח בענין נפ\"א. ועוד)."]]],[300010202,"קסט\n\n<b>מעלה</b> גדולה כשאדם מחשב <span data-k=\"sm\">[ומהרהר]</span> תמיד <span data-k=\"sm\">[בלבו]</span> שהוא אצל הבורא יתברך, והוא מקיף אותו מכל צדדיו, &lt;כמ\"ש אשרי אדם לא יחשוב ה', פי' כשרגע אינו מחשב בדביקות הש\"י, לו עון&gt;, ויהיה דבוק כ\"כ שלא יהא צריך ליישב א\"ע בכל פעם שהוא אצלו ית', רק שיראה הבורא ית' בעין השכל, ושהוא יתברך מקומו של עולם, <span data-k=\"sm\">[והכונה שהרי הוא היה קודם שברא העולם, והעולם הוא עומד בבורא ית']</span><i>[ftnref_1_כ]</i>. &lt;וכן האדם שנקרא עולם קטן, ויקיים שויתי ה' לנגדי תמיד כמ\"ש בש\"ע א\"ח סימן א'&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ד</b>,<b> סע</b>\"<b>ב (סי</b>'<b> נד)</b>\n<i>אשרי אדם גו'</i> – תהלים לב, ב. <i>ושהוא ית' מקומו של עולם</i> – בר\"ר סח, ט. <i>האדם שנקרא עולם קטן</i> – תנחומא פקודי ג. <i>שויתי ה' גו'</i> – תהלים טז, ח.\n----- שולי הגליון -----\n[ftn_1_כ]) <i>במקורו יש המשך המובא לקמן סי' ר</i><i>א</i><i> עיי\"ש</i>.\n----- הערות וציונים -----\nסימן זה הוא הרישא מהדרוש בלקו\"י, וההמשך הובא לקמן סי' ר-א.\n<i>שהוא אצל הבורא ית' כו'</i> – ראה צוה\"ר ריש סי' קלז.\n<i>וכמ\"ש אשרי אדם לא יחשוב כו'</i> – ראה תוי\"י פ' בהר קיג, ד (תכו, ב) בשם הרה\"מ מבאר, שלא נמצא לו עון אחר זולת זה שאין מחשבתו דבק בו ית', וז\"ש לא יחשוב ה' לקיים שויתי ה', אצלו נחשב זה לעון.\n<i>כשרגע אינו מחשב בדביקות הש\"י לו עון</i> – להעיר מלעיל סי' קמט, עיי\"ש בהערות.\n<i>שיראה הבורא ית' בעין השכל</i> – ראה לקמן סי' רלב. ולבטוי עין השכל ראה זח\"ב קטז, סע\"ב וזח\"ג רל, סע\"ב, ולקמן סי' רי ורלב."]]],[300010203,"קע\n\n<b>ידע</b> מה בחשוכא <span data-k=\"sm\">[ונהורא עמה שרא]</span>, ר\"ל הקב\"ה &lt;מחבב את&gt; <span data-k=\"sm\">[מקושר עם]</span> זה האדם שעושה את עצמו למה, ר\"ל ללא כלום, ולא עוד אלא אפילו בחשוכא, כלומר אפילו כשהוא בין עניים הנק' חשוכים, הוא משפיל א\"ע נגדם מגודל ענוה, עם זה האדם <span data-k=\"sm\">[הקב\"ה מקושר. ואם תאמר שאפשר שאדם זה באמת הוא נמי שפל הערך כמותם, וא\"כ מאי רבותיה בענוותנותו, לזה אמר]</span> ונהורא עמיה שרא <span data-k=\"sm\">[ר\"ל שהוא אדם גדול מאד, ואעפ\"כ משפיל עצמו]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ו</b>,<b> ב (סי</b>'<b> קא)</b>\n<i>ידע מה גו'</i> – דניאל ב, כב. <i>עניים הנק' חשוכים</i> – ביצה לב, ב.\n----- הערות וציונים -----\n<i>הקב\"ה מקושר כו'</i> – כלומר ידע לשון חיבור והתקשרות, ע\"ד והאדם ידע את חוה (ראה תקו\"ז ריש תס\"ט צט, א, וצוה\"ר סי' צד וצט).\n<i>למה ר\"ל ללא כלום</i> – ראה לעיל סי' לא ובהערות שם.\n<i>אפילו כשהוא בין עניים כו'</i> – ראה צוה\"ר סי' יב ומח."]]],[300010204,"קעא\n\n<b>איזהו</b> גבור הכובש את יצרו, קשה דהל\"ל מי הוא גבור. י\"ל כמו בעסקי העולם השומר בחדר לשמור סחורה ושומע גנב חותר, יש צועק ועי\"ז בורח הגנב, ויש מכין שלשלאות וכשבא הגנב לחדר הוא אוסרו בכבלי ברזל. וכן בצדיקים יש אינו מניח לקרב אצלו שום הרהור, &lt;וכדר' עמרם חסידא&gt;, ויש לוקח החמדה או אהבה ויראה רעה לעבודת ה' לאהבה וליראה אותו ית'. וז\"ש איזהו גבור יותר, הכובש את יצרו ומדותיו וחמדתו לעבודת השי\"ת.<i>[ftnref_1_כא]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>קיצור לקו</b>\"<b>י ג</b>,<b> ד (סי</b>'<b> מג)</b>\n<i>איזהו גבור כו'</i> – אבות פ\"ד מ\"א. <i>טוב ארך אפים מגבור</i> – משלי טז, לב. <i>וכדר' עמרם חסידא</i> – קידושין פא, א. <i>היצה\"ר הנקרא אף</i> – זו\"ח רות עח, ג.\n----- שולי הגליון -----\n[ftn_1_כא]) <i>המאמר במילואו</i>: איזהו גבור הכובש את יצרו. יש לדקדק לשון איזהו משמע שמדבר משני בני אדם ושואל איזה מהם גבור, והוה ליה למימר מי נקרא גבור, ועוד יש לדקדק שמלשון הפסוק משמע איפכא, שהכתוב אומר טוב ארך אפים מגבור, משמע מי שהוא מאריך אף דהיינו הכובש את יצרו חשוב יותר מגבור.\nויש לומר דיש שני מיני צדיקים, אחד שאין מניח היצר הרע לקרב אצלו כלל, וקודם בואו אליו מרחיקו מעליו. ויש צדיק שיניחו לבוא אצלו, אך כובשו שלא להסיתו לעבירה. למשל כשהיצר הרע מסיתו לחמדה, אומר ליצר הרע אעשה כדבריך שאלך אחר חמדה, אך אחר חמדה של מצוה, והולך ולומד תורה בחשק גדול ובחמדה גדולה, וכן בכל דבר שמסיתו למדה רעה הוא לוקח אותה המדה לעבודת הבורא. אך מי מהם יותר משובח, [הצדיק] הב' יותר משובח.\nוהוא על דרך השכל, למשל אדם שישן בחנות לשמור סחורה, ולא היה הדלת סגור בבריח חזק, ושמע באמצע הלילה שגנב אחד בא ועושה תחבולות לפתוח הדלת, וכאשר שמע זה היה ירא לנפשו והתחיל לצעוק בקול גדול לבני ביתו שיבואו שירא מהגנב, וברח הגנב מחמת הצעקה.\nומעשה כזה אירע לאיש אחר, ואותו אחר כששמע שגנב בא שתק כמו שאינו שומע, וכשבא הגנב לחנות בפנים תפס אותו ואסרו בנחושתיים, אבל לא היה רוצה לצעוק כדי שיברח הגנב, כי אמר בדעתו לכשיברח הגנב שמא יבא עוד בלילה זה או בלילה אחר ושמא אהיה נרדם בשינה ולא אשמע ויעשה מה שלבו חפץ, אך אעשה לו דבר שלא יוסיף לגנוב עוד, כי בודאי יפול עליו פחד שלא יתפסו אותו ויענש ביסורים קשים כבראשונה, והנמשל מובן מאליו.\nוזהו פירוש איזהו גבור וכו', כלומר איזה מב' צדיקים הללו נקרא גבור, הכובש וכו', ולא זה שאינו מניח היצר הרע לקרב אצלו כלל, שנאמר טוב ארך אפים [מגבור], ר\"ל זה מי שמאריך האף, דהיינו היצר הרע הנקרא אף, שהיצר הרע תמיד אצלו, ועם כל זה הוא כובש אותו, זהו טוב ומשובח יותר מהצדיק הא' שאינו מניחו לקרב אצלו כנ\"ל. ומושל ברוחו, ר\"ל מי שהוא מושל על היצר הרע וכובש אותו, הוא יותר משובח מלוכד עיר, כי מי שהוא לוכד עיר בודאי מגרש את האנשים תחלה ואחר כך בא לעיר, אבל זה אינו מגרש את היצר הרע רק כובשו.\n----- הערות וציונים -----\nראה לקמן בהוספות סי' קטז. ולהעיר משם סי' כא. וראה ג\"כ צ\"פ פ' שמות יא, ג (נג, א).\nהסיפא בפנים הם דברי הרב המלקט, וכנראה מיוסד על סי' סד דלעיל."]]],[300010205,"קעב\n\n<b>&lt;כתב&gt;</b> <span data-k=\"sm\">[ואמר]</span> <i>הבעש\"ט</i>, מ\"ש האר\"י ז\"ל שהלכה ר\"ת הריעו לה' כל הארץ, ר\"ל שלהליכה זו צריך לשבר כל הארציות וחומריות <span data-k=\"sm\">[והלכה זו אפשר הוא כפשוטה לעסוק בה]</span>, ונתן לנו מנסה א' הוא היצה\"ר לנסותינו בה, כדרך שמנסין התינוק בהלכה, והוא מקשה <span data-k=\"sm\">[ומפרק]</span> ומבלבל &lt;הפשיטות&gt; <span data-k=\"sm\">[הפשוט]</span> להסיבנו לדרך עקום, וכשאנו חכמים ואין אנו מניחים אותו לנצחינו אזי יש להש\"י תענוג גדול, &lt;כמשל בן נחמד וחרוץ שיש לאביו תענוג כשהאורח מנסהו ומקשה לו והבן אינו מניח א\"ע להנצח&gt;.<i>[ftnref_1_כב]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כו</b>,<b> ד (יד</b>\"<b>א פל</b>\"<b>ה)</b>\n<i>מ\"ש האר\"י ז\"ל</i> – לקו\"ת, ושער הפסוקים, תהלים ק. <i>הריעו לה' גו'</i> – תהלים ק, א. <i>רוח סערה גו'</i> – תהלים קמח, ח. <i>וכמ\"ש בזוהר</i> – זח\"ב קסג, א.\n----- שולי הגליון -----\n[ftn_1_כב]) <i>במקורו יש המשך</i>: וכשרואה היצר שיש להש\"י תענוג, והוא נברא ג\"כ למען הש\"י כמ\"ש רוח סערה עושה דברו, וכמ\"ש בזוהר במשל הזונה הידוע, הוא מכוין א\"ע לנסות יותר ומסבב להעקימנו יותר, וזה סיבת התגברות המחשבות זרות בתפלה. כל זה אמר הרב ר' בער זלה\"ה.\n----- הערות וציונים -----\n<i>צריך לשבר</i> – כלומר הריעו לשון תרעם בשבט ברזל (תהלים ב, ט); זח\"ג רלא, ב. וראה לקמן סי' שכ ד\"ה עוד י\"ל הלכה. ולהעיר מלקמן הוספות סי' סח-סט. ועיין סידור עם פיה\"מ ע\"פ דא\"ח לאדה\"ז דף מד סע\"ד ואילך.\n<i>כדרך שמנסין התינוק כו' כמשל בן נחמד כו'</i> – ראה לקמן סי' רז-ב וצוה\"ר סי' קלח.\n<i>היצר </i>. .<i> כמ\"ש רוח סערה</i> – ראה זו\"ח רות עה, סע\"ד."]]],[300010206,"קעג\n\n<b>שרפים</b> עומדים ממעל לו, פירוש שרפים עומדים הם הצדיקים שבוער בלבם אהבת הבורא <span data-k=\"sm\">[הוא]</span> מחמת שממעל לו &lt;חלק אלוה ממעל&gt;. ע\"ד דע מה למעלה ממך.<i>[ftnref_1_כג]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יט</b>,<b> א (סי</b>'<b> רכט)</b>\n<i>שרפים גו'</i> – ישעי' ו, ב. <i>חלק אלו</i>-<i>ה ממעל</i> – איוב לא, ב. <i>דע מה כו'</i> – אבות פ\"ב מ\"א. <i>אנא סימנא בעלמא</i> – זח\"א רכה, א. זח\"ג טו, א.\n----- שולי הגליון -----\n[ftn_1_כג]) <i>המשך במקורו</i>: תדע כי האדם הוא חלק אלוה ממעל, וכשהוא מדבק מחשבתו למעלה יכול לידע מה שנעשה למעלה, כי כל הדברים הנעשים למעלה עוברים במחשבתו כמו שאמר רשב\"י ע\"ה אנא סימנא בעלמא, פי' כל המדות שמתעוררים למעלה הם מתעוררים למטה בצדיק. וזה פירוש שרפים עומדים ממעל לו.\n----- הערות וציונים -----\nראה לעיל סס\"י קמה. להעיר ממדל\"י סי' קט (קכא), קכ (קל) וקעז (קפב)."]]],[300010207,"קעד\n\n<b>בגמרא</b> דבר גדול ודבר קטן, דבר גדול מעשה מרכבה ודבר קטן הויות דאביי ורבא. &lt;וק'&gt; ח\"ו שיקראו להויות דאביי ורבא דבר קטן כי זה עיקר תורתינו הנאמרה בסיני <span data-k=\"sm\">[מפי הבורא ית\"ש, ואף גם שקראו למעשה מרכבה דבר גדול, כי הלא בזמנינו רובם כמעט כולם בקיאים בכתבי האר\"י ז\"ל שגילה כל עניני מעשה מרכבה]</span>.\n<b>אלא</b> &lt;ה\"פ&gt;, באמת הן תורה הנגלית הן הנסתרות הכל סוג א', כי הכל הולך אחר כוונת האדם <span data-k=\"sm\">[בה]</span>. אם &lt;כוונתו&gt; <span data-k=\"sm\">[כוונת האדם]</span> לידע עניינה &lt;לבד&gt;, אינו זוכה לשום דבר, <span data-k=\"sm\">[כמ\"ש בראשית חכמה]</span> שעליו נאמר וכל חסדו כציץ השדה. אבל אם כוונתו שחושק &lt;לדביקות הש\"י&gt; <span data-k=\"sm\">[לדבק בהש\"י]</span> להיות מרכבה לו, ואין לזה דרך כ\"א ע\"י התורה והמצות, אזי הן ע\"י תורה &lt;נגלות&gt; <span data-k=\"sm\">[הנגלית]</span> הן ע\"י תורה הנסתרות <span data-k=\"sm\">[יתדבקו א\"ע, שע\"י הנסתרות]</span> יזכה &lt;להיות מרכבה לו ית'&gt; <span data-k=\"sm\">[לדביקות נפלא יותר]</span>.\n<b>&lt;וז\"ש&gt;</b> <span data-k=\"sm\">[וזה לדעתי כוונתם]</span> דבר קטן הויות דאביי ורבא, &lt;ר\"ל מי שלומד לחדוד לתענוג וצורך עצמו הוא דבר קטן, פירוש שעובד הש\"י בדבר קטן וכאין הוא, שהרי הוא רק כמי שחושק לדבר חכמה אחרת&gt; <span data-k=\"sm\">[ר\"ל השכל שיש בפלפול הגמרא שהוא הויות וקושיות דאביי ורבא לחדודי הוא דבר קטן, ר\"ל מי שלומד בשביל שכל זה שיש לו תענוג מזה, הוא קטן וכאין הוא, ואינו נוגע להש\"י, רק כמו שחושק בדבר חכמה אחרת]</span>. אבל מי שחושק להיות מרכבה &lt;לו ית'&gt; <span data-k=\"sm\">[להש\"י]</span> ע\"י התורה הוא דבר גדול, וזהו דבר גדול מעשה מרכבה, ר\"ל לעשות עצמו מרכבה להשי\"ת ע\"י התורה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כא</b>,<b> ד (יד</b>\"<b>א פ</b>\"<b>ח)</b>\n<i>דבר גדול כו'</i> – סוכה כח, א. <i>כמ\"ש בר\"ח</i> – שער האהבה פ\"ח (מתקוזו\"ח צז, ג). <i>וכל חסדו גו'</i> – ישעי' מ, ו.\n----- הערות וציונים -----\nסימן זה הוא המשך מסי' רלח-ב דלקמן עיי\"ש. ורג\"כ לקמן סי' שכ ד\"ה וענין למוד לשמה.\n<i>להיות מרכבה לו</i> – ראה לקמן סי' שנ ותכו. רג\"כ סי' שיט ד\"ה כי הנה בנין המשכן.\n<i>ע\"י התורה והמצוות כו' לדביקות כו'</i> – להעיר מפי' היעב\"ץ לאבות ד, ב (הובא בר\"ח שער היראה פ\"ד), ור\"ח שער האהבה פ\"י.\n<i>מי שלומד כו' וצורך עצמו כו'</i> – להעיר מברכות יז, א ושם פרש\"י ד\"ה העושה. תוס' פסחים נ, ב ד\"ה וכאן. נתיבות עולם למהר\"ל, נתיב התורה פ\"ז."]]],[300010208,"קעה\n\n<b>ביאור</b> משנה דע מה למעלה ממך עין רואה ואזן שומעת כו'. כי יש ראיה ושמיעה וידיעה, ראיה גדול משמיעה ושמיעה מידיעה. והנה אם יבוא א' ויכפור לומר שאין ירושלים בעולם מפני שלא ראה ולא שמע ממנה, יש אלפים אנשים שיכחישוהו שהם ראו ושמעו ממציאותה.\n<b>וז\"ש</b> משה לפרעה כה אמר ה' שלח את עמי ויחוגו לי במדבר, ויאמר פרעה מי ה', פי' לא ראיתיו, וא\"ת כי הוא רואה ואינו נראה, אשר אשמע בקולו, פי' היה לי לשמוע קול דיבור נבואה ממנו כמו אתם. וא\"כ כיון שאין לי ראיה ושמיעה ממנו, ואתם רוצים שיהיה לי אמונה בו מצד ידיעה, לא ידעתי את ה' וגם את ישראל לא אשלח. והשיבו משה ואהרן, אלהי העברים נקרא עלינו, פי' אע\"פ שאתה לגשמותך אין לך ראיה ושמיעה ממנו, מ\"מ אנחנו שמענוהו, ותדע לך כי נלכה נא דרך שלשת ימים במדבר, ומ\"ט אמר דרך ג' ימים, שא\"א לך להשיג פה המדבר והר אלהים, לא ע\"פ ראיה, אפי' ע\"י כלי מחזה, כמו ששם לבן דרך ג' ימים בין הצאן, ולא על ידי שמיעת קול ממנו, דהיינו הבת קול היוצאת מהר חורב, ואפ\"ה לא תוכל להכחיש ולומר שאין מדבר סיני והר חורב בעולם מפני שיש אנשים שראו ושמעו ומוכרח אתה להאמין מצד הידיעה, כן מוכרח אתה להאמין בהש\"י.\n<b>וז\"ש</b> דע מה למעלה ממך עין רואה, כי מצד שהוא עין ראוי שיסתכל ויראה מסוף העולם ועד סופו ולראות השגת אלהות, ואוזן ראוי שתהא שומעת הכרוזין של ב\"ד של מעלה ובת קול היוצאת מהר חורב, והיית יודע בחוש ראיה ושמיעה שיש אלוה בעולם, אלא וכל מעשיך, הרעים, בספר, באותן הספירות והבהירות של חושי נשמתך, נכתבין, ועי\"ז מדהה אתה ומכהה אורה של הנשמה מפני שעונותיו מבדילין, ע\"כ דע מה למעלה ממך ע\"י ידיעה לבד.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>דע מה למעלה כו'</i> – אבות פ\"ב מ\"א. <i>ראיה גדול משמיעה</i> – מכילתא יתרו יט, ט. ר\"ה כה, ב. <i>כה אמר ה' שלח גו' ויאמר פרעה גו'</i> – שמות ה, א-ב. <i>רואה ואינו נראה</i> – ברכות י, א. <i>אל</i>-<i>הי העברים גו' נלכה גו'</i> – שמות ה, ג. <i>ששם לבן כו'</i> – ויצא ל, לו. <i>בת קול היוצאת כו'</i> – אבות פ\"ו מ\"ב. <i>וכל מעשיך בספר נכתבין</i> – אבות פ\"ב מ\"א. <i>שעונותיו מבדילין</i> – ע\"פ ישעיה נט, ב.\n----- הערות וציונים -----\n<i>עין רואה כו' ואוזן ראוי כו'</i> – ראה לקמן סי' שס, ומשם משמע שזה פי' הבעש\"ט."]]],[300010209,"קעו\n\n<b>שמעתי</b> <i>ממורי</i> כי השכינה נקרא תפלה כמ\"ש בכתבים ואני תפלה וכו'. וגם מבואר שם כשיתפלל ישים מגמת פניו לשכינה ליחדה <span data-k=\"sm\">[בבעלה]</span> &lt;כו'&gt;, ולא יכוין לתועלת עצמו שח\"ו עליו נאמר נתנני ה' בידי לא אוכל קום וכו' יעו\"ש. וביאר <i>מורי</i> זללה\"ה הטעם יותר, כי אם יכוין לתועלת עצמו הגשמי שיהיה נענה בתפלתו לתועלתו הגשמי, אז נעשה מסך מבדיל ע\"י שהכניס הגשמי ברוחני שם ואינו נענה כלל, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ שמות ב</b>,<b> רע</b>\"<b>ג (כג</b>,<b> א)</b>\n<i>השכינה נקרא תפלה</i> – זח\"א רנג, ריש ע\"ב. זח\"ג מט, ריש ע\"ב. <i>כמ\"ש בכתבים</i> – פע\"ח, ריש שער התפלה. לקו\"ת, תהלים קב. <i>ואני תפלה</i> – תהלים קט, ד. <i>נתנני ה' גו'</i> – איכה א, יד.\n----- הערות וציונים -----\nראה לעיל סי' פ, ולקמן סי' רסח ושצה-א.\n<i>נתנני ה' גו'</i> – להעיר מתקו\"ז תי\"ח לה, א."]]],[300010210,"קעז\n\n<b>שמעתי</b> <i>ממורי</i> כי יראת העונש שהיא יראה חיצונית מורה על ידו יתברך פשוטה לקבל שבים, ויתעורר מזה ליראה פנימית הנקרא אהבה, לקבל באהבה, ואז יפטור מיראה חצונית וכו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בא לב</b>,<b> סע</b>\"<b>ג (קכא</b>,<b> א)</b>\n<i>ידו ית' פשוטה לקבל שבים</i> – זח\"א כג, רע\"א. תקו\"ז ת\"ו כב, א. שם תמ\"ז פד, סע\"ב. פדר\"א רפמ\"ג.\n----- הערות וציונים -----\nנשנה לקמן סי' שסה. ראה לעיל סי' לח, ולקמן סי' קפ ורז-א. ורג\"כ סי' תיג."]]],[300010211,"קעח\n\n<b>שמעתי</b> <i>ממורי</i> זללה\"ה ענין החיות רצוא ושוב, כי כל דבר חושק ומתלהב <span data-k=\"sm\">[לחזור לשרשו לדבק שם, לכך הנשמה מתלהב]</span> תמיד לידבק בשרשו למעלה ע\"י חשק בתורה ובעבודת ה', ואם מתלהב תמיד היה בטל ממציאותו כמו קודם עולם התיקון. וזה סוד קברות התאוה שכתב בס' ברית מנוחה <span data-k=\"sm\">[וכו']</span>, והוא סוד המבול, נפתחו ארובות השמים <span data-k=\"sm\">[וכו']</span>. לכך תיקן השי\"ת שיעסוק לפעמים זמן מה בצרכי הגוף אכילה ושתיה ומעט להתעסק בצרכי פרנסתו גם שיש לו מדת הסתפקות, וע\"י ביטולו מעבודת ה' בזמנים אלו ינוח הנשמה וכח השכלי יתחזק לחזור ולעסוק בעבודת הש\"י אח\"כ. וזה והחיות רצוא ושוב. ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בא לג</b>,<b> סע</b>\"<b>ב (קכז</b>,<b> א)</b>\n<i>החיות רצו\"ש</i> – יחזקאל א, יד. <i>קברות התאוה</i> – בהעלתך יא, לד. <i>בס' ברית מנוחה</i> – ד\"ה הדרך הראשונה. <i>נפתחו ארובות השמים</i> – נח ז, יא.\n----- הערות וציונים -----\nהסיפא דסימן זה (בתוספת המשך) מובא לקמן בסי' שסז עיי\"ש. ולכללות התוכן ראה ג\"כ לעיל סי' לד, קי-ג וקכא.\n<i>כל דבר חושק כו'</i> – להעיר מהלכות יסוה\"ת פ\"ד ה\"ב. ועיין זח\"ג ריט, סע\"ב ואילך.\n<i>וז\"ס קברות התאוה כו'</i> – ראה דמ\"א, פ' בראשית ד\"ה ויאמר אלקים: ששמעתי מאא\"ז נ\"ע ריב\"ש שאמר שכתוב בס' ברית מנוחה שחכמה נקרא קברות התאוה, כי כשאדם דבוק בחכמה ממילא כל התאוות בטלין ממנו, ולכך נקרא קברות התאוה היינו שע\"י החכמה הוא מקבל ומבטל כח התאוה מעליו. וכן שם ר\"פ מסעי: ששמעתי בשם אא\"ז זללה\"ה כי כל המסעות היו מ\"ב והם אצל כל אדם מיום הולדו עד שובו אל עולמו . . וידוע שכל המסעות הם בחי' קדושים וטהורים כמו ששמעתי מן אא\"ז זללה\"ה בשם ספר ברית מנוחה קברות התאוה הוא בחי' החכמה כי שם קברו את העם המתאוים, פי' מי שבא למדת החכמה אזי בטל ממנו כל התאוות מרוב דביקותו בו ית' (ועיי\"ש ההמשך). ולהעיר ממדל\"י סי' צא (ק) קרוב לסופו, ושם קעז (קפב) קרוב לסופו, דמדריגת חכמה הוא מדריגת אי\"ן והאי\"ן אינו מתאוה לכלום.\n<i>והוא סוד המבול נפתחו כו'</i> – ראה תוי\"י ס\"פ מסעי קסה, ד: ענין מי המבול שנפתחו ארובות השמים הוא רמז לעולם התוהו קודם עולם התיקון בסוד ז' מלכים קדמאן לרוב חשקם והתמדתן בדביקות ועבודת ה' בטלו ממציאות ומתו, משא\"כ אח\"כ ויסכרו מעיינות תהום רבה שיהיה ע\"י צנורות דקים לקיום העולם, וזהו השבועה ולא יהיה המים למבול דייקא שלא ירבו מימי השפע לרוב רק כדי שיוכלו לסבול, וא\"כ גם אלו הלומדין המבטלין לפעמים הוא לתועלת שיהיה יתרון אור מן החושך, וכמו ששמעתי ממורי ביאור מדרש וירא אלקים את האור כי טוב אלו מעשיהם של צדיקים וכו' יעו\"ש (ראה לקמן סי' רמט, ורג\"כ סי' קפח), א\"כ הביטול הוא התיקון."]]],[300010212,"קעט\n\n<b>שמעתי</b> <i>ממורי</i> זלה\"ה &lt;הבעש\"ט&gt;, כיצד מרקדין לפני הכלה בית שמאי אומרים כלה כמות שהיא ובית הלל אומרים כלה נאה וחסודה <span data-k=\"sm\">[וכו']</span>. וביאר, כי לעתיד &lt;לבוא&gt; השכינה נקראת כלה כו', משא\"כ עתה השכינה נקראת זא\"ת כו'. ובזה יובן כיצד מרקדין לפני הכלה, ר\"ל שמתמיה כיצד מרקדין בזמן הזה בגלות השכינה שהוא לפני וקודם שנקראת כלה, כי הריקוד הוא להעלות ניצוצין ומדריגה תחתונה להעלותה אל העליונה, כמו ריקוד קדוש כו', ואין זה עולה יפה בזמן הגלות, כי מי יוכל לעשותה על צד השלימות, כמבואר בסוד נפילת אפים שהוא להעלות ניצוצין מן עשיה עד רום המעלות וכו', וכתב מוהרח\"ו ז\"ל שאין אתנו יודע עד מה כו', יעו\"ש.\n<b>לכך</b> אמרו בית שמאי כלה כמות שהיא, על דרך שכתב בזוהר סוד נודע בשערים בעלה לפי מה שמשער כל אחד בדעתו ויכולתו, אף בדרך כלל אם אינו יכול בדרך פרט לייחד השכינה ולקשטה, מכל מקום ישער כלה כמות שהיא כו'. ובית הלל סבירא ליה כלה נאה וחסודה, שצריך לידע בפרט איך להסיר בגדים צואים וליכלוך מהניצוצין ולקשטה בפרט, שתהיה השכינה כלה נאה וחסודה וכו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ ר</b>\"<b>פ בשלח מו</b>,<b> א (קסז</b>,<b> א)</b>\n<i>כיצד מרקדין כו'</i> – כתובות טז, ב. <i>השכינה נקראת כלה</i> – ראה זח\"ב ה, ב. <i>השכינה נקראת זא\"ת</i> – זח\"ג רצז, סע\"ב. <i>ריקוד קדוש</i> – (טושו\"ע או\"ח סי' קכה ובנ\"כ שם). פע\"ח שער חזרת העמידה פ\"ג. <i>בסוד נפילת אפים</i> – פע\"ח שער מ\"ן ונפ\"א פ\"ג. <i>וכתב מוהרח\"ו ז\"ל</i> – פע\"ח שם ספ\"ג. <i>בזוהר</i> – זח\"א קג, ריש ע\"ב. <i>נודע בשערים גו'</i> – משלי לא, כג.\n----- הערות וציונים -----\nראה לקמן סי' שסח-שסט.\n<i>השכינה נקראת זא\"ת</i> – ראה לעיל סי' קכו."]]],[300010213,"קפ\n\n<b>שמעתי</b> <i>ממורי</i> זללה\"ה לבאר ענין קושית הפילסוף, מאחר שהקב\"ה נקרא נורא למה צריך לצוות בתורה על היראה הא יבוא ממילא, כנודע ממורא מלך בשר ודם שהוא <span data-k=\"sm\">[ממילא]</span> בלא צווי. וביאר, כי ענין היראה הוא ירא מן העדר כבוד ועושר וחיים וכיוצא, משא\"כ אחר ההעדר אין יראה, שאם הוא נעדר מהחיים ומת שוב אין לו יראה מהעדר חיים, וכיוצא בעושר ואינך.\n<b>והנה</b> יראה זו הוא יראה חצונית שהוא בכל הנבראים, כי העכבר ירא מחתול וחתול ירא מכלב וכלב מזאב, וכיוצא בזה יש באדם אחד ירא מחבירו. ולמעלה מזה יש יראה פנימית, יראת הבורא יתברך. אמנם גם יראה חצונית הבאה על האדם היא כדי לעורר אותו אל היראה הפנימית, והוא חסד ה' יד ימינו פשוטה ושואל ומבקש מהאדם שיתעורר מזה אל יראת ה'. וז\"ש מה ה' אלקיך שואל מעמך כי אם ליראה את ה' וגו', שהוא יראה פנימית. וההעדר ביראה פנימית הוא כאשר מדבק את עצמו אל חי החיים ושם הוא העדר המציאות, וכאשר אין לו יראה זו אז ידע שכבר הוא נעדר מהחיים שכבר מת, וכמ\"ש רשעים בחייהם קרויים מתים, ולכך אין לו יראה.\n<b>ובזה</b> סרה קושית הפילסוף, שבאמת אין צריך צווי על היראה כי היא ממילא, ומ\"ש מה ה' שואל מעמך כי אם ליראה את ה' היינו מאחר שיש מדת היראה בכל הנבראים, אם כן ראוי שיהיה לאדם מעלה יתירה זו שיתעורר מן יראה חצונית אל יראה פנימית אחר <span data-k=\"sm\">[שידעו]</span> שידו ית' פשוטה לעוררו בזה. וז\"ש מה ה' שואל מעמ\"ך דייקא וכנ\"ל, והבן.\n<b>והנה</b> אם ידע האדם זה החסד ואהבת הבורא ית' עליו בחמלתו ששלח לו יראה חיצונית כדי לעוררו אל יראה פנימית &lt;סוד הבינה <span data-k=\"sm\">[א]</span> אלף בינה&gt;, אז נעשה מיראה אהבה, שמקבל היראה חיצונית באהבה, ואז נפטר מיראה חצונית. (שנעשה מן מו\"ת ואמ\"ת שהיא חיים, כי מקשר מלכות, ה' תתאה, אל ה' עילאה, ונעשה מן אנ\"י אי\"ן, ומבטל כל גזירות רעות, כמו ששמעתי <i>ממורי</i> זלה\"ה והבן, והש\"י יכפר).<i>[ftnref_1_כד]</i>\n<b>אך</b> אם כוונתו בזה כדי לפטור מיראה חצונית לא מהני כלום. וזה שהזהירה <span data-k=\"sm\">[תורה]</span> ואהבת את ה' בכל לבבך, שיהיה בלב שלם כאשר בא היראה חצונית בנפשך ובמאדך, שיהי' בכוונה הראויה וכנ\"ל, והבן ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בשלח מט</b>,<b> ג (קפ</b>,<b> ב)</b>\n<i>שהקב\"ה נקרא נורא</i> – תהלים קיא, ט. <i>חסד ה' יד ימינו</i> – תקו\"ז יז, א. זח\"א כז, ב. <i>יד ימינו פשוטה</i> – פדר\"א רפמ\"ג. זח\"א כג, רע\"א. תקו\"ז ת\"ו כב, א. שם תמ\"ז פד, סע\"ב. <i>מה ה' גו'</i> – עקב י, יב. <i>חי החיים</i> – תקו\"ז תי\"ט מא, סע\"ב. שם תס\"ט קטו, סע\"א. <i>רשעים בחייהם כו'</i> – ברכות יח, ב. <i>יראה היא במלכות</i> – זח\"ג קח, א. תקו\"ז ו, א. שם תל\"ג עז, רע\"א. <i>במלכות אשר רגליה כו'</i> – ע\"ח של\"ד פ\"א. <i>רגליה גו'</i> – משלי ה, ה. <i>בינה א' אלף בינה</i> – זח\"ב קטו, א. תקו\"ז תנ\"ה פח, א. <i>א' אלף בינה</i> – שבת קד, א.\n----- שולי הגליון -----\n[ftn_1_כד]) <i>מה ששמתי בחצ\"ע הוא קטע (בשנויים קלים) ממש\"כ שם בצ\"פ דף נ סע\"ג</i>,<i> וזה לשונו שם</i>:\nובזה תבין טעם הנ\"ל למה בהכנס אל יראה פנימיות נפטר מיראה חיצונית, כי יראה היא במלכות אשר רגליה ירדות מות, וכאשר נכנס אל יראה פנימיות סוד הבינה א' אלף בינה, אז נעשה מן מו\"ת ואמ\"ת שהיא חיים, ונפטר מן מות יראה חיצונית, כי מקשר מלכות ה' תתאה אל ה' עילאה, ונעשה מן אנ\"י אי\"ן ומבטל כל גזירות, כמו ששמעתי <i>ממורי</i> זלה\"ה והבן, והש\"י יכפר.\n----- הערות וציונים -----\nראה לקמן סי' תיג ובהערות שם. ורג\"כ סי' תיב.\n<i>יראה חיצונית הבאה אל האדם כו'</i> – ראה לעיל סי' קעז וש\"נ.\n<i>במלכות אשר רגליה כו'</i> – ראה לעיל סי' מב ופח.\n<i>נעשה מן מו\"ת ואמ\"ת</i> – ראה שער היחודים (ענף ד' מס' פע\"ח) פי\"ג יח, סע\"א: במילת משה תכוין בשם הקדוש מה\"ש (הוא שם הה' דשם ע\"ב, ראה זח\"ב ער, א) במילואו מ\"ם ה\"א שי\"ן כו' גי' מו\"ת למתק המות כו' ותכוין להמשיך א' מתיקון באמת שבפני דא\"א להופכו ממות לאמת כו'. והובא בדמ\"א פ' תשא (הנסמן לעיל בהערות לסי' ע) ושם: כי ידוע בכוונת הקטורת כי מה\"ש במילואו הוא מספר מות ונמתק ונעשה האמת ע\"ש.\n<i>מלכות ה' תתאה אל ה' עלאה</i> – ראה זח\"ג רנג, א.\n<i>ונעשה מן אנ\"י אי\"ן ומבטל כו'</i> – ראה לקמן סי' קפט-א וקפט-ב. להעיר מפרדס רמונים שכ\"ט פ\"א. ע\"ח שמ\"ב ספ\"א."]]],[300010214,"קפא\n\n<b>&lt;פי'</b> מורי&gt; <span data-k=\"sm\">[</span><i>וממורי</i><span data-k=\"sm\"> זללה\"ה שמעתי]</span> ביאור קושיא זה דשמעון העמסוני היה דורש כל אתין שבתורה עד שהגיע לאת ה' אלהיך תירא פירש, עד שבא ר' עקיבא ולימד את &lt;ה' אלהיך תירא&gt; לרבות תלמידי חכמים, &lt;וקשה&gt; <span data-k=\"sm\">[והקושיא מפורסמת]</span> מאי טעמא לא דרש שמעון כך <span data-k=\"sm\">[ועיין פירוש רש\"י ומוהרש\"א בפ\"ב דקידושין ובפ\"ד דבבא קמא יעו\"ש]</span> דפירשו &lt;כי דבר פשוט&gt; דאי אפשר להשוות שום דבר למוראו ית', לכך פירש מדרשה זו, משא\"כ ר' עקיבא כשהיה ע\"ה והיה שונא לת\"ח והיה מרוחק ממורא השי\"ת, ועכשיו שנעשה ת\"ח דחיל מרבנן מקורב למורא השי\"ת ג\"כ, לכך דרש את ה' לרבות ת\"ח, כי מורא ת\"ח מביאו למורא השי\"ת.\n<b>והנה</b> ישראל שבמדבר היה להם יראה מת\"ח, שנאמר ויראו מגשת אליו, אם כן בנקל הוא <span data-k=\"sm\">[להם]</span> שיזכו הם ג\"כ ליראת ה'. ובזה יובן אין לגבי משה זוטרתי, ר\"ל מאחר שהיה יראה להם לגבי משה וזכו ליראת הת\"ח, אם כן זוטרתי היא שיזכו ג\"כ ליראת ה', והבן, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בשלח נ</b>,<b> רע</b>\"<b>א (קפא</b>,<b> ב)</b>\n<i>דשמעון העמסוני כו'</i> – פסחים כב, ב. וש\"נ. <i>את ה' אלקיך תירא</i> – ואתחנן ו, יג. <i>בפ\"ב דקידושין</i> – נז, א. <i>ובפ\"ד דב\"ק</i> – מא, ב. <i>ר\"ע כשהיה ע\"ה כו'</i> – פסחים מט, ב. <i>ויראו מגשת אליו</i> – כי תשא לד, ל. <i>אין לגבי משה כו'</i> – ברכות לג, ב.\n----- הערות וציונים -----\nראה לעיל סי' קנג-ב.\n<i>ובזה יובן אין לגבי משה כו'</i> – ראה לעיל סס\"י לח."]]],[300010215,"קפב\n\n<b>שמעתי</b> <i>ממורי</i> זלה\"ה &lt;פי'&gt; כי צדיקייא אינון שלוחי דמטרוניתא, ע\"י הצר וחסרונו יודע חסרון השכינה להתפלל שימולא שם החסרון ונעשה על ידו יחוד קב\"ה ושכינתיה. וזהו מעלת התפלה.\n<b>וסרה</b> קושית הקדמונים למה צריך תפלה, הלא הש\"י יודע מה שצריך האדם כי הוא בוחן כליות ולב וכו', <i>ומורי</i> ביאר ע\"פ הנ\"ל, כי תפלה הוא צורך גבוה, שידע אדם מחסרונו שהוא נמשך מחסרון של מעלה, ויתפלל שימולא החסרון שם למעלה בשכינה, כי צדיקייא אינון שלוחי דמטרוניתא &lt;ואיזהו חסיד המתחסד עם קונו&gt;, וממילא ימולא החסרון שלו גם כן, רק שלא יכוין לתועלת עצמו רק לתועלת השכינה, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בשלח נ</b>,<b> ג (קפג</b>,<b> א)</b>\n<i>צדיקייא אינון כו'</i> – זח\"א רמב, א. <i>קושית הקדמונים</i> – עיקרים מ\"ד פי\"ח. נתיבות עולם להמהר\"ל נתיב העבודה פ\"ב. <i>ואיזהו חסיד כו'</i> – זח\"ב קיד, ב. זח\"ג רכב, א.\n----- הערות וציונים -----\nראה לקמן סי' רצו.\n<i>צדיקייא כו' ע\"י הצר כו'</i> – ראה לעיל סי' סא וקכו. לקמן סי' שצה. ורג\"כ סי' כ ובהערות שם.\n<i>איזהו חסיד כו'</i> – זו הוספת הרב המלקט, והוסיף זה ע\"פ תוי\"י וירא לח, ג (לקמן סי' רצו) שם הובא דרוש זה בהוספת המלים: והוא כלל גדול שהוא חסיד המתחסד עם קונו ולא עם עצמו.\n<i>וממילא ימולא החסרון שלו</i> – ראה לקמן סי' שסח ושצה-א.\n<i>שלא יכון לתועלת עצמו כו'</i> – ראה לעיל סי' פ וקעו, לקמן סי' רפב-ב ורצ. ועיין היטב סי' שצה-א."]]],[300010216,"קפג\n\n<b>(שמ\"מ)</b> משל ששמעתי <i>ממורי</i> זלה\"ה מלך <span data-k=\"sm\">[אחד]</span> ביקש רפואה שיחיה לעולם, ונתנו לו רפואה להרחיק מגאות כו', וכל מה שנהג ענוה ביותר נכנס בלבו גאוה יותר שהוא מלך גדול ועניו ביותר, עד שבא רבו אצלו ולמדו לנהוג מלכות מבחוץ ובקרבו ישפיל דעתו, על ידי שהראה לו בית הכסא שהוא מן האדם כו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בשלח נ</b>,<b> סע</b>\"<b>ד (קפד</b>,<b> ב)</b>\n----- הערות וציונים -----\nבצ\"פ ממשיך: וכן שמעתי פי' הפסוק ה' מלך גאות לבש הוא הגאוה מדת מגונה כו' לכך אמר לצורך הנהגת המלוכה צריך לבוש הגאוה כו', וכעין זה כתוב בס' יד יוסף דף קס\"ו ותלבש אסתר מלכות (אסתר ה, א), מבחוץ לבשה כך ובקרבה היתה אבודה והדיוטות כו' יעו\"ש."]]],[300010217,"קפד\n\n<b>&lt;שמ\"מ&gt;</b> יש ג' בחינות בסדר עבודת הש\"י. א' <span data-k=\"sm\">[ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה ביאור פסוק אחור וקדם צרתני]</span> שיעלה גם הקטנות בימי הגדלות כו' &lt;וזה ביאור פ' אחור וקדם צרתני&gt;. בחינה ב' אם חושש שמא לא יזכה לבוא למדריגת הגדלות, מכל מקום אם יודע שהוא במדריגת הקטנות אז ממתיק הדינין ע\"י מנצפ\"ך כו'. בחינה ג' כשהוא בגדר השכחה בלי דעת, וזהו שאמר הכתוב ואנכי הסתר אסתיר, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בשלח נא</b>,<b> סע</b>\"<b>ג (קפז</b>,<b> א)</b>\n<i>אחור וקדם גו'</i> – תהלים קלט, ה. <i>ואנכי הסתר גו'</i> – וילך לא, יח.\n----- הערות וציונים -----\nראה לעיל סי' כה וקלט."]]],[300010218,"קפה\n\n<b>שמעתי</b> <i>ממורי</i> זלה\"ה פירש <span data-k=\"sm\">[הפסוק פ' כי תשא]</span>, איש אשר יעשה כמוה להריח בה, שיהיה ריחו נודף, שיצא לו שם כאנשי חסידים שנקרא קטרת שמקשרין ומייחדין קב\"ה &lt;ושכינתיה&gt;, והם עושין להריח בה, ונכרת מעמיו, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בשלח נו</b>,<b> ריש ע</b>\"<b>ב (רב</b>,<b> א)</b>\n<i>איש אשר יעשה גו'</i> – כי תשא ל, לח.\n----- הערות וציונים -----\nבצ\"פ ממשיך \"וכיו\"ב שמעתי בשמו\" ומביא פי' הבעש\"ט על שמות השבטים כמו שהם בקליפה, כנ\"ל בסוף סי' לא ולקמן סי' תג. ולהעיר עוד מלקמן סי' שטו."]]],[300010219,"קפו\n\n<b>שמעתי</b> <i>ממורי</i> דיש <span data-k=\"sm\">[בכתבי]</span> שו\"ת של הרמב\"ם, ששלחו מדינה א' להרמב\"ם, וחתמו על שאלה זו במספר ע' אלף, ילמדנו רבינו, מאחר שאין תחיית המתים מפורש בתורה, רק בש\"ס רמזו ודרשו מהוכחות שלהם, א\"כ גם לנו יש להוכיח ולדרוש איפכא כו'. והרמב\"ם לא רצה בעצמו להשיב, וצוה לתלמידו מהר\"י אבן תבון לכתוב תשובתם. ותוכן ענין תשובתם הוא זה, אבאר לכם, מאחר שנמשך לכם ספק זה, א\"כ אין נשמתכם נמשך מבני אברהם יצחק ויעקב רק מאנשי סדום ועמורה כו', כי יש נשמות הנמשך משמים וארץ וז' כוכבי לכת וכיוצא וכו'.<i>[ftnref_1_כה]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ יתרו סד</b>,<b> א (רכח</b>,<b> א)</b>\n<i>בש\"ס רמזו ודרשו כו'</i> – פסחים סח, סע\"א. סנהדרין צ, ב. שם צא, ב. שם צב, א. <i>כדרשת חז\"ל</i> – ר\"ה יא, א.\n----- שולי הגליון -----\n[ftn_1_כה]) <i>חסר המשך הדברים</i>: ויש לשאול על עיקר הבריאה הא כל מעשה בריאת עולם לצביונן נבראו כדרשת חז\"ל בפסוק ויעש אלהים וגו', ואם כן מה טעמא לא רצה ארץ להיות בחינת שמים, וצ\"ל שלא נתן דעת לארץ שידע בחינת שמים וזכותו שיתאוה להיות בחינת שמים, והטעם כי גם בחינת ארץ צריך שיהיה בעולם, וכיוצא בזה וכל הנבראים, וזה שאמרו לצביונים נבראו. וגם בחינת אדם צריך שיהיו כת רשעים וכת בינונים וכת צדיקים, כי יתרון אור מהחושך עיין מזה במקום אחר, ר\"ל שנמשך תועלת מהחשך, ממעשה הרשעים נודע מעלת הצדיקים, וכל אחד נבראו לצביונם ורצונם.\nוכי תימא אם כן תקשי לכם קושיא בחינת הבחירה עם הידיעה, מאחר שאתם כופרים בדרשת חז\"ל, אם כן אין אתם משיגים ביאור קושיא זו.\nוהנה נפש האדם הוא דם הנעשה מברירות המאכלים, ויש כמה מיני בירור, בתחלה על ידי שזורקת המרה טפה במאכל שבתוך מעיו נברר הגס ועב ונעשה צואה ויוצאה לחוץ, בירור ב' יוצא למי רגלים, בירור ג' נעשה זיעה, ד' נעשה שערות וצפרנים, בירור ה' הדם נבלע בכבד וטחול וכו', ומבחר הדם נכנס בלב ואחר כך במוח ומזה נעשה השכל והדעת. ומדבריכם נראה שאתם כופרים בדברי חז\"ל, אם כן לא נזהרתם מאכילת איסור ודברים טמאים, והשכל והדעת שלכם נעשה מהדמים של טריפות ואיסורים, והשכל והדעת שלכם נמשך להכריע אל הטומאה כי ממנו נעשה, ואם כן איך תוכלו להכריע בשכל שלכם נגד רבותינו חכמי התלמוד אשר רוחב לבם היה רחבה מני ים וכו'. ותדעו נאמנה, מאחר שירדו לספק זה וכפירה זו, שהפורעניות קרובה לכם. וכך עלתה להם שבא עליהם מלך אחד והרגם והשמידם, ורצו להמיר דתם ולא קבלו אותם מאחר שכפרו בתחיית המתים, והאומות מאמינים גם כן בסוד הגלגול ותחייה וכמ\"ש הפילסוף וכו'. ומעט מזעיר נמלטו להרמב\"ם וחזרו בתשובה ע\"כ.\n----- הערות וציונים -----\nכן הובא ענין זה בדמ\"א פ' עקב ד\"ה ומלתם ששמע זה מא\"ז הבעש\"ט עיי\"ש. וראה לקמן סי' שפא. ולהעיר שהיה זה קבלה ביד הבעש\"ט דאינו מצוי בכתבי הרמב\"ם אשר לפנינו.\n<i>מבני אברהם כו'</i> – להעיר מזח\"ב צה, סע\"א. ר\"ח שער הענוה ספ\"א.\n<i>רק מאנשי סדום כו'</i> – להעיר מזו\"ח ריש מדרש רות עה, א.\n<i>בפסוק ויעש כו'</i> – צ\"ע, דחז\"ל דרשו הנ\"ל בפסוק ויכלו גו' (בראשית ב, א).\n<i>כי יתרון אור כו'</i> – ע\"פ קהלת ב, יג.\n<i>עיין מזה במ\"א</i> – ראה לקמן סי' קפח.\n<i>לצביונם ורצונם</i> – ראה רש\"י ר\"ה יא, א ד\"ה לדעתם, ופרש\"י לבר\"ר י, ה. ולהעיר ממאמר היושבת בגנים תשי\"א אות ג.\n<i>והשכל והדעת שלכם נעשה כו'</i> – ראה עקידת יצחק שער ס (לג, ב ושם בסופו לח, ב). של\"ה, שער האותיות פה, ב (סא, ג) ד\"ה ויחזור אחר מאכלים דקים וד\"ה ויזהר מהמאכלים הגסים. וראה זח\"ג מא, א ואילך. פס\"ז, מדה\"ג ואוה\"ח על שמיני יא, מג. ע\"ח שמ\"ט פ\"ב ופ\"ה. שו\"ע יו\"ד סי' פא סעיף ז ובש\"ך שם. רג\"כ יומא לט, רע\"א."]]],[300010220,"קפז\n\n<b>&lt;פי'</b> מורי&gt; <span data-k=\"sm\">[בשם </span><i>מורי</i><span data-k=\"sm\"> זללה\"ה]</span> טעם שניתן למשה רבינו ע\"ה מ\"ט שערי בינה ולא שער נ', כי שער הנ' הוא חוזר ומתחיל כו' יעו\"ש.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ ס</b>\"<b>פ משפטים פד</b>,<b> ג (רחצ</b>,<b> א)</b>\n<i>שניתן למשה כו'</i> – ר\"ה כא, סע\"ב.\n----- הערות וציונים -----\n<i>יעו\"ש</i> – צ\"פ פ' בשלח מז, ד (קעד, א): דשמעתי ממורי זללה\"ה טעם שניתן מ\"ט שערי בינה למשה חוץ מן שער החמשים, ותירץ כי שער החמשים הוא חוזר ומתחיל נ' שערים למעלה מזה וכן למעלה למעלה מזה עד אין סוף כי שנת החמשים דיובל (ולאה) [עולה] לכאן ולכאן (ר\"ה ט, רע\"א) ודפח\"ח."]]],[300010221,"קפח\n\n<b>&lt;פי'</b> מורי&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\"> זללה\"ה . . . ביאור]</span> משנה דאבות ד' מדות בנותני צדקה <span data-k=\"sm\">[וכו', והקושיא מפורסמת]</span> &lt;וק'&gt; איך הוא ד' מדות, דמדה זו לא יתן ולא יתנו אחרים אינו מנותני הצדקה, וכן ד' מדות בהולכי בית המדרש וכו'. וביאר לי שאלת חלום וכו', וביאר פסוק חשבתי דרכי ואשיבה רגלי אל עדותיך, על פי מדרש ויהי ערב אלו מעשיהם של רשעים ויהי בקר אלו מעשיהם של צדיקים ואיני יודע באיזה מהם חפץ, כשהוא אומר וירא אלהים את האור כי טוב הוי במעשיהם של צדיקים חפץ יותר, והוא תמוה, וכי סלקא דעתך שחפץ במעשה רשעים. וביאר מה שקיבל מרבו, כי דוד המלך ע\"ה היה במזל שלא עלו לו מחשבותיו בעבודת הש\"י כהוגן, והוא מצד מזל שבתאי המקבל מבינה וכו', לכך היה חושב בדרכיו הגשמי וממילא הי' בהיפך וכו'. וז\"ש חשבתי דרכי ואז ואשיבה רגלי, ר\"ל אשיבה להרגיל בו אל עדותיך, והבן.\n<b>והלבנה</b> שהיא בסוד דוד מלך ישראל חי וקיים אין לה אור מעצמה רק מה שמקבלת מן השמש כנודע לחכמי התכונה. אמנם יש תועלת ויתרון לאור מן החשך, דהיינו מעלת יתרון האור ניכר מצד החשך, וכן החכם מצד הטיפש, וניכר מעלת הצדיק מצד הרשע, והתענוג מכח הנגע והיסורין, ומעלת הדעת נודע מכח השכחה, א\"כ נעשה זה כסא לזה, כמו יד האדם המושיט דבר למעלה אז הוא בעצמו שם. וזה מעלת גזירה שוה, כי ברוחני אחר שיש לו שווי בצד מה נעשה אחד, ולכן דנין בגזירה שוה גם למיתה החמורה. וכן כתב הרמב\"ם גרגיר חרדל מצד עגולו וכידורו שוה לרקיע <span data-k=\"sm\">[וכו'. אמנם לפי זה יש מקום לטעות לעבוד עבודה זרה מאחר שהכל נעשה כסא זה לזה, אם כן באמת הכל נכנס באחדות אחד וכו']</span>, אפס <span data-k=\"sm\">[שזה אינו]</span> כי יש הבדלה וכו'. רק התענוג שנמשך אחר שסר השכחה הוא נכנס באחדות והשאר יורד למטה בסוד הבדלה וכו'.\n<b>וז\"ש</b> ואיני יודע באיזה מהם חפץ, מאחר שגם מעשה הרשעים הוא כסא למעשה הצדיקים, אם כן הכל אחדות אחד. לכך נאמר וירא אלהים את האור כי טוב אלו מעשיהם של צדיקים, כי במעשה הרשעים צריך הבדלה וכו'.\n<b>ובזה</b> יובן כי יש &lt;ד' מדות בהולכי בהמ\"ד, כי זה שאינו הולך נעשה כסא לההולך בדרך הנ\"ל כשמפרנסו&gt; <span data-k=\"sm\">[ד' מדות בנותני צדקה, כי זה שאינו נותן נעשה כסא להנותן בדרך הנ\"ל]</span>, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ תרומה קד</b>,<b> סע</b>\"<b>ב (שסו</b>,<b> ב)</b>\n<i>ד' מדות בנותני צדקה</i> – אבות פ\"ה מי\"ג. <i>ד' מדות בהולכי ביה\"מ</i> – אבות פ\"ה מי\"ד. <i>חשבתי גו'</i> – תהלים קיט, נט. <i>ע\"פ מדרש</i> – בר\"ר ב, ה. <i>ויהי ערב גו'</i> – בראשית א, ה. <i>וירא אלקים גו'</i> – בראשית א, ד. <i>והלבנה שהיא כו'</i> – זח\"ג שב, סע\"ב. <i>דוד מלך ישראל כו'</i> – ר\"ה כה, א. <i>אין לה אור מעצמה</i> – זח\"א רמט, ב. שם רנא, ב. <i>ויתרון לאור כו' וכן החכם כו'</i> – ע\"פ קהלת ב, יג. זח\"ג מז, ב. <i>דנין בג\"ש גם כו'</i> – כריתות ה, א.\n----- הערות וציונים -----\n<i>והוא מצד מזל שבתאי</i> – ראה שבת קנו, א ובמהרש\"א שם ד\"ה מחשבתיה בטלין.\n<i>וז\"ש חשבתי דרכי כו'</i> – ראה לעיל סי' קמא ולקמן סי' רמט.\n<i>א\"כ נעשה זה כסא לזה</i> – ראה לעיל סי' כו, ע וקו, ולקמן סי' רפח ושצו.\n<i>וזה מעלת גז\"ש</i> – ראה לקמן סי' שעא.\n<i>לפי זה יש מקום לטעות כו'</i> – השוה מש\"כ בצ\"פ לפני זה בדף קא, סע\"ג ואילך (שנה, ב): אמנם טעם זה לא ניתן לכתוב ולאמר בפני המוני עם שיש בזה מקום לאפיקורסים לומר א\"כ גם עע\"ז נעשו כסא וכו' ובאמת זה אינו כי יש הבדלה כמו שביאר מורי זלל\"הה ודפח\"ח, וכן בתוי\"י פ' תצא קפט, א (תרפח, ב): אמנם יש בזה מקום לטעות ולומר דעצם העבירה נכנס בקדושה וזה אינו כי צריך הבדלה, וכמ\"ש במ\"א בשם מורי זלה\"ה כי אחר הבדלה יש יתרון לאור הנמשך מן החשך וכו', וז\"ש וגלחה את ראשה וגו' והסירה וגו' שהיא הבדלה מעצם עבירה ואח\"כ מה שנמשך הטוב ע\"י עבירה זה ובעלתה והיתה לך לאשה והבן, וזה סוד ותשליך במצולות ים וגו' (מיכה ז, יט) – ונקה (עיין סידור האריז\"ל להר\"ש, כוונת תשליך ד\"ה דע וד\"ה אמנם), שבכל עבירה יש ניצוץ קדוש ויש לבררו ולנקות וכו' וכמ\"ש בפע\"ח הל' ר\"ה (שער השופר פ\"ה) יעו\"ש, וה\"נ והבאתה ניצוץ שבתוך עבירה וגלחה וגו' והסירה עבירה עצמה וגו' ובכתה וגו' ואח\"כ ובעלתה והבן. וכן כתב שם בר\"פ בראשית ז, א (כג, ב). ועיין לעיל סי' כח-א וקס."]]],[300010222,"קפט-א\n\n<b>&lt;שמ\"מ&gt;</b> כאשר מקשר האדם מלכות במחשבה, בסוד כל אשר תמצא ידך לעשות בכחך עשה <span data-k=\"sm\">[שביאר </span><i>מורי</i><span data-k=\"sm\"> זלה\"ה]</span>, אז &lt;נעשה&gt; מן אנ\"י גליא נעשה אי\"ן דאתכסיא.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ כי תשא קיז</b>,<b> א (תיא</b>,<b> ב)</b>\n<i>כל אשר גו'</i> – קהלת ט, י.\n----- הערות וציונים -----\nראה לקמן סי' קפט-ב ובנסמן שם."]]],[300010223,"קפט-ב\n\n[<b>ששמעתי</b> <i>ממורי</i><span data-k=\"sm\">, כל אשר תמצא ידך לעשות בכחך עשה]</span>, ר\"ל לקשר המעשה שהיא מלכות דעשיה מצד השמאל אל המחשבה, &lt;בינה, המיוחד ב&gt;חכמה, כ\"ח מ\"ה, קו ימין, שהוא יחוד קב\"ה ושכינתיה, ועי\"ז מבטל גזירות רעות, לקשר מלכות הנקראת אנ\"י אל המחשבה הנק' אי\"ן וכו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ פקודי קיט</b>,<b> ג (תכא</b>,<b> ב)</b>\n<i>כל אשר גו'</i> – קהלת ט, י. <i>המעשה שהיא מלכות</i> – זו\"ח יתרו לד, רע\"ג (ועיי\"ש סע\"ב). <i>המחשבה </i>. .<i> חכמה</i> – זח\"ב כ, א. תקו\"ז יז, א. תקוזו\"ח ק, ב. <i>חכמה כ\"ח מ\"ה</i> – זח\"ג כח, א. שם לד, א. רלה, ב. <i>חכמה </i>. .<i> קו ימין</i> – זח\"ג רכד, א. תקו\"ז תי\"ח לב, ב. <i>מלכות הנקראת אנ\"י</i> – זח\"א רס, ב. שם רסא, ב. <i>המחשבה הנק' אי\"ן</i> – זח\"א רמו, ב.\n----- הערות וציונים -----\nראה לעיל סי' מב-א וצא.\n<i>לקשר שמאל אל </i>. .<i> קו ימין</i> – ראה זח\"ג קעח, רע\"א.\n<i>ועי\"ז מבטל גזירות רעות</i> – ראה לעיל סס\"י קפ ולקמן סי' ערב.\n<i>אני </i>. .<i> אין</i> – ראה לעיל סס\"י קפ וקפט-א."]]],[300010224,"קצ\n\n<b>&lt;שמ\"מ</b> על מה&gt; שכתב הרמב\"ם בשכליים הנבדלים אין שייך תואר ריבוי ומספר, &lt;ופי' ד&gt;הכי נמי אין שייך באותיות רוחניות התורה ריבוי ומספר כי אם מצד עילה ועלול. כי א' ראש כל האותיות נקרא עילה וכל האותיות עלולים ממנו, <span data-k=\"sm\">[והוא כאשר קבלתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כי אות ב' הם ב' אלפין, וכן אות ג' ג' אלפין כו', עד אות ת' הם ד' מאות אלפין וכו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ פקודי קיט</b>,<b> סע</b>\"<b>ב (תכא</b>,<b> א)</b>\n<i>שכתב הרמב\"ם כו'</i> – מו\"נ ח\"א פע\"ד ד\"ה הדרך השביעי. שם בהקדמות לח\"ב ד\"ה השש עשרה. הל' יסוה\"ת פ\"ב ה\"ה.\n----- הערות וציונים -----\n<i>א' ראש לכל האותיות כו'</i> – ראה לעיל סי' מה, פו וקס, ולקמן סי' שנה."]]],[300010225,"קצא\n\n<b>ולך</b> ה' החסד כי אתה תשלם לאיש כמעשהו, &lt;וקשה&gt; <span data-k=\"sm\">[ויש להבין אם הוא משלם כמעשהו]</span> &lt;אם כן&gt; מהו החסד, <span data-k=\"sm\">[כמו שמקשה בגמרא]</span>.\n<b>ואפשר</b> לומר על פי מ\"ש התנא אל תהיו כעבדים המשמשין את הרב על מנת לקבל פרס אלא כו' &lt;ויהי מורא שמים עליכם. וקשה חדא, מאי טעמא קראו התנא פה רב. עוד קשה מהו השייכות ויהי מורא שמים עליכם לכאן. וי\"ל&gt; ע\"פ משל לעבד אצל האדון, ואם העבד עובד את אדוניו כראוי משלם לו שכרו משלם, אבל זאת לא יעלה על &lt;לב שום&gt; עבד שאף אם יעבוד האדון עצמו עבודת העבד שישלם לו שכר לעבדו בשביל זה<i>[ftnref_1_כו]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ו</b>,<b> ג (ריש סי</b>'<b> קי)</b>\n<i>ולך ה' גו'</i> – תהלים סב, יג. <i>כמו שמקשה הגמרא</i> – ר\"ה יז, ב. <i>אל תהיו כעבדים כו'</i> – אבות פ\"א מ\"ג. <i>שהאדם מעורב טו\"ר</i> – תקו\"ז ריש תס\"ו צו, ב. שם תס\"ז צח, א. <i>הגוף הוא מסטרא כו'</i> – תקו\"ז תכ\"א מח, ב. <i>ובחטא יחמתני אמי</i> – תהלים נא, ז. <i>חלק א</i>-<i>לוה ממעל</i> – איוב לא, ב.\n----- שולי הגליון -----\n[ftn_1_כו]) <i>התירוץ בא בסוף סי' קצג</i>,<i> אבל בספר זה השמיט והוסיף כמה דברים</i>,<i> ע\"כ מועתק בזה כל המאמר כמו שהוא במקורו</i>:\nולך ה' חסד כי אתה תשלם לאיש כמעשהו, ויש לדקדק אם הוא משלם כמעשהו מהו החסד, כמו שמקשה בגמרא.\nואפשר לומר על פי מה שאמר התנא אל תהיו כעבדים המשמשין את הרב על מנת לקבל פרס, אלא הוו כעבדים המשמשין את הרב שלא לקבל פרס. והוא על פי משל לעבד אצל האדון, ואם העבד עובד את אדוניו כראוי משלם לו שכרו משלם, אבל זאת לא יעלה על אותו עבד שאף אם יעבוד האדון עצמו עבודת העבד שישלם לו שכר לעבדו בשביל זה, וזהו כאלו הוא משמש את הרב, כלומר העבד המשמש עם הרב שיעבוד עבודת עצמו, ועוד שישלם לו שכר עבור זה, וזהו פתיות גדול. ועל כל פנים אם הוא העבד עושה כן ומשמש עם הרב, יהיה על כל פנים על מנת שלא לקבל פרס ודי לו שאינו עובד את הרב בעצמו.\nוהנה ידוע שהאדם מעורב טוב ורע, ולבד זה כי הגוף הוא מסטרא דמסאבא חולקא דיצר הרע, כמו שאמר הכתוב ובחטא יחמתני אמי, והנשמה היא חלק אלוה ממעל, והנה חלק הטוב והנשמה הוא העובד עבודת השם. וזהו המשמש את הרב, כי החלק אלוה בעצמו הוא עובד לאלוה, והעבד המשמש את הרב, שיעבוד עבודה המוטל על העבד, ואף על פי שזה נקרא עבודה גרוע שאין העבד עובד כלום, על כל פנים לא תהיה זאת במחשבתו ודעתו לקבל שכר על זה. אבל הקב\"ה ברחמיו ובחסדיו הוא משלם שכר לעבדיו אף על פי שאינם עובדים אותו רק מאתו יתברך הוא עבודתו.\nוזהו ולך ה' חסד כי אתה תשלם לאיש כמעשהו, אף על פי שאין האיש עושה כלום מעצמו, אף על פי כן אתה משלם כמעשהו, וכמו שהיה העבד עושה בעצמו, וזהו חסד, וד\"ל.\n----- הערות וציונים -----\nראה לקמן סס\"י שנד."]]],[300010226,"קצב\n\n<b>&lt;והנה</b> בענין הדביקות י\"א&gt; הדביקות הוא כשאומר תיבה אחת הוא מאריך באותה תיבה הרבה, שמחמת דביקות אינו רוצה לפרוד עצמו מהתיבה <span data-k=\"sm\">[ולכך מאריך באותה תיבה]</span> &lt;כו'.&gt;\n<b>&lt;וי\"א</b> הדביקות הוא כשעושה מצוה או עוסק בתורה ועושה הגוף כסא לנפש ונפש לרוח ורוח לנשמה והנשמה כסא לאור שכינה שעל ראשו וכאלו האור מתפשט סביבו והוא בתוך האור יושב ויגיל ברעדה.&gt;",[["","","----- מקורות ומראה מקומות -----\n<i>הדביקות </i>. .<i> באותה תיבה</i>: <b>לקו</b>\"<b>י ג</b>,<b> א (סי</b>'<b> כא) [צוה</b>\"<b>ר סי</b>'<b> ע]</b>\n----- הערות וציונים -----\n<i>הדביקות הוא כו'</i> – ראה לעיל סי' מד ולקמן סי' רפד-ב.\n<i>וי\"א כו'</i> – להעיר מסי' ר ורח. בס' אור הגנוז לצדיקים, פ' בראשית ד\"ה גם ענין הדביקות (הא'), הובא קטע זה בשנוי מעט ובהוספות, ושם במקום \"ורוח לנשמה\" כתב: והדיבור הנקרא רוח ממללא הוא ענף מן הרוח, והכונה הוא ענף מן הנשמה, ועי\"ז נעשה הנשמה כסא לאור השכינה (כו' כבפנים).\n<i>לאור השכינה שעל ראשו</i> – ראה זח\"ג קפז, א."]]],[300010227,"קצג-א\n\n<b>גם</b> <span data-k=\"sm\">[ענין הדביקות ד-]</span> ע\"כ השמים <span data-k=\"sm\">[נראין]</span> כחצי כדור בכל מקום <span data-k=\"sm\">[והאדם נראה לו כאילו עומד במרכז האמצע, זהו ע\"ד שאו מרום עיניכם כו' אליך נשאתי את עיני היושבי בשמים]</span><i>[ftnref_1_כז]</i>.\n<b>כתב</b> ס' חרידים, הצדיק המביט לשמים ירמוז אל עולם עליון נברא ביו\"ד, מן הארץ עד לרקיע מהלך ה' מאות שנה רומז לה\"א, האדם שבארץ עומד על רגליו רומז לוי\"ו, והארץ אשר הוא עומד עליה רומז לה\"א אחרונה שבשם.\n<b>וירמוז</b> ויהי מורא שמים עליכם דייקא, וכאלו השמים ואור שכינה שעליהם שנקרא מורא שמים הוא עליכם ממש, וכאלו האור מתפשט סביבו והוא בתוך האור זהר הרקיע יושב ויגיל ברעדה, והוא יחוד שלם.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>שאו מרום גו'</i> – ישעיה מ, כו. <i>אליך נשאתי את עיני גו'</i> – תהלים קכג, א. <i>כתב ס' חרידים</i> – מצות התשובה פ\"ד. <i>עולם עליון נברא ביו\"ד</i> – מנחות כט, ב. <i>מן הארץ עד כו'</i> – פסחים צד, ב. חגיגה יג, א. <i>ויהי מורא כו'</i> – אבות פ\"א מ\"ג.\n----- שולי הגליון -----\n[ftn_1_כז]) <i>כל זה, עם המילואים, ע\"פ הנוסח בס' אור הגנוז לצדיקים, פ' בראשית ד\"ה גם ענין הדביקות (הב'), ושם ממשיך אח\"כ עם הקטע דלהלן ד\"ה וירמוז.</i>\n----- הערות וציונים -----"]]],[300010228,"קצג-ב<i>[ftnref_1_כח]</i>\n\n<b>והנה</b> האדם העושה מצוה, כגון עטיפת טלית וציצית, אע\"פ שנראה לאדם שהוא דבר קטן, אעפ\"כ הקב\"ה עושה מן מצוה או חדושי תורה לשמה שמים חדשים וארץ חדשה, כמ\"ש כן תתעטף נשמתי באור הציצית העולה תרי\"ג הרומז לתרי\"ג אורות דעוטה אור כשלמה, גאות לבש ה' עוז התאזר, התאזר גי' תרי\"ג, וכמ\"ש ברוכים אתם לה' עושה שמים וארץ חדשים ע\"י מצוה וחדושי תורה שלכם, ומפרש השמים שמים לה', ע\"י הכונה הקדושה שהיא לשם הקב\"ה עושה שמים חדשים, והארץ נתן לבני אדם, פי' ע\"י עשיה גשמיות של המצות עושה הקב\"ה מהן ארצות החיים, ואז היא פעולה חשובה גמורה.\n<b>וז\"ש</b> אל תהיו כעבדים המשמשין את הרב, פי' עם הרב, פי' הקב\"ה שנקרא רב ושליט עקרא ושרשא דכל עלמין, א\"כ ודאי היא פעולה חשובה ונכבדת ודי לך שזכית להיות מסייע לאותה פעולה והרי אתה כמו מסייע שאין בו ממש שהוא עושה עיקר הפעולה למעלה, ויהי' ע\"מ לקבל פרס, וזה פתיות גדול. וזהו שסיים ויהי' מורא שמים עליכם, פי' יהי' לך מורא ממה שהקב\"ה מצמצם בהירות שלו באור זוהר הרקיע ואור שכינה השורה עליך בשעת עשייתך המצות ותורה חדשה לעשות מהם שמים חדשים.\n<b>וז\"ש</b> לך ה' החסד כי אתה תשלם לאיש כמעשהו. &lt;כאלו האיש עשה הכל&gt;, אע\"פ שאין האיש עושה כלום &lt;אלא כמסייע שאין בו ממש&gt;, אעפ\"כ אתה משלם כמעשהו כאלו היה &lt;האיש&gt; <span data-k=\"sm\">[העבד]</span> עושה &lt;הכל&gt; בעצמו, וזהו חסד גדול, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>הקב\"ה עושה כו' חדשה</i> – זח\"א ד, ב ואילך. <i>כן תתעטף כו'</i> – תפילת לשם יחוד קודם עטיפת הטלית. <i>הציצית העולה תרי\"ג</i> – תנחומא קרח יב. במ\"ר יח, כא. זח\"ג רכז, א. <i>עוטה אור גו'</i> – תהלים קד, ב. <i>גאות לבש גו'</i> – תהלים צג, א. <i>התאזר גי' תרי\"ג</i> – מג\"ע פ' ואתחנן. <i>ברוכים אתם גו'</i> – תהלים קטו, טו. <i>השמים שמים גו' והארץ גו'</i> – תהלים קטו, טז. <i>רב ושליט כו'</i> – זח\"א יא, ב. <i>מסייע שאין בו ממש</i> – שבת צג, א. <i>ע\"מ לקבל פרס</i> – אבות פ\"א מ\"ג. <i>לך ה' גו'</i> – תהלים סב, יג.\n----- שולי הגליון -----\n[ftn_1_כח]) <i>ראה לעיל סי' קצא ובשוה\"ג שם.</i>\n----- הערות וציונים -----\n<i>כן תתעטף נשמתי כו'</i> – ראה ר\"ח שער הקדושה פ\"ו.\n<i>התאזר גי' תרי\"ג</i> – במגלה עמוקות פ' ואתחנן. ושם אופן קיג (הובא בילק\"ר פ' ואתחנן).\n<i>עושה שמים וארץ חדשים כו' ארצות החיים</i> – ראה זח\"א ד, סע\"ב ושם ה, רע\"א.\n<i>וז\"ש אל תהיו כו' את הרב פי' עם הרב</i> – ראה מאור עינים, פ' ואתחנן סד\"ה וזהו כוונת הנביא: וכמ\"ש הבעש\"ט נבג\"מ על אמרם ז\"ל אל תהיו כעבדים המשמשין את הרב ע\"מ לקבל פרס, את הרב פי' עם הרב, שעבודתן הוא עם הרב שהוא ממש כביכול עובד כאמור, אלא הוו כעבדים המשמשין את הרב, ע\"י שמשמשין עם הרב צ\"ל שלא ע\"מ לקבל פרס. וממשיך שם: וזהו ג\"כ פי' הפסוק ולך ה' החסד כי אתה תשלם לאיש כמעשהו, כי זהו חסד גדול מהבורא ב\"ה שמשלם לאדם שכר שאע\"פ שהוא בעצמו העושה הכל כמ\"ש מי הקדימני ואשלם (איוב מא, ג) וכדרשת הש\"ס (ויק\"ר כז, ב) כשנתתי לך טלית מקודם עשית בו ציצית בית קבעת בו מזוזה, רק ע\"י חסדו כי חפץ חסד הוא משלם לאדם כמעשיהו כאילו היה האדם העושה אע\"פ שבאמת אין זה מעשיהו.\n<i>אע\"פ שאין האיש עושה כלום כו'</i> – כנ\"ל בהערה מס' מאור עינים, וראה לקמן סס\"י שנד, ריש סי' שצג בד\"ה והשיב, ובצוה\"ר סי' קלח. ולהעיר עוד מלעיל סי' נה ולקמן סי' רסט."]]],[300010229,"קצד\n\n<b>ויענך</b> וירעיבך ויאכילך את המן כו' למען הודיעך כי לא על הלחם לבדו יחיה האדם כי על כל מוצא פי ה' יחיה האדם. וק' דהההי\"ן של ב' פעמים האדם מיותרים, דהוה ליה למימר כי לא על הלחם לבדו יחיה אדם כי על כל מוצא פי ה' יחיה אדם.\n<b>י\"ל</b> שבס' לקוטי תורה מהאריז\"ל, דהחוקרים הקשו מאין הוא חיות הנשמה, דאין הדעת נותן שיהיה חיות הנשמה מלחם ומאכל גשמי, ואין לומר דהנשמה יכולה לחיות בלי מזון כמו מלאך, דא\"כ מה טעם אם עובר אדם ושוהה כמה ימים בלי מזון ימות ברעב, והמיתה הוא פירוד הנשמה מן הגוף, וקשה מה טעם תצא הנשמה מחמת מניעת אכילה כיון שאינה נהנית ממנו. ונבוכו הרבה בזאת החקירה.\n<b>ותירץ</b> האריז\"ל שלא ידעו והיו סכלים בשורש הבריאה, דארז\"ל בעשרה מאמרות נברא העולם, פי' ע\"י המאמרות עצמן נתהוה הכל, דמאמרו של הקב\"ה הוא מרום וקדוש, ותיכף כשאמר הקב\"ה יהי רקיע נתהוה הרקיע, כמ\"ש בדבר ה' שמים נעשו, ונכנס המאמר ההוא בחיות פנימי להחיות הרקיע כל ימות עולם שיעמוד, כמ\"ש לעולם ה' דברך נצב בשמים, וכן כשאמר תוצא הארץ נפש חיה או תוצא הארץ דשא ועץ פרי, אותו המאמר היה מהוה הכל, והמאמר הזה הוא חיות פנימי להם. וכשנוטל אדם פרי או דבר מאכל ומברך עליו בכונה ואומר ברוך אתה ה', כשמזכיר את השם מתעורר אותו החיות שעל ידו נברא הפרי ההוא כי נברא הכל ע\"י השם, ומוצא מין את מינו וניעור, וזה החיות הוא מזון הנשמה. וכל זה במאכלים המותרים וכשרים שצוה הקב\"ה להעלותן מגשמיות לרוחניות.\n<b>וז\"ש</b> ויענך וירעיבך, כי המן היה רוחני מאד וההדיוטות לא היה להם קורת רוח ממנו, דעל כן אמרו ונפשנו קצה כו', וז\"ש ויאכילך את המן, שהוא רוחני מאד, לחם אבירים שמלאכי השרת אוכלין, אלא שנתגשם קצת כדי שיהיה בו תפיסת יד לבני אדם, למען הודיעך אפילו בזמן שתבוא לארץ ישראל ותאכל לחם גשמי, שתקדים כבוד נשמתך לכבוד גופך ולהעלות הכל מגשמיות לרוחניות, כי לא על הלחם לבדו, פי' בזמן שהוא לבדו גשמיות בלי התעוררות הרוחניות, בו יחיה האדם, פי' הנשמה שנקרא האדם בה\"א הידיעה, כי הגוף נקרא בשר אדם והנשמה נקרא האדם, כי על כל מוצא פי ה', פי' כשאתה מוציא השם בכוונה ע\"י הברכה שברכת עליו, שעי\"ז מתעורר בו הרוחניות, מזה יחיה האדם, שהיא הנשמה, ניזונית מרוחניות המאכלים, כי הקב\"ה עשה כן בכוונה מכוונת ע\"י שהיה בונה עולמות ומחריבן נפלו ניצוצין קדישין לד' חלקים שהם דומם צומח חי מדבר שראוי לאדם להעלותם.\n<b>והמשל</b> למלך שנאבדה לו אבן טוב מתוך טבעתו, והנה עמדו לפני המלך בעת ההיא הרבה מעבדיו ושריו הפרתמים והפחות והסגנים מאנשי מלחמתו עד אין מספר, עכ\"ז לא רצה המלך לצוות להם שיחפשו אחר האבן טוב, רק צוה לבנו יחידו וחביבו שיחפש וימצא האבידה ויחזירנה לאביו המלך, הגם שהיה המלך בטוח מכל אחד משריו ועבדיו שכאשר ימצאנו יחזירנו בשלימות, אעפ\"כ לא היה ברצונו שהם יחפשו כי רצה לזכות את בנו חביבו וכדי שיקרא המציאה על שמו. ולא עוד, אלא גם רמז לבנו חביבו בכמה רמזים מקום מציאותו, כי מתחלה היתה האבידה מדעת המלך את מקומה ועשה הכל רק למען לזכות את בנו חביבו, וכדי שיגיע גם להמלך מזה גודל שעשוע והתפארות מבנו לאמר ראו כי שום בן אדם בעולם לא היה יכול לחפוש ולמצוא זולת בנו חביבו. והנמשל מובן, שתחילת בריאת העולמות היה כדי לברר הניצוצין קדישין על ידי אומה ישראלית, כמ\"ש בשביל ישראל שנקרא ראשית, שע\"י יבררו ממאכלים מותרים וכשרים.\n<b>וז\"ש</b> <i>ריב\"ש</i> ע\"פ רעבים גם צמאים נפשם בהם תתעטף, פי' בכאן סוד גדול <span data-k=\"sm\">[ונורא]</span>, והוא למה ברא הקב\"ה דברי מאכל ומשקה שאדם תאב להם <span data-k=\"sm\">[לאכול ולשתות]</span>, והטעם שהם &lt;ניצוץ אדה\"ר שהיו&gt; <span data-k=\"sm\">[ממש ניצוצות אדה\"ר שהם]</span> מתלבשים בדצח\"ם ויש להם חשק להדבק בקדושה, והם מעוררים מיין נוקבין בסוד אין טפה יורדה מלמעלה שאין טפיים עולים כנגדה, וכל אכילה <span data-k=\"sm\">[ושתיה]</span> שאדם אוכל ושותה היא ממש חלק ניצוצות שלו שהוא צריך לתקן. וז\"ש רעבים גם צמאים, כשאדם רעב וצמא להם, למה זה, &lt;ואמר&gt; <span data-k=\"sm\">[וז\"ש]</span> נפשם בהם תתעטף, בסוד גלות &lt;בלבוש&gt; <span data-k=\"sm\">[בלבושי זרים]</span> ויחשבה לזונה כי כסתה פניה, וכל הדברים שהם משמשין לאדם הם ממש בסוד הבני' שלו שהלבישו, והבן.\n<b>והש\"י</b> רמז להם לישראל בכמה רמזים שימצאו האבידה ויחזרו לבעליהם, לאביהם שבשמים, ולא צוה כן למלאכים ושרפים ואופנים, והאבידה ההוא מדעת היתה כמרז\"ל שהיה בונה עולמות ומחריבן.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>ויענך וירעיבך גו'</i> – עקב ח, ג. <i>לקו\"ת מהאריז\"ל</i> – ר\"פ עקב. <i>בעשרה מאמרות כו'</i> – אבות פ\"ה מ\"א. <i>יהי רקיע</i> – בראשית א, ו. <i>בדבר ה' גו'</i> – תהלים לג, ו. <i>לעולם ה' גו'</i> – תהלים קיט, פט. <i>תוצא הארץ נפש חיה</i> – בראשית א, כד. <i>(תוצא) [תדשא] הארץ דשא גו'</i> – בראשית א, יא. <i>ומוצא מין כו'</i> – עירובין ט, א. <i>ונפשנו קצה גו'</i> – חקת כא, ה. <i>לחם אבירים</i> – תהלים עח, כה. <i>שמלה\"ש אוכלין</i> – יומא עה, ב. <i>הגוף נקרא כו' והנשמה כו'</i> – זח\"א כ, ב. זח\"ב עו, א. <i>בונה עולמות כו'</i> – בר\"ר ג, ז. שם ט, ב. <i>בשביל ישראל שנק' ראשית</i> – ויק\"ר לו, ד. <i>וז\"ש ריב\"ש</i> – פירוש הבעש\"ט על הודו. <i>רעבים גם גו'</i> – תהלים קז, ה. <i>אין טפה יורדה כו'</i> – זח\"ג רמז, ב. <i>ויחשבה לזונה</i> – וישב לח, טו.\n----- הערות וציונים -----\n<i>לקו\"ת מאריז\"ל</i> – רג\"כ שער המצות וספר הליקוטים פ' עקב. וראה לעיל סי' נג.\n<i>כמ\"ש לעולם ה' גו'</i> – ראה לקמן בהוספות סי' עז. מדל\"י סי' עא (פג) ובסס\"י עדר (רעט). לקו\"י לג, באמצע ע\"ד (סי' רסה). ולהעיר מפרדס רמונים ש\"ו פ\"ח. וראה לעיל סי' יט.\n<i>וז\"ש ריב\"ש</i> – קטע זה הובא ג\"כ בס' שמועה טובה (סד, ד), בשנויים קלים.\n<i>הגוף נקרא בשר והנשמה נקרא אדם</i> – ראה זח\"ב עו, רע\"א ובאוה\"ח שם. וראה תניא פכ\"ט.\n<i>וז\"ש ריב\"ש</i> – להעיר שבס' שמועה טובה, דף סב, ד, הובא כל קטע זה בפ\"ע בשנויים קלים.\n<i>מאכל ומשקה שאדם תאב להם</i> – ראה לקמן סי' ריח.\n<i>ויש להם חשק להדבק בקדושה</i> – ראה לעיל סי' קכא וקעח."]]],[300010230,"קצה\n\n<b>ריב\"ש</b> אמר, כשהוא דבוק בבורא ית' ונופל לו איזה מחשבה מאיזה דבר, מסתמא הוא כך כמו שנופל במחשבתו, וזהו רוח הקודש מועט.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ב</b>,<b> ג (סי</b>'<b> יב) [צוה</b>\"<b>ר סי</b>'<b> לא]</b>\n----- הערות וציונים -----\nראה לעיל סי' צו-א ובהערות שם, לקמן סי' קצט-א (ובשוה\"ג שם). רג\"כ סי' קצו וריז-ג. ולהעיר מאליהו רבה רפ\"ט (הובא בילק\"ש שופטים רמז מב בשם התנחומא)."]]],[300010231,"קצו\n\n<b>גם</b> אמר &lt;ריב\"ש ז\"ל&gt; מכח התורה שלמד היום ואח\"כ באותו יום מזדמן לו דבר לעשות ואינו יודע אם לעשות אם לא, יוכל להבין מכח אותו הענין שלמד איך יעשה, ובלבד &lt;שיהיה&gt; <span data-k=\"sm\">[שיהא]</span> תמיד דבוק בהש\"י, אז יזמין לו הש\"י תמיד שידע מכח התורה כו'.\n[<b>אבל</b> <span data-k=\"sm\">אדם שהולך בקרי עם הש\"י, הולך עמו ג\"כ באקראי, וגם אינו מזמין לו מלבושים ואכילות שיש בהם ניצוצים השייכים לשורש נשמתו שיתקנם]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ב</b>,<b> ג (סי</b>'<b> יב) [צוה</b>\"<b>ר סי</b>'<b> לא]</b>\n----- הערות וציונים -----\nלהעיר מספרי האזינו סוף פי' שכב. זח\"א יא, א. זח\"ב פב, סע\"ב ושם צו, סע\"ב. זח\"ג נג, ב ושם רס, רע\"א והג' מוהרח\"ו שם. וראה לעיל סי' סז-ב וסי' קצה ובהערות שם. להעיר עוד מס' אור המאיר, פ' פקודי (פז, א) שהבעש\"ט ענה ע\"פ הסתכלות בס' הזוהר (וכן המובא בשבחי הבעש\"ט ע' ס – ונראה שזה העובדא דאי' באוה\"ת להצ\"צ, דרושים לשבועות ע' רכא – ושם ע' עט). וכן בדמ\"א, פ' בראשית ד\"ה וירא אלקים (ונראה שזה העובדא אשר בשבחי הבעש\"ט ע' קלב)."]]],[300010232,"קצז\n\n<b>הנשמה</b> אמרה <i>להרב</i> &lt;זלה\"ה&gt;, שמה שזכה שנתגלו אליו דברים עליונים, לא מפני שלמד הרבה מסכתות ופוסקים <span data-k=\"sm\">[הרבה]</span>, רק משום תפלה שהיה מתפלל תמיד בכוונה גדולה משם זכה למעלה עליונה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ג</b>,<b> א (סי</b>'<b> כח) [צוה</b>\"<b>ר סי</b>'<b> מא]</b>\n----- הערות וציונים -----\nראה לקמן בהוספות סי' רפב. ולהעיר מלעיל סי' יז.\n<i>הנשמה אמרה</i> – להעיר משערי קדושה להרח\"ו ח\"ג ש\"ה וש\"ח."]]],[300010233,"קצח\n\n[<b>כאשר</b> <span data-k=\"sm\">מתחיל האדם להתפלל]</span> מיד כשאומר אדנ-י שפתי תפתח השכינה מתלבשת בו ומדברת &lt;בו כל&gt; הדיבורים, וכשיהיה לו האמונה שהשכינה מדברת <span data-k=\"sm\">[אלו הדיבורים, בודאי]</span> תפול עליו <span data-k=\"sm\">[אימה ו]</span>יראה, וגם הקב\"ה <span data-k=\"sm\">[כביכול]</span> מצמצם <span data-k=\"sm\">[את]</span> עצמו ושורה אצלו כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סי</b>'<b> ד (ג)</b>\n<i>אד' שפתי גו'</i> – תהלים נא, יז.\n----- הערות וציונים -----\nראה לקמן סי' שיג, ת-א ותיא.\n<i>מיד כשאומר כו'</i> – ראה לקמן סי' רעג-א ורעג-ב. שא-ב ושא-ג. שיג. צוה\"ר סי' עה.\n<i>תפול עליו כו'</i> – ראה לקמן סי' רפד-א, שיג ותיא. צוה\"ר סי' פח."]]],[300010234,"קצט-א\n\n<i>[ftnref_1_כט]</i><b>התפשטות</b> הגשמיות &lt;הוא&gt; שאינו מרגיש <span data-k=\"sm\">[במחשבתו]</span> כלל הרגשת הגוף וציור זה העולם, רק ציור העולמות העליונים, דהיינו המלאכים והשרפים. ואחר כך כשבא לעולם האצילות אינו מרגיש רק דק מן הדק, דהיינו אצילותו ית', ושם ידע עתידות, ולפעמים בעולמות התחתונים ידע ג\"כ עתידות ששם מכריזין &lt;הכרוזים&gt; <span data-k=\"sm\">[כנ\"ל]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ד</b>,<b> ב (סוף סי</b>'<b> מט)</b>\n<i>לרקיע הראשון שהוא מהלך כו'</i> – פסחים צד, ב.\n----- שולי הגליון -----\n[ftn_1_כט]) <i>סימן זה הוא קטע שבא בהמשך לזה</i>:\nכשמדבר בדביקות בעולם העליון ואין לו שום מחשבה זרה, ובאה לו מחשבה כמו נביאות, בודאי יהיה כך, והמחשבה באה מחמת הכרוזים שמכריזין למעלה על הדבר. ולפעמים ישמע כמו קול מדבר מחמת שידביק קול העליון ב[קול] תפלתו וקול תורתו, וישמע כמו קול אומר עתידות.\nוצריך לילך ממדרגה למדרגה כשרוצה לעלות למעלה. בתחילה צריך שיהיה במחשבתו לעלות לרקיע הראשון שהוא מהלך ת\"ק שנה, וירחיב במחשבתו הרקיע על כל הרוחות שלא יהא נראה במחשבתו קצר וקטן רק ירחיב לכל הצדדים, וכיון שהוא עומד שם צריך לחזור במחשבתו לעלות למעלה יותר, ואחר כך עוד יותר למעלה, אבל בפעם אחת לא יוכל לעלות לכל השבעה רקיעים, רק ממדרגה למדרגה צריך לעלות. אבל באמצע התפלה, כשדבק עצמו מתחלה כראוי, יכול לעלות לכל הז' רקיעים בפעם אחת.\nובעלותו ממדרגה למדרגה, כשבא לרקיע הראשון צריך לראות שני דברים, אחד שלא יפול למטה, ואחד שיעלה עוד למעלה, וכיון שהוא ממש במחשבתו ברקיע הראשון, יכול לעלות עוד רקיע עד שיעלה בעולם המלאכים, ואחר כך בעולם הכסא, ואחר כך ישאר בעולם האצילות, שם ידביק מחשבתו בבורא יתברך, וכשרוצה לעלות, מתחלה יראה כדמות אדם וכדמות כלבים, שהם הקליפות שיש בכל עולם העשיה, וצריך לחזק עצמו ולא יתיירא.\nולפעמים יכול לדבר למעלה בנשמתו לבד בלי גופו, שיפריש עצמו מגופו, וזהו התפשטות הגשמיות (<i>כבפנים</i>).\n----- הערות וציונים -----\n<i>וצריך לילך ממדריגה כו'</i> – ראה לקמן סי' רפא-א.\n<i>ובעלותו כו'</i> – להעיר מלקמן סי' רטז-א ורטז-ב. צוה\"ר סי' קלה, קלו וקלז.\n<i>התפשטות הגשמיות</i> – ראה שו\"ע או\"ח סי' צח סעיף א. הל' ת\"ת לאדה\"ז פ\"ד ה\"ה. לקמן סי' רלט-ב, רמ-א, רעט, רפד-ב, רצב-ב. וצוה\"ר סי' ה, סב וצז.\n<i>ידע ג\"כ עתידות כו'</i> – ראה לקמן סי' שס."]]],[300010235,"קצט-ב\n\n<b>ריב\"ש</b> אמר בענין עובדא זו, כשאני מדבק מחשבתי בבורא ית' אני מניח הפה לדבר מה שירצה, כי אני מקשר הדברים בשורש העליון בבורא ית', שכל דבר יש לו שורש למעלה בספירות.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ד</b>,<b> ב (סי</b>'<b> נ)</b>\n----- הערות וציונים -----\n<i>מניח הפה כו'</i> – ראה לקמן סי' ריז-ג. וראה לעיל סי' קצח ובהערות שם.\n<i>שכל דבר יש לו שורש כו'</i> – להעיר מזח\"ג קט, ב."]]],[300010236,"ר-א<i>[ftnref_1_ל]</i>\n\n<b>צריך</b> שיהיה דבוק כ\"כ שעיקר ראייתו יהיה בבורא ית', ולא שתהא עיקר ראייתו בעולם ואגב בבורא, לא כן, אלא עיקר ראייתו תהא בבורא ית'.\n[<b>וזה</b> <span data-k=\"sm\">האדם זוכה שיפרדו הקליפות מעליו, כי הם מחשיכים ומבדילים בינו ית' ובין האדם, ומסתימים עיני שכל האדם להסתכל בבורא ית'. ויחשוב שהבורא ית' אין סוף מקיף את כל העולמות ושפעו ית' שופע מלמעלה למטה ע\"י צינורות בכל העולמות, ואנו הולכים תמיד בבורא ית' ואין אנו יכולים]</span> &lt;כי אין אדם יכול&gt; לעשות שום תנועה בלא שפעו וחיותו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ד</b>,<b> סע</b>\"<b>ב (סי</b>'<b> נד)</b>\n----- שולי הגליון -----\n[ftn_1_ל]) <i>קטע זה המשך מהנ\"ל סי' קסט</i>.\n----- הערות וציונים -----\nראה לעיל סי' קסט שהוא רישא דמאמר זה, ולקמן סי' רלב. רג\"כ צוה\"ר סי' קלז ולקו\"י ד, סע\"ב (סי' נב).\n<i>אין אנו יכולים לעשות כו'</i> – ראה לקמן סי' רעג-א."]]],[300010237,"ר-ב\n\n<b>כשמדבר</b> דברי תורה ברבים יהיה כוונתו שיתכבד ויתפרסם הקדושה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ד</b>,<b> ג (סי</b>'<b> נו)</b>\n----- הערות וציונים -----\nראה צוה\"ר סי' צג. ולהעיר מלעיל סי' קיג-ב (ולקמן סי' רנא-ב)."]]],[300010238,"רא-א\n\n<b>כשאדם</b> עובד תמיד את הבורא ית' בכל רגע, אין <span data-k=\"sm\">[לו]</span> פנאי להתגאות ולאהוב <span data-k=\"sm\">[את הגאוה ו]</span>שאר מדות רעות.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ד</b>,<b> ג (סי</b>'<b> נז) [צוה</b>\"<b>ר סי</b>'<b> נב]</b>\n----- הערות וציונים -----\nראה צוה\"ר סי' יו\"ד. ולהעיר ממדל\"י סס\"י פו (צו)."]]],[300010239,"רא-ב\n\n<b>וישים</b> &lt;את&gt; עצמו כמי שאינו, <span data-k=\"sm\">[כדאיתא בגמרא על הפסוק והחכמה מאין תמצא. והכונה שיחשוב]</span> כמו שאינו בעולם הזה, ומה תועלת שאהיה חשוב בעיני בני אדם.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ד</b>,<b> ג (סי</b>'<b> נח) [צוה</b>\"<b>ר סי</b>'<b> נג]</b>\n<i>כדאיתא בגמרא</i> – סוטה כא, ב. <i>והחכמה מאין תמצא</i> – איוב כח, יב.\n----- הערות וציונים -----\nראה לקמן סי' רכ-א, ובצוה\"ר סי' ו וסי' יו\"ד. להעיר מחובה\"ל שער יחוד המעשה פ\"ה. ורג\"כ צוה\"ר סי' קיד."]]],[300010240,"רא-ג\n\n<b>אם</b> חושק לאיזה מצוה, <span data-k=\"sm\">[יראה ו]</span>ישתדל לעשותה, ואל יבטל אותו היצה\"ר לומר שהוא דבר שיוכל לבוא לידי יוהרא, <span data-k=\"sm\">[אעפ\"כ לא יבטלנו. אך יזהר מאוד אף שיבוא לו התפארות באמצע המעשה]</span> &lt;אלא&gt; ידחוק &lt;א\"ע&gt; <span data-k=\"sm\">[אותה]</span> בחוזק ובהתלהבות, ובודאי שלבסוף יעשה לשמה ממש בלי שום התפארות, שמשלא לשמה יבוא לשמה. <span data-k=\"sm\">[וירבה במצות כל מה שיוכל, והקב\"ה יעזור לו שיהיה בלא פניה, אך יתחזק עצמו בכל יכלתו]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ד</b>,<b> ג (סי</b>'<b> ס) [צוה</b>\"<b>ר סי</b>'<b> נה]</b>\n<i>שמשלא לשמה כו'</i> – פסחים נ, ב.\n----- הערות וציונים -----\nראה צוה\"ר סי' קכו (מדל\"י רס\"י קצ (קצח)), ושם סי' נו. וראה לקמן סי' שצג ד\"ה וענין הזה. ועיין מדבר קדמות להחיד\"א, ערך התעוררות.\n<i>וירבה במצות כו'</i> – להעיר מצוה\"ר סי' א ושם סי' יז.\n<i>והקב\"ה יעזור לו כו'</i> – ראה שבת קד, א הבא ליטהר כו'.\n<i>שיהיה בלא פניה</i> – להעיר מצוה\"ר סי' טו ושם סי' צה."]]],[300010241,"רב\n\n<b>להבין</b> מהו קטנות ומהו גדלות. דרך משל, כשאדם יושב ולומד תורה שלא בהבנה אז &lt;היא הקטנות&gt; <span data-k=\"sm\">[הוא בקטנות]</span>, שאין שכלו שלם, אבל כשהוא לומד בהבנה ובהתלהבות אז הוא במדריגות גדלות, שמקושר במדריגות העליונים. וכן בתפלה ובכל מצוה <span data-k=\"sm\">[שעושה האדם]</span> יש קטנות וגדלות.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ה</b>,<b> סע</b>\"<b>א (סי</b>'<b> עד) [צוה</b>\"<b>ר סי</b>'<b> קכט]</b>\n----- הערות וציונים -----\n<i>מהו קטנות ומהו גדלות</i> – ראה לעיל סי' לז וש\"נ בהערות. רג\"כ צוה\"ר סי' סז, סט, צו וקלז."]]],[300010242,"רג\n\n<b>גם</b> יחשוב כשיושב ללמוד, או אפי' בדברי חולין, אזי יחשוב באיזה ענין הוא מדבר, אם באהבה או ביראה או רחמנות או בניצוח או בהודיה או בהתקשרות או באיזה ממשלה, ויתקשר א\"ע במדה ההיא.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ה</b>,<b> סע</b>\"<b>א (סי</b>'<b> עה)</b>\n----- הערות וציונים -----\nראה לקמן סי' רצה ותו. רג\"כ סי' רכז וצוה\"ר סי' צ."]]],[300010243,"רד-א\n\n<b>העוסק</b> בתורה לשמה, פי' לשם ה', זוכה לדברים הרבה, פי' ממילא נתרבה אליו הדיבור בחכמת התורה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ה</b>,<b> ריש ע</b>\"<b>ב (סי</b>'<b> עו)</b>\n<i>העוסק בתורה לשמה</i> – אבות פ\"ו מ\"א. <i>לשם ה'</i> – שער המצות להרח\"ו פ' ואתחנן.\n----- הערות וציונים -----\nראה לעיל סי' צו-א, קכז-ב ובהערות שם. לקמן סי' תכו.\n<i>לשמה לשם ה'</i> – ראה שער המצות פ' ואתחנן. שער מאמרי רז\"ל, אבות. פע\"ח שער הנהגת הלימוד. ועיין לעיל בהערות לסי' קמב מהקדמת ס' תוי\"י."]]],[300010244,"רד-ב\n\n<b>&lt;כי&gt;</b> כשאדם מדבר דיבור טוב, והדיבור הוא החיות של האדם, והחיות הוא ממנו ית', אז הדיבור סלקא לעילא ומתעורר הדיבור העליון ומשפיע עליו יותר חיות מלמעלה.\n[<b>אבל</b> <span data-k=\"sm\">כשהוא מדבר דיבור רע, אזי יוצא ממנו החיות, ולעילא ג\"כ לא סלקא, אז קרוב הדבר להיות נפסק ממנו כל החיות לגמרי, וזה ג\"כ מה שאנו אומרים בל\"א ער האט אויש</span><span data-k=\"sm\">-</span><span data-k=\"sm\">גירעט].</span>",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ה</b>,<b> ב (סי</b>'<b> עז) [צוה</b>\"<b>ר סי</b>'<b> קג]</b>\n----- הערות וציונים -----\nעיין בס' ערבי נחל, פ' וישלח בריש ד\"ה ואמר עוד נפשי יצאה בדברו: כי הנה כ' הבעש\"ט זלל\"ה כי ענין רוח האדם בקרבו וחיות שלו הוא כח הדיבור אשר בקרבו, וכמשה\"כ ויפח באפיו נשמת חיים ויהי האדם לנפש חיה (בראשית ב, ז) ומתרגמינן לרוח ממללא, ולפ\"ז כשהאדם מדבר דיבורים אזי הדיבורים ההם הן הן חיותו ויוצא חיות שלו באותן הדיבורים, רק שלהיות חיות האדם דבוק תמיד בשורשו לכן הדיבורים ההמה עצמן ממשיכים עליו משרש חיות חדש ועי\"ז חי תמיד, אף שבכל דיבור יוצא חיות מקרבו רק כל דיבור עצמו מביא לו חיות חדש עכ\"ד. ועיי\"ש בהמשך מה שהאריך בענין דיבורים טובים ודיבורים לא טובים, ושם: כאשר האדם מדבר דיבורים טובים הנה אף שנפשו יוצאת ממנו אין לו פסידא בדבר כי אדרבה נמשך לו נפש וחיות חדש ממקום הקדוש ההוא נמצא שאותו חיות עצמו שיוציא הוא הבא לו ביתר שאת ויתר עוז, משא\"כ בדברו דיבורים רעים אז נפשו הטובה יוצאה ורעה באה תחתיה וזה הפסד גדול כו' עיי\"ש. ועיין לקמן סי' רעג-ב. ולהעיר מס' מדבר קדמות להחיד\"א, מערכת ד אות כא (דיבור).\n<i>והדיבור הוא החיות של האדם כו' ממנו ית'</i> – ראה לקו\"ת להאריז\"ל פ' עקב (ועיין מש\"כ על זה במדבר קדמות שם, ובלב דוד פכ\"ב ופכ\"ג). וראה הערה הקודמת, ובלקו\"י סי' – וקב. ועיין צוה\"ר סי' פח ובהערות שם.\n<i>הדיבור סלקא לעילא ומעורר כו'</i> – ראה זח\"ג לא, ב (הובא בר\"ח שער הקדושה ספ\"י עיי\"ש). וראה ג\"כ זח\"ב מז, ב וזח\"ג קה, א."]]],[300010245,"רה\n\n<b>הלואי</b> שיהא מורא שמים עליכם כמורא בשר ודם, <span data-k=\"sm\">[הלואי הוא לשון חבור ודמיון דבר לדבר, כלומר תדמה מורא שמים למורא בשר ודם]</span>. למשל, כשישן ובא רבו והקיץ אותו בידו, מיד הוא נרתע ונזדעזע <span data-k=\"sm\">[בדביקות להשי\"ת, וישגיח על הכל, על כל אשר יראה וישמע]</span> לפניו, ומכ\"ש כשהשי\"ת מקיצו משנתו שהוא בחצות לילה כידוע.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ה</b>,<b> ג (סי</b>'<b> פו)</b>\n<i>הלואי שיהא כו'</i> – ברכות כח, ב. <i>כשהשי\"ת כו' בחצות לילה</i> – זח\"ב לו, ב.\n----- הערות וציונים -----\n<i>לשון חיבור</i> – ראה תיב\"ע ומדרש בראשית רבתי לויצא כט, לד. שמ\"ר א, ה. זח\"א קנד, ב וזח\"ב יט, רע\"א.\n<i>ומכש\"כ כשהשי\"ת מקיצו כו'</i> – ראה צוה\"ר סי' כו."]]],[300010246,"רו-א\n\n<b>אין</b> כאלהינו הוא בעולם העשיה, שהוא כמו ספר שבודאי א\"א לטעות. מי כאלהינו הוא ביצירה, שאפשר חלילה לטעות, כמו אחר שראה מט\"ט וכו'. אך אני איני טועה כי מי כאלהינו. נודה לאלהינו הוא בבריאה, ששם א\"א לטעות מפני שקרובה לאצילות. ובאצילות אומר לנוכח &lt;ברוך, וגם&gt; אתה הוא אלהינו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ה</b>,<b> ד (סי</b>'<b> צו)</b>\n<i>אין כא</i>-<i>להינו הוא בעולם העשי' כו'</i> – סידור האריז\"ל להר\"ש קיד, ב. <i>כמו אחר שראה כו'</i> – חגיגה טו, א.\n----- הערות וציונים -----\nעיין בסידור האריז\"ל להר\"ש שם בפיוט דאין כאלקינו, ברם שם דבבא דברוך נגד אצילות שהוא ברוך מהא\"ס כו' ובבא דאתה הוא נגד עולמות הנעלמים וכולהו אקרי א\"ס כו'."]]],[300010247,"רו-ב\n\n<b>טעם</b> למה אנו אומרים אלהינו ואלהי אבותינו. כי יש שני מיני בני אדם המאמינים בהש\"י. א' שמאמין בהקב\"ה מחמת &lt;קבלת אבותיו&gt; <span data-k=\"sm\">[שהולך בדרכי אבותיו הקדמונים]</span>, ועכ\"ז אמונתו חזקה. והב' מי שבא על האמנת הדת מחמת החקירה. והחילוק ביניהם הוא, שהא' יש לו מעלה שא\"א לפתות אותו אף אם יאמרו לו כמה חקירות הסותרות ח\"ו, כי אמונתו חזקה מצד קבלת אבותיו, ועוד שלא חקר מעולם, אבל יש לו חסרון, שהאמונה אצלו הוא רק מצות אנשים מלומדה, בלי טעם ושכל. אבל הב' יש לו מעלה, שמחמת שהכיר הבורא ית' מחמת גודל חקירתו היא חזק אצלו באמונה שלימה ובאהבה גמורה, אבל ג\"כ יש לו חסרון, שבקל יכול לפתותו, ואם יביאו לו ראיות הסותרות אמונתו יתפתה ח\"ו. אבל מי שב' המדות בידו אין למעלה ממנו, דהיינו שסומך על אבותיו הקדמונים בחוזק, וג\"כ באה לו שחקר בעצמו, זו היא אמונה שלימה וטובה. ולזה אנו אומרים אלהינו &lt;מצד חקירתנו&gt; ואלהי אבותינו &lt;מצד קבלתינו&gt;. &lt;וכ\"כ בתשובת פנים מאירות, דעכ\"א אלקי אברהם אלקי יצחק ואלקי יעקב ואין אומרים אלקי אברהם יצחק ויעקב, לומר לך דיצחק ויעקב לא סמכו על קבלתם מאברהם אלא חקרו האלקות בעצמם&gt;.\n[<b>גם</b> <span data-k=\"sm\">בזה יש לפרש הפסוק טעמו וראו כי טוב ה', ר\"ל טעמו מחמת החקירה וראו הוא לשון ראיית הנהגה כמו שהנהיגו אבותינו]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יז</b>,<b> סע</b>\"<b>א (סי</b>'<b> קצט)</b>\n<i>מצות אנשים מלומדה</i> – ע\"פ ישעי' כט, יג. <i>בתשובות פנים מאירות</i> – ח\"א סי' לט. <i>טעמו וראו גו'</i> – תהלים לד, ט.\n----- הערות וציונים -----\nבדברות שלמה, פ' שלח בד\"ה עוד אפשר לומר, הובא זה בשם הרה\"מ. וראה לעיל סי' ג. רג\"כ לקו\"י סי' קכט (באו\"ת סי' רנה) – וקטע משם לקמן סי' רי. ולהעיר מאו\"ת סי' שס (צג, א) ור\"מ נקרא השכל כי מה שאנו אוהבים אותו ית' מפני שאנו מאמינים בו ית' והאמונה הוא מכח השכל שאנו מבינים שיש מנהיג כו' עיי\"ש (וכן הוא באור המאיר, דרוש לר\"ה ד\"ה ואתא חד (כד, ב) בשם הרה\"מ, ועיי\"ש היטב מה שהאריך בזה). ולהעיר מחובה\"ל ריש שער היחוד. מו\"נ ח\"א פל\"ג. וספר החינוך סי' כה.\n<i>וכ\"כ בתשובות פ\"מ</i> – ראה אוה\"ת על סידור תפילה, ע' קפז."]]],[300010248,"רז-א\n\n<b>יראה</b> חצונית הבאה לאדם הוא כדי לעוררו ליראת אלקים. מלה\"ד לאיש חיל שלוח מהמלך לקרוא לאדם והוא בכעס גדול ובפחד, אין לירא מהשליח כ\"א תיכף ילך להמלך לרצותו. וכן אהבה חיצונית הבאה הוא כדי לעוררו לאהבת ה'. מלה\"ד, לפעמים בא איש מהמלך שלוח לאדם בתנועת אהבה, ומי שהוא טפש הוא מתענג ומשתעשע עם השליח, והחכם אומר מה לי להשתעשע עם השליח, אלך לשורש האהבה של מלך.\n<b>וזהו</b><i>[ftnref_1_לא]</i> שכתוב תמים תהי' עם ה' אלקיך, והתי\"ו גדולה, דלכאורה התי\"ו רחוקה מן האלף, לרמוז להעלות כל דבר רחוק, הן אהבה הן יראה או שמחה ותענוג גשמי, אל האלף הרומז לאלופו של עולם.",[["","","----- מקורות ומראה מקומות -----\n<b>קיצור מדל</b>\"<b>י סי</b>'<b> ריג (רכג</b>-<b>רכד) [ובלקו</b>\"<b>י ו</b>,<b> א (סי</b>'<b> צח)</b>,<b> עד סוף הנמשל]</b>\n<i>תמים תהי' גו'</i> – שפטים יח, יג. <i>לאלופו של עולם</i> – זח\"ג לא, א. <i>אמירה לגבוה כו'</i> – קידושין כח, ב.\n----- שולי הגליון -----\n[ftn_1_לא]) <i>נוסח הפיסקא במקורו</i>: ואם נפשך לומר איך יכול האדם להעלות במחשבתו כל דבר להיות ממותק בשורשו, אך כי הנה כתיב תמים תהיה עם ה' אלהיך, ותי\"ו דתמים רבתי, דלכאורה התי\"ו רחוק מאל\"ף ד' מאות מדריגות והיאך יכול להאיר בה האל\"ף, אך באמת אמירה לגבוה כמסירה להדיוט דמי, ר\"ל דרך משל אם אדם רוצה לעלות כשהוא עומד במדרגה תחתונה, אינו יכול להגיע ולהשיג למעלה העליונה רק כשהוא הולך ממעלה למעלה, אבל אם הוא עומד שם למעלה יכול להעלות מלמטה ברגע אחד, וזהו אמירה לגבוה כו', דרך משל קטן צריך לילך יותר מגדול, והמחשבה גם כן גדול ממעשה הרבה ולכן אין צריך רק שיחשוב במחשבתו ומעלה תיכף לשרשו, ולכך התי\"ו משתוקק לאל\"ף ויש בו כל הד' מאות אלפי\"ן, ולכך התי\"ו גדולה שהם מאותיות המחשבה.\n----- הערות וציונים -----\n<i>יראה חיצונית </i>. .<i> ליראת אלקים</i> – ראה לעיל סי' לח-א ולח-ב, קעז וקפ.\n<i>מלה\"ד</i> – המשל הובא ג\"כ בלקו\"י-יד\"א פי\"ז. להעיר מהמשל בזח\"ב נא סע\"ב.\n<i>התי\"ו רחוק מאל\"ף כו'</i> – ראה לעיל סי' מה, קס וקצ, ולקמן סי' שנה.\n<i>תי\"ו גדולה שהם מאותיות המחשבה</i> – דאתוון רברבין מההוא עלמא דאתי (זח\"ב קלב, ב) איהו בינה (שם כז, סע\"ב) עולם המחשבה (זח\"ג רכט, סע\"ב). וראה אוה\"ח לזח\"א ג, ב."]]],[300010249,"רז-ב<i>[ftnref_1_לב]</i>\n\n<b>והנה</b> ידוע שהאותיות נקראים כלים, והנקודות הם חיות ונשמות הכלים. והנה האדם כשמחשב איזה מחשבה מה שיהי' הוא אותיות, וכבר ידעת שאם באה לאדם איזה מחשבה זרה בלמודו או בתפלתו אינה מקריות, כי יש עת לכל חפץ, וכמ\"ש ובהגיע תור נערה ונערה לבוא כו', שהוא הניצוץ הנתונה בעמקי הקליפות <span data-k=\"sm\">[הנקרא נערה]</span> שמנוערת מכל &lt;טוב&gt; ורוצה להתדבק בשרשה, והגיע עת וזמן להעלותה בקדושה, הנה אז צריך להתעורר <span data-k=\"sm\">[מאד]</span> מאד, כי לא לחנם באה <span data-k=\"sm\">[זאת]</span> המחשבה אלא להעלותה, ואם לא עכשיו אימתי, אפשר לא יהיה עוד עת ותור הנערה ההיא, כי ע\"פ רוב המחשבה באה מענין הדומה לענין התפלה והברכה &lt;ההיא&gt; <span data-k=\"sm\">[או מענין הלימוד שהוא עוסק]</span>.\n<b>ומלה\"ד</b> לבן חביב &lt;שלקח אביו מנסה לנסות בנו בדבר ההלכה, והנה המנסה מקשה אותו קושיות שונות ורוצה להתעותו מדרך הפשוטה להעקומה, והנה לא הי' ח\"ו כוונת האב לסתור דברי בנו ולהטעותו שישאר מבוכה וטועה, אלא לחדודי קמכוין, שיעשה הבן תשובות נגד הקושיות ויתרצם&gt;<i>[ftnref_2_לג]</i> וידרוך בדרך האמת והישר בפשט ההלכה, וזהו רצון האב ושמחתו, כמ\"ש חכם בני ישמח לבי &lt;ואשיבה חורפי דבר&gt;.\n<b>והנמשל</b> מובן, &lt;שהמנסה הוא היצר הרע והמ\"ז, ובאמת הוא לסיבת שיעלה אותה האדם, ע\"כ&gt; כאשר באה מ\"ז צריך להתעורר מאד ולהעלותה בקדש עם אותן מחשבות קדושות שמכוין ומייחד ועם הדיבורים שהוא מדבר.\n<b>וז\"ש</b> מטבילין כלים בתוך כלים, &lt;כלים הם&gt; אותיות של המ\"ז, יטבול ויטהר בתוך כלים שהם אותיות הקדושה, ועי\"ז יחבר הכל לקדש העליון.\n<b>וז\"ש</b> אם בחקותי <span data-k=\"sm\">[תלכו, ואמרו רז\"ל]</span> שזהו לימוד התורה, <span data-k=\"sm\">[ואומר לשון]</span> תלכו, &lt;ממדריגה למדריגה&gt; <span data-k=\"sm\">[כלומר, שתלכו תמיד, ולא עומדים במקום א' במדריגה א', אלא שתלכו תמיד הילוך העולה ממעלה למעלה בדביקות ובהתלהבות עד שמגיע למדרגה עליונה לדבק מחשבותיכם למעלה בכל העולמות, כמו מי שיעלה מעולם לעולם, כענין ד' שנכנסו לפרדס מרוב הדביקות והמחשבות טהורות וזכות. ואז]</span> ונתתי גשמיכם, כלומר שגם הגשמיות <span data-k=\"sm\">[והחומריות]</span> שלכם יזדככו, וגם הניצוץ יעלה, בעתם, ר\"ל בעת הצורך שיוכל <span data-k=\"sm\">[לעלות]</span> &lt;אדם להעלותו&gt;, יזדמן לכם המ\"ז בכדי לזכותכם בהעלות הניצוץ, ולא כמו שאר בני אדם שבאה המ\"ז מחמת מחשבותם שלא מטוהרה מדברים הגשמיים, ולא כן אתם ההולכים בחקותי <span data-k=\"sm\">[כנ\"ל, ואם תבוא לכם מ\"ז תוכלו להעלותה אל הקדושה]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>קטע מלקו</b>\"<b>י ז</b>,<b> ד (סי</b>'<b> קיח)</b>\n<i>שהאותיות כו' והנקודות כו'</i> – ע\"ח ש\"ה פ\"ה. כוזרי מ\"ד אות ד. <i>עת לכל חפץ</i> – קהלת ג, יז. <i>ובהגיע תור גו'</i> – אסתר ב, יב. <i>ואם לא עכשיו כו'</i> – אבות פ\"א מי\"ד. <i>חכם בני גו'</i> – משלי כז, יא. <i>מטבילין כלים כו'</i> – חגיגה כ, ב. <i>אם בחקותי גו'</i> – בחקותי כו, ג. <i>ואמרו רז\"ל שזהו כו'</i> – ספרא ר\"פ בחקותי הובא ברש\"י עה\"פ. <i>ד' שנכנסו לפרדס</i> – חגיגה יד, ב. <i>ונתתי גשמיכם גו'</i> – בחקותי כו, ד.\n----- שולי הגליון -----\n[ftn_1_לב]) <i>סי' רז</i><i>ב</i><i> הוא המשך להמובא בסי' רח וצ\"ל סימן אחד בהיפוך הסדר</i>.\n[ftn_2_לג]) <i>שנה לשון המשל</i>,<i> ובמקורו</i>:\nמשל לבן חביב האומר לפני אביו דבר הלכה, והנה אביו מקשה אותו קושיות שונות ומתעהו מדרך הפשוט. והנה אין ח\"ו כוונת האב לסתור דברי בנו ולהטעותו שישאר מבוכה וטועה, אך אדרבא האב לחדודי הוא מתכוין, שיעשה הבן דבר נגדיות נגד קליפות הקושיות ויתרץ וידרוך <i>(כבפנים)</i>.\n----- הערות וציונים -----\n<i>שהאותיות נק' כלים כו'</i> – להעיר מלקמן סי' רעט.\n<i>אינה מקריות כי יש כו'</i> – ראה מדל\"י סי' רלח (רנא). ורג\"כ לעיל סי' לט.\n<i>ומלה\"ד כו'</i> – ראה לעיל סי' קעב. צוה\"ר סי' קלח.\n<i>תלכו כו' שתלכו תמיד כו'</i> – ראה לקו\"ת לאדה\"ז, בחקותי מה, א. ולהעיר מלקו\"י סי' עב.\n<i>ולא כשאר בני אדם כו'</i> – עיין תניא ר\"פ כח."]]],[300010250,"רח\n\n<b>חומר</b> בקודש מבתרומה <span data-k=\"sm\">[שמטבילין כלים בתוך כלים וכו']</span>, כי הלא נודע שעיקר עבודת &lt;ה'&gt; <span data-k=\"sm\">[הבורא ית']</span> הוא הדביקות והתלהבות בעבודת הש\"י ובלימוד תורתו <span data-k=\"sm\">[שיהיה]</span> בדחילו ורחימו, &lt;כי עי\"ז&gt; <span data-k=\"sm\">[ומחמת זה יכול הוא לידבק בהש\"י כביכול, מפני ש]</span>ההבל שבדיבורם מתדבק בהבל העליון והקול בקול העליון והדיבור בדיבור העליון וכן המחשבה, <span data-k=\"sm\">[וכמו שאמרו רז\"ל השכינה מדברת מתוך גרונו של משה, מחמת גודל קדושתו ודביקותו בהש\"י היה ממש מתחבר עם שרשו, והרי הוא כמו הקב\"ה היה מדבר דבורו של משה, ועי\"ז נזדכך חומריותו ונעשה איש האלהים, וכמ\"ש של נעליך, שהוא לבוש החומרי]</span>.\n<b>וזהו</b> <span data-k=\"sm\">[אפשר]</span> רמז <span data-k=\"sm\">[המשנה]</span> חומר בקודש, כלומר אם תרצה לזכות חומרך שיהי' בקודש העליון שהוא המחשבה העליונה, א\"א אלא מבתרומה, פי' <span data-k=\"sm\">[שצריך שתרים תמיד עיניך ולבך ותטהר מחשבותיך ורעיוניך במחשבת הש\"י ודביקות גמור והתלהבות גדולה]</span> &lt;ע\"י הקול והדיבור שהם תרי ממאה ברכות שצריך אדם לברך בכל יום ע\"י קול ודיבור&gt;, וזה ידוע שבמקום שהאדם מחשב שם הוא ג\"כ במקום ההוא, ואם כן כשתתמיד ותרגיל עבודתך בכך, בודאי תרום ותעלה במקום המחשבה העליונה &lt;שנקרא קודש&gt; <span data-k=\"sm\">[אל שורשה]</span>, ואז גם חומר שלך תזדכך בקודש העליון כנ\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>קטע מלקו</b>\"<b>י ז</b>,<b> סע</b>\"<b>ג (סי</b>'<b> קיח)</b>\n<i>חומר בקודש כו'</i> – חגיגה כ, ב. <i>השכינה מדברת כו'</i> – זח\"ג רלב, א. <i>איש האלקים</i> – ברכה לג, א. <i>של נעליך</i> – שמות ג, ה. <i>שהוא לבוש החומרי</i> – תקו\"ז תכ\"א מח, ב. שם תל\"א עו, א. <i>ממאה ברכות כו'</i> – מנחות מג, ב.\n----- הערות וציונים -----\n<i>שעיקר עבודת הבורא ית' כו'</i> – להעיר ממדל\"י סי' ריג (רכג).\n<i>ההבל כו' והקול כו' והדיבור כו'</i> – ראה לקמן סי' ריא ושא-ב.\n<i>שהם תרי ממאה ברכות כו'</i> – להעיר מזח\"ג קעט, א ע\"פ המבואר לקמן סי' ריא.\n<i>במקום שהאדם מחשב כו'</i> – ראה לעיל סי' נו ובהערות שם."]]],[300010251,"רט\n\n<b>שש</b> אנכי על אמרתיך כמוצא שלל רב, ואע\"פ שלקח המוצא ממנו, מ\"מ מצטער מאד על שנשאר הון רב שא\"א לקחתו כולו. כן אף על פי שלמדתי תורה הרבה, מ\"מ נשאר הרבה מאד שא\"א ללמדו כולו, כי ארוכה מארץ כו'<i>[ftnref_1_לד]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>קיצור לקו</b>\"<b>י ח</b>,<b> ב (סי</b>'<b> קכ)</b>\n<i>שש אנכי גו'</i> – תהלים קיט, קסב. <i>ארוכה מארץ גו'</i> – איוב יא, ט. <i>אף שלמדתי תורה הרבה כו'</i> – ע\"פ אבות פ\"ב מ\"ח.\n----- שולי הגליון -----\n[ftn_1_לד]) <i>קיצור מהמובא בלקו\"י</i>,<i> וז\"ל שם</i>: בפסוק שש אנכי על אמרתך כמוצא שלל רב. יש להקשות למה מדמהו למוצא שלל רב. וי\"ל משל לאדם ההולך בדרך ומצא אוצר רב עד אין מספר, והנה האדם ההוא לוקח מן האוצר ממון רב ועצום כל אשר יוכל שאתו, והיה לו שמחה גדולה, וברצותו ללכת משם, ראה שנשאר הרבה מן האוצר הון רב ליקח עד אין מספר, מפני שלא היה יכול לקבל מחמת שאין לו כלים לקבל בתוכם, והיה לו צער מזה.\nוז\"ש שש אנכי על אמרתך, מה שלמדתי וקבלתי, אבל בגמר לימודי, אף שלמדתי תורה הרבה, אין אני מחזיק טובה לעצמי, כי יודע אני חסרוני ומכיר בעצמי חסרון ידיעת התורה מה שחסרתי, שלא למדתי וקבלתי ממנה אלא כטפה מן הים, דוגמת זה המוצא שלל רב.\n----- הערות וציונים -----\n<i>יודע אני חסרוני כו'</i> – ראה פירוש רבינו יונה לאבות פ\"ב מ\"ח."]]],[300010252,"רי\n\n<b>יעקב</b> ראה בעין השכל שמן ההכרח שיש בהנהגת העולם מדה הממוצעת והמכריע בין <span data-k=\"sm\">[חו\"ג]</span> &lt;מדת החסד ומדת הדין&gt;, שאילולי כן לא היה העולם מתקיים אם היה נוטה לא' משני הקצוות <span data-k=\"sm\">[הנ\"ל]</span>, לכן המתדבק במדת התפארת שהוא &lt;מדת ה&gt;רחמים המכריע בין חו\"ג, ומתוך זאת המדה שהשיג והכיר יותר מאבותיו &lt;ע\"כ&gt; הוא בחיר שבאבות, כי <span data-k=\"sm\">[בזה]</span> &lt;בזאת המדה&gt; העולם מתנהג בתמידות, כמשרז\"ל ראה שאין העולם מתקיים בדין ושיתף עמו מדה\"ר.",[["","","----- מקורות ומראה מקומות -----\n<b>קטע מלקו</b>\"<b>י י</b>,<b> סע</b>\"<b>א (סי</b>'<b> קכט)</b>\n<i>יעקב כו' העולם מתקיים</i> – ר' זח\"א קנד, ב. זח\"ג שב, א. <i>התפארת שהוא רחמים המכריע כו'</i> – זו\"ח יתרו לא, סע\"ב. <i>בחיר שבאבות</i> – בר\"ר עו, א. <i>ראה שאין העולם כו'</i> – בר\"ר יב, טו.\n----- הערות וציונים -----\n<i>בעין השכל</i> – ראה לעיל בהערות לסי' קסט. ולהעיר ממדל\"י סי' קיח (קכח) יעקב הוא נקרא עין כמש\"כ עין יעקב (וזאת הברכה לג, כח). וראה מזה בלקו\"י סי' רעא.\n<i>בזאת המדה העולם מתנהג כו'</i> – להעיר ממדל\"י סי' רסה (רעג)."]]],[300010253,"ריא\n\n<b>צריך</b> <i>[ftnref_1_לה]</i> האדם להעלות הדיבורים מתתא לעילא אל שרשם, דהיינו כשאדם מדבק ומחבר דיבור עם דיבור, וקול עם קול, והבל עם הבל, ומחשבה עם מחשבה, שהם ד' אותיות שם הוי' כידוע. ואם האדם עושה כן, כל דבוריו פרחין לעילא אל שרשם, ובזה הוא גורם שהדיבורים באים לפניו ית' ומסתכל בהם, ובזה הוא נענה בתפלתו. כי ההסתכלות הוא כעין ההשפעה מעילא לתתא, שכאשר הש\"י מסתכל &lt;בהם&gt; הוא קיום העולמות כולם, כי למעלה אין שם שעות וזמן, כי ברגע א' באה ההשפעה מהמעיין העליון הנובע תמיד ודרכו להטיב ולהשפיע לבריותיו, רק כשיהיה המקבל ראוי לקבל, ואם הוא מתפלל או לומד תורה בענין הזה, הוא נעשה כצנור אל המעיין העליון הממשיך ומשפיע שפע טובה לו ולכל העולם כולו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י י</b>,<b> ד (ריש סי</b>'<b> קלא)</b>\n<i>בזוהר</i> – תקו\"ז ת\"י כה, ב. <i>קול ודבור הם נגד זו\"נ</i> – תקו\"ז תס\"א צג, סע\"ב. <i>ו\"ה של (שם) הוי'</i> – תקו\"ז ת\"ע קלב, א. <i>דו\"ר שהם או\"א כו'</i> – תקו\"ז ת\"י כה, ב. <i>כמ\"ש באורייתא כו'</i> – זח\"א ה, א.\n----- שולי הגליון -----\n[ftn_1_לה]) <i>במקורו כתוב לפני זה</i>:\nבזוהר האי מילה דלא נפקי בדחילו ורחימו לא פרחי לעילא, פי' כי קול ודיבור הם נגד זו\"ן שהם ו\"ה של הוי' ב\"ה ואם נפקי בלא דחילו ורחימו שהם אבא ואמא י\"ה של השם הוא עושה פירוד ח\"ו. ובפרט שכל כוונתו בתפלה ובלימוד כדי ל[ה]עלות הדיבורים אל שורשם מתתא לעילא, כי כמו שבתחילת בריאת העולמות היה בכ\"ב אותיות התורה, כמ\"ש באורייתא אברי עלמא, שהם הכ\"ב אתוון, ומהם היה התפשטות וקיום העולמות מעילא לתתא, כך צריך האדם <i>(כבפנים)</i>.\n----- הערות וציונים -----\n<i>בכ\"ב אותיות התורה</i> – ראה זח\"א רד, א. וראה לקמן סי' שנה.\n<i>מדבק ומחבר דיבור כו'</i> – ראה לעיל סי' רח, ולקמן סי' שא-ב.\n<i>שהם ד' אותיות הוי'</i> – דמחשבה איהי חכמה (יו\"ד) – תקוזו\"ח ק, ב; תקו\"ז יז, א ושם תי\"ט מא, סע\"ב; הבל איהו בינה (ה' עלאה) – תקו\"ז תכ\"ב סג, סע\"ב ושם תס\"ט קה, ב וקיז, ב; קול איהו ת\"ת (ו) – זח\"ג רפג, א ותקו\"ז ת\"י כה, ב ושם תל\"ח עט, א; דיבור איהו מלכות (ה' תתאה) – זח\"א קמה, סע\"א וזח\"ג רכח, א.\n<i>ההסתכלות הוא כעין ההשפעה</i> – להעיר מע\"ח ש\"ח פ\"ה בענין בת היענה. ומדל\"י ריש סי' צג (קב)."]]],[300010254,"ריב\n\n<b>&lt;ענין</b> איסור אפי' שאלת שלום קודם התפלה&gt;, כי ידוע שהעולם נברא ע\"י מחשבה ודיבור ומעשה, וראשית הכל הוא המחשבה, והדיבור הוא ענף המחשבה, והמעשה הוא ענף הדיבור. וכמו כן האדם בקומו משנתו שהוא נעשה בריה חדשה &lt;כמ\"ש&gt; חדשים לבקרים, אם ידבר תחלת דבריו דברי הרשות, &lt;וכ\"ש&gt; <span data-k=\"sm\">[ופשיטא]</span> דברים אשר לא כן, אף אם יתפלל ויעסוק בתורה אח\"כ, הכל מסתעפין ונמשכין אחר הדיבור הראשון. כי כמו שהדיבור הוא ענף המחשבה וטפילה אליו, כן הדיבור השני אל הראשון, כמ\"ש בזוהר ובכתבי האריז\"ל בענין כיבוד אח הגדול, <span data-k=\"sm\">[מפני שאח הבכור נוטל חלק העיקרי ושארי אחיו הם המסתעפין ממנו וענפים אליו, כן הוא כאן]</span>.\n<b>ולכן</b> יזהר האדם שיקדש ויטהר דיבורו הראשון &lt;בקומו&gt;, ויזכך מחשבתו הראשונה דבוקה בקדושה, כדי שימשיך אלי' כל שארי הדבורים שאחריה. ואח\"כ כשיעמוד בתפלה מתוך שמחה של מצוה &lt;כנ\"ל&gt; כמו שקידש דיבורו ומחשבתו כנ\"ל, בודאי יהי' נענה בתפלתו. &lt;וכן יקדש א\"ע ודיבורו בשכבו כדי שלא יבוא לידי מקרה לילה ח\"ו. וז\"ש הדלת תיסוב על צירה, פי' על ב' הצירים ציר העליון והתחתון סובבת הדלת, וכן העצל על מטתו, פי' להתקדש בשכבו ובקומו&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יב</b>,<b> ד (שלהי סי</b>'<b> קלו)</b>\n<i>איסור </i>. .<i> שאלת שלום כו'</i> – ברכות יד, א. <i>נעשה בריה חדשה</i> – בר\"ר עח, א. זו\"ח בראשית יח, סע\"ב. זח\"ב ריג, סע\"ב. <i>חדשים לבקרים</i> – איכה ג, כג. <i>כמ\"ש בזוהר</i> – זח\"ג פג, א. <i>ובכתבי האריז\"ל</i> – שער המצות, יתרו. <i>הדלת תיסוב גו'</i> – משלי כו, יד.\n----- הערות וציונים -----\n<i>שהעולם נברא ע\"י מדו\"מ</i> – ראה בר\"ר יב, יד. זח\"ב כ, א. אבות רפ\"ה וזח\"א קנו, א.\n<i>וראשית הכל הוא המחשבה</i> – ראה זח\"א קנה, א בס\"ת.\n<i>ודיבור הוא ענף המחשבה כו'</i> – ראה מדל\"י סי' עח (פט) ואו\"ת סי' רנג.\n<i>כמ\"ש בזוהר ובכתבי האריז\"ל</i> – ראה צוה\"ר סי' צ.\n<i>ויזכך מחשבתו הראשונה כו'</i> – להעיר מזח\"ג ה, סע\"ב ואילך.\n<i>וכן יקדש א\"ע ודבורו כו'</i> – להעיר מע\"ז כ, סע\"א וע\"ב. זח\"ג פג, ב. צוה\"ר סי' צ.\n<i>וז\"ש הדלת תיסוב כו'</i> – להעיר מר\"ח שער הקדושה פ\"ו."]]],[300010255,"ריג-א\n\n<b>שמעתי</b> <i>ממורי</i> &lt;הבעש\"ט&gt; זלה\"ה פי' המשנה כל תורה שאין עמה מלאכה <span data-k=\"sm\">[וכו']</span>, וביאר דיש ג' מיני דיבור שהם ג' מיני זווג, א' זווג המלך ומטרוניתא, ב' זווג בן המלך וזוגתו, ג' זווג דעבד ושפחה וכו'. והנה הדיבור בתורה ותפלה <span data-k=\"sm\">[שהוא]</span> הזווג קוב\"ה <span data-k=\"sm\">[ושכינתיה . . .]</span> &lt;ע\"ש <i>[ftnref_1_לו]</i>&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ וארא כד</b>,<b> רע</b>\"<b>ג (צז</b>,<b> ב)</b>\n<i>כל תורה כו'</i> – אבות פ\"ב מ\"ב.\n----- שולי הגליון -----\n[ftn_1_לו]) <i>ראה לקמן סי' שסב.</i>\n----- הערות וציונים -----\nהמאמר במילואו לקמן סי' שסב. ורג\"כ סי' שעח ובהערות שם.\n<i>ג' מיני דיבור שהם ג' מיני זווג כו'</i> – מבואר בכתונת פסים, פ' בהעלתך לו, ב: דשמעתי ממורי דבכל דבור יש יחוד קבה\"ו ויש ג' סוגי הדבור הנקרא ג' מיני זווג, א' זווג המלך עם מטרוניתא שלו שהיא ידוע ונראה לעצמו, ב' זווג בן וזוגתו שאין הזווג נראה לעיני המלך רק קירוב ספור דברים הגורמין זווג ויודע ומתענג מזה, ג' זווג עבד ושפחה שגם קרוב דברים אינו לפני המלך רק זירוז עבודתן נגלה למלך וכו', והנה הדבור ב' מו\"מ הוא זווג עבד לשפחה והדבור בין אדם לחבירו קירוב דברים הוא זווג בן וזוגתו והדבור בתורה ותפלה כשהוא מתבודד בינו לקונו מעוטף בטלית ותפלין הוא זווג מלכו של עולם ומטרוני' יחוד קבה\"ו ודפח\"ח."]]],[300010256,"ריג-ב\n\n<b>צחות</b> לשון הש\"ס לעולם יעסוק אדם בתורה שלא לשמה, לשון צווי, כדי שאם יעסוק אח\"כ לשמה אז מתו\"ך שלא לשמה בא לשמה, כאשר שמעתי בשם <i>מורי</i> שיעלה הפנימיות &lt;של&gt; שלא לשמה וכו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בא לא</b>,<b> סע</b>\"<b>ב (קכ</b>,<b> א)</b>\n<i>לעולם יעסוק אדם כו'</i> – פסחים נ, א.\n----- הערות וציונים -----\nדברי הבעש\"ט הביא עוה\"פ לקמן סי' שסד, ועומק הענין מבואר באורך בס' תוי\"י פ' שלח קלב, ב (תקב, ב) עיי\"ש."]]],[300010257,"ריד\n\n<b>&lt;חשב</b> ה' להשחית חומת בת ציון נטה קו. ענין כשהצדיק מתפלל וצועק על הזיקו שבעוה\"ז ואינו נענה ואין משגיחין עליו&gt; <span data-k=\"sm\">[ענין שאין לצדיק בעוה\"ז קורת רוח, גם כשהוא מתפלל לפעמים על עניני עוה\"ז אינו נענה ואין משגיחין בתפלתו, אבל]</span> האמת הוא כי הכל הוא מגודל החיבה והאהבה שיש לו ית' אל הצדיק, ובשביל כך אינו נענה בעניני עוה\"ז.\n<b>&lt;מלה\"ד</b><i>[ftnref_1_לז]</i> לבן המלך שהוא קטן ועשה לעצמו בית קטן מקיסמין, ובא אדם וסתר אותו, ובא התינוק אצל אביו בקובלי רבה ובוכה ע\"ז, ואביו הי' מצחק ולא ענהו להנקם תיכף מזה האדם שסתר בנין גרוע זה, כי במחשבת המלך לבנות לו פלטרין גדולים. וז\"ש רומה ה' בעוזך, לבנות בית המקדש העתיד, ואז נשיר ונזמרה גבורתיך. והנמשל מובן, שמחמת אהבת ה' להצדיק ויודע שינחלו עוה\"ב, לכן אינו משגיח על הצער שיש להצדיק בעוה\"ז, שהרי על ידי זה הצער לפום צערא אגרא, שינחילהו לעוה\"ב&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טו</b>,<b> סע</b>\"<b>ג (סי</b>'<b> קסד)</b>\n<i>חשב ה' גו'</i> – איכה ב, ח. <i>לעוה\"ב כו' אשר עין גו' </i>– ע\"פ ברכות לד, ב. <i>אשר עין לא ראתה</i> – ישעי' סד, ג. <i>רומה ה' גו'</i> – תהלים כא, יד. <i>לפום צערא אגרא</i> – אבות פ\"ה מכ\"א.\n----- שולי הגליון -----\n[ftn_1_לז]) <i>מכאן עד סוף הסימן קצר ושנה</i>,<i> ובמקורו</i>:\nמשל לזה, בן קטן היה אצל המלך, והבן ההוא עשה לעצמו בית קטן מקסמין כדרך שהתינוקות המשחקין עושין, ובא אדם א' וסתר אותו הבית שעשה לו הבן מלך, ובא התינוק אצל אביו המלך בקובלנא רבא וצועק ובוכה לפני אביו על גודל הצער שעשה לו האדם הזה. והנה אביו בשמעו היה מצחק, הגם שהוא אוהב אותו ביותר, כי בעיניו לא נחשב לכלום אותו הבית נגד הטובות המוכן ומזומן לקבל מאביו המלך, וגם במחשבתו של המלך לבנות לבנו פלטרין וטרקלין גדולים מפוארים, אבל הבנין השפל והגרוע הזה אינו נחשב לאביו כלל שינקום בשביל זה מאותו אדם שסתר זה. ואף שיש לבנו צער גדול על זה, עם כל זה אינו משגיח עליו, כי לפי דעתו של התינוק הוא צער לו, אבל אביו שיודע שלגדולה מזה הוא מתוקן לכל הטובות אשר עתיד הוא לקבל ממנו.\nוהנמשל מובן, שמחמת גודל אהבה וחיבה שיש להקב\"ה על הצדיקים, שבשביל אהבתו ינחילם לעוה\"ב כל הטוב הצפון אשר עין לא ראתה, לכן אינו משגיח הקב\"ה על הצער שיש להצדיק בעוה\"ז, כי הוא ית' יודע שכל טוב עולם הבא הוא כפול ומכופל, שכל טוב עוה\"ז הוא כאין נגד האהבה החזקה שבשבילה ינחילם טוב הגנוז לעוה\"ב.\n----- הערות וציונים -----\n<i>כשהצדיק מתפלל כו'</i> – להעיר מזח\"ב טו, א. ורג\"כ זח\"א קסז, ב ושם קסט, רע\"א ובהג' החיד\"א שם.\n<i>ינחילנה לעוה\"ב</i> – להעיר מזח\"ב רכד, רע\"א וראה באוה\"ח שם."]]],[300010258,"רטו\n\n<b>ריב\"ש</b> ע\"ה אמר, כשאדם טובע בנהר והוא מראה &lt;במים&gt; כמה תנועות שיוציא עצמו מן המים השוטפים אותו, בודאי הרואים אותו לא יתלוצצו עליו ועל תנועתו, כן כשמתפלל ועושה תנועות אין להתלוצץ עליו, שהוא מציל עצמו ממים הזדונים שהם הקליפות &lt;ומ\"ז&gt; הבאים לבטלו ממחשבתו בתפלתו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> א (סי</b>'<b> קסז)</b>\n----- הערות וציונים -----\nראה צוה\"ר סי' סח. להעיר מזח\"ג ריח, סע\"ב ואילך. פי' קול יהודה לכוזרי מ\"ב רס\"י פ. שבלי הלקט סי' יז. רמ\"א בטושו\"ע או\"ח סי' מח."]]],[300010259,"רטז-א\n\n<b>צריך</b> שירגיש במחשבתו שהוא בעולם העשיה בתחלת התפלה, ואח\"כ ירגיש שהוא ביצירה <span data-k=\"sm\">[עד סוף המדריגות]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> א (סי</b>'<b> קסט)</b>\n----- הערות וציונים -----\nראה פע\"ח שער התפלה פ\"א ופ\"ד. שער הכונות, דרושי תפלת השחר דרוש א-ב. וראה לקמן סי' רטז-ב, רנט ורפא-א."]]],[300010260,"רטז-ב\n\n[<b>כשמדבק</b> <span data-k=\"sm\">עצמו ילך בתחילה בעולם עשיה, ואח\"כ יפרח במחשבתו למעלה גבוה יותר, ואח\"כ עוד גבוה יותר ב]</span>עולם המלאכים והאופנים, ואח\"כ בעולם הבריאה, עד שירגיש במחשבתו שפרח במחשבותיו גבוה מאד לעולם האצילות <span data-k=\"sm\">[וזהו נקרא בזוהר מחשבה שאין בה מעשה]</span> &lt;וכמו אדם שמטייל מחדר לחדר, כן יטייל במחשבתו בעולמות עליונים&gt;.\n<b>ויזהר</b> שלא יפול ממחשבתו הגבוה מאד בעולמות העליונים <span data-k=\"sm\">[לירד למטה]</span>, רק יחזיק את עצמו בכל כחו שישאר למעלה במחשבותיו, וכמ\"ש אל תהיו כסוס כפרד אין הבין במתג ורסן כו', שיעשה כמו גדר שלא ירד, <span data-k=\"sm\">[ואז כשהוא דבוק כ\"כ, כשנופל במחשבתו איזה דבר בודאי יתחזק כיון שהוא דבוק בו ית' וממנו באים כל הדברים. וצריך שיתחזק במחשבתו שיעלה מחשבתו למעלה בעולמות העליונים בו ית' כמו אדם שמטייל מחדר לחדר כן יטייל במחשבתו בעולמות העליונים]</span>.\n<b>&lt;וכשרוצה</b> לעשות כן לצורך דביקות בלא שעת תפלה&gt;, צריך שלא יהיה שום אדם באותו בית <span data-k=\"sm\">[כשרוצה לדבק]</span>, שאפילו צפצופי עופות יכולים לבטלו, וכן מחשבה של אחר יכול לבטלו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ב (סי</b>'<b> קעה)</b>\n<i>אל תהיו כסוס גו'</i> – תהלים לב, ט.\n----- הערות וציונים -----\nראה לעיל סי' רטז-א ולקמן סי' רפא-א.\n<i>אל תהיו כסוס כו'</i> – ראה לעיל סס\"י קמו.\n<i>לצורך דביקות בלא שעת התפלה</i> – אולי הוסיף מלים אלו דלא רמי הא דכתב להלן שלא יהיה שום אדם באותו בית כו' (וכדאיתא שיזכה לדביקות מחמת התבודדות – צוה\"ר סי' פג וראה שם בהערות) מהא דכתב בצוה\"ר סי' סג דכשרוצה להיות בהתבודדות צריך להיות עמו עוד חבר אחד, אבל אדם אחד לבד הוא בסכנה כו' עיי\"ש (וכבר הערותי שם מר\"ח שער הקדושה פ\"ו שכתב טובה התבודדות ע\"י קניית חבר כו')."]]],[300010261,"ריז-א\n\n<b>ירגיש</b> בשבת תוספות נפש, ואח\"כ תוספות רוח, ואח\"כ תוספות הנשמה, שירגיש בכל פעם שהולך גבוה יותר בעולמות עליונים.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> א (סי</b>'<b> קע)</b>\n<i>ירגיש בשבת תוספות כו'</i> – פע\"ח שער השבת פ\"א ופ\"ו. ע\"ח ש\"נ פ\"ו.\n----- הערות וציונים -----\nראה לקמן סי' תב."]]],[300010262,"ריז-ב\n\n<b>&lt;אפילו</b> כשהולך לעסקיו יקיים שויתי ה' לנגדי תמיד ובכל דרכיך דעהו.\n<b>ויהיה</b> דבוק בבורא יתברך במחשבה קטנה&gt; <span data-k=\"sm\">[אפילו כשנופל ממדריגתו יהיה דבוק בבורא ית' במחשבה קטנה],</span> לפעמים יש גם כן קטנות למעלה בזעיר אנפין, ומכח אותו הקטנות יבוא לגדלות, כמו בגחלים אם יהיה ניצוץ א' שנשאר יכול לנפח בהם הרבה עד שיהיה מדורה גדולה &lt;כבתחלה&gt;, לאפוקי אם לא יהיה ניצוץ קטן לא יכול לנפח אש, כך אם לא יהיה דבוק במחשבה קטנה תמיד בו ית' יכבה נשמתו לגמרי.\n<b>&lt;וז\"ש</b> הרמ\"ק ז\"ל לומר אש תמיד תוקד על המזבח לא תכבה, פי' הדביקות הנמשל לאש, רשפי אש כו', תמיד תוקד על המזבח, בהצדיק הזובח יצרו בקרבו, לא תכבה, דא\"כ יצטרך להביא אש מחדש&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> א (סי</b>'<b> קעא)</b>\n<i>שויתי ה' גו'</i> – תהלים טז, ח. <i>ובכל דרכיך דעהו</i> – משלי ג, ו. <i>וז\"ש הרמ\"ק ז\"ל כו'</i> – של\"ה שער האותיות ערך ל. <i>אש תמיד גו'</i> – צו ו, ו. <i>רשפי אש</i> – שה\"ש ח, ו.\n----- הערות וציונים -----\n<i>אפילו כשהולך לעסקיו כו'</i> – ראה לעיל סי' קב, לקמן סי' רכ-א, רפב-א-רפב-ב, וצוה\"ר סי' צח וצט. להעיר מרמב\"ם הלכות דעות פ\"ג וטושו\"ע או\"ח סי' רלא.\n<i>אפילו כשנופל כו'</i> – ראה צוה\"ר סי' סז וסט.\n<i>לפעמים יש ג\"כ קטנות בז\"א</i> – ראה ע\"ח שי\"א פ\"ח.\n<i>כמו בגחלים כו' </i>(עד סוף הפיסקא) – ראה לעיל סי' פד ד\"ה והנה אליהו ז\"ל."]]],[300010263,"ריז-ג\n\n<b>לפעמים</b> כשמתפשט הניצוץ הקדוש של השכינה שיש בנשמתו, ואז היא ממש מדברת הדברים שבפיו, ונראה כאילו הוא אינו מדבר, שהדברים יוצאים מאליהם מפיו, וזהו מדריגה גדולה. וכן אנו רואים להיפך <span data-k=\"sm\">[בס\"א]</span> במשוגעים.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> סע</b>\"<b>א (סי</b>'<b> קעב)</b>\n----- הערות וציונים -----\nלהעיר מלעיל סי' קצט-ב, וראה לקמן סי' רכ-ד."]]],[300010264,"ריח\n\n<b>התורה</b> חסה על ממונם של ישראל, ולמה כך, כי זה כלל גדול שכל דבר שאדם לובש או אוכל או משתמש בכלי, הוא נהנה &lt;מהחיות&gt; <span data-k=\"sm\">[מהרוחניות]</span> שיש באותו הדבר, כי לולא אותו הרוחניות לא היה שום קיום לאותו דבר, ויש שם ניצוצין קדושים השייכים לשורש נשמתו<i>[ftnref_1_לח]</i>, וכשהוא משתמש באותו הכלי או אוכל מאכל אפילו לצורך גופו, הוא מתקן הניצוצין, כי אח\"כ עובד &lt;ה'&gt; בכח ההוא שבא לגופו מלבוש או מאכל או שאר דברים, ובזה הכח עובד להשי\"ת, נמצא מתקנם <span data-k=\"sm\">[מתוקנים]</span>.\n<b>לכך</b> פעמים שיאבד ממנו הדבר ההוא, שכשכלה כבר לתקן כל הניצוצין שהיו באותו הדבר השייכים לשורש נשמתו, אז לוקח ממנו השי\"ת אותו הכלי ונותן לאחר, ששייכים הניצוצות הנשארים באותו הכלי לשורש של אחר שהוא משורש נשמתו.\n<b>ואמר</b> <i>ריב\"ש</i> ע\"ה, שאוכלים בני אדם ויושבים על בני אדם ומשתמשים בבני אדם, היינו בניצוצין שיש באותן הדברים.\n<b>לכך</b> צריך האדם לחוס על כליו ועל כל דבר שיש לו, דהיינו מצד הניצוצין שיש בכלי זה, בכדי לחוס על הניצוצין הקדושים.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ב (סי</b>'<b> קעז) [צוה</b>\"<b>ר סי</b>'<b> קט]</b>\n<i>התורה חסה כו'</i> – יומא לט, א.\n----- שולי הגליון -----\n[ftn_1_לח]) <i>בצוה\"ר מוסיף כאן</i>: ושמעתי כי זהו הטעם שיש אדם שהוא אוהב דבר זה ויש אדם ששונא דבר זה ואוהב דבר אחר.\n----- הערות וציונים -----\nראה לעיל סי' נג וקצד ובמ\"מ והערות שם.\n<i>לולא אותו הרוחניות כו'</i> – ראה פרדס רמונים ש\"ד ספ\"י, ושם ש\"ו פ\"ח. תניא, שהיוה\"א פ\"א ושם אגה\"ק סי' כה.\n<i>ויש שם ניצוצין כו'</i> – ראה ע\"ח שכ\"ו פ\"א ושם ש\"נ פ\"ג. ולעיל סי' קצד ד\"ה וז\"ש ריב\"ש. ורכ\"ג לעיל סס\"י כז."]]],[300010265,"ריט\n\n<b>אמרו</b> על <i>ריב\"ש</i> ע\"ה שזכה לכל הארות והמדריגות שהי' לו הכל מחמת המקוואות, שהיה תמיד בטבילות. ומקוואות יותר בתמידות טוב יותר מהתענית, שהתענית מחליש הגוף מעבודת השם, ועוד יותר טוב שהכח שהוא מניח בתענית יתן הכח ההוא בלימוד התורה ותפלה שיתפלל בכל כחו וכוונתו, ובזה יבוא למדריגה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ב (סי</b>'<b> קעח)</b>\n----- הערות וציונים -----\nהובא בקיצור בלקו\"י-יד\"א ר\"פ מב, לפני כונת המקוה דלעיל סי' ב.\n<i>שהיה תמיד בטבילות</i> – ראה לעיל בריש הספר (צוואה מהבעש\"ט זלה\"ה) מלקו\"י סי' קצח אות ג, וצוה\"ר סי' טו. רג\"כ לקמן בהוספות סי' קצט ובהערות שם. ולהעיר מר\"ח שער האהבה פי\"א.\n<i>שהתענית מחליש הגוף מעבודת ה'</i> – להעיר מתענית יא, א. רמב\"ם, הלכות דעות רפ\"ג ורפ\"ד, ושמנה פרקים פ\"ד. ר\"ח שער הענוה פ\"ג (ועד\"ז לקמן סי' רכו). וראה צוה\"ר סי' נו שטוב יותר לעבוד השי\"ת בשמחה בלי סגופים כי הם גורמים עצבות. ולקמן סי' שב-ב, ובהוספות סי' כא. וראה עוד בס' בוצינא דנהורא, ששאלו להבעש\"ט מהו עיקרי העבודה כו' ואתם בטלתם את הדבר הזה (התענית) כו' והשיב להם הבעש\"ט דעתי בזה שיראה אדם להמשיך ע\"ע ג' דברים הללו היינו אהבת השי\"ת ואהבת ישראל ואהבת התורה ואין צריך לעשות סיגופים."]]],[300010266,"רכ-א\n\n<b>שויתי</b> ה' לנגדי תמיד, שויתי לשון השתוות, בכל דבר שיארע לו יהא הכל שוה אצלו, בין בענין שמשבחין אותו בני אדם או מבזין אותו, וכן בכל שארי דברים, וכן בכל האכילות, בין שאוכל מעדנים בין שאוכל שאר דברים, הכל שוה בעיניו, שהוסר בזה היצה\"ר ממנו מכל וכל.\n<b>וכל</b> דבר המאורע יאמר הלא זה נשלח מאתו ית', ואם בעיניו הגון כו', וכל כוונתו יהא לש\"ש, אבל מצד עצמו אין חילוק. וזהו מדריגה גדולה מאד.\n<b>וכן</b> האדם צריך לעבוד הש\"י בכל כחו, שהכל הוא צורך גבוה, שהשי\"ת רוצה שיעבדו אותו בכל האופנים, הכוונה, כי לפעמים אדם הולך ומדבר עם בני אדם, ואז אינו יכול ללמוד, וצריך להיות דבוק בהשי\"ת במחשבתו וליחד יחודים.\n<b>וכן</b> כשאדם הולך בדרך ואינו יכול להתפלל וללמוד כדרכו, וצריך לעובדו באופנים אחרים, אל יצער את עצמו בזה, כי השי\"ת צריך שיעבדוהו בכל האופנים, פעמים באופן זה ופעמים באופן זה, לכך הזדמן לפניו לילך לדרך או לדבר עם בני אדם בכדי לעבוד אותו באופן הב'.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> סע</b>\"<b>ב (סי</b>'<b> קעט</b>-<b>קפ) [צוה</b>\"<b>ר סי</b>'<b> ב</b>-<b>ג]</b>\n<i>שויתי ה' גו'</i> – תהלים טז, ח.\n----- הערות וציונים -----\n<i>לשון השתוות כו' בין בענין שמשבחין אותו כו'</i> – ראה חובה\"ל שער יחוד המעשה פ\"ה (אמר על א' מן החסידים כו' הנשתוית . . נשתוה בעיניך השבח והגנות כו' המדרגה הזאת . . העליונה שבמדריגות החסידים ותכלית החמודות). והובא בשל\"ה, פ' עקב קונטרס הענוה שעא, א (פ, א) יעו\"ש. שערי קדושה להרח\"ו ח\"ג ש\"ד. צוה\"ר סי' יו\"ד. וראה לעיל סי' רא-א.\n<i>וכל דבר המאורע כו' מאתו ית'</i> – ראה לקמן סי' רכז-ב. צוה\"ר סי' פד. וראה תניא, אגה\"ק רס\"י כה.\n<i>וזה מדרגה גדולה מאד</i> – ראה בדברי החובה\"ל הנ\"ל. וראה ס' אור האמת ק, ב – וכן בלקו\"א המיוחס להרמ\"מ כט, א – הבעש\"ט אמר שאם לא יהיה לאדם שום פניה שיהיה הכל שוה אצלו בודאי יזכה לכל המדריגות שענוה גדולה מכולם כו' עיי\"ש.\n<i>שהכל צורך גבוה כו'</i> – להעיר מתוספתא ברכות רפ\"ד עה\"פ כל פעל ה' למענהו. רמב\"ם, הלכות דעות פ\"ג ושמנה פרקים פ\"ה. וראה לעיל סי' ריז-ב ובהערות שם.\n<i>הולך ומדבר עם בני אדם כו'</i> – ראה לעיל סי' צג-ג ובהערות שם.\n<i>ואל יצער א\"ע בזה כו'</i> – ראה צוה\"ר סי' קי.\n<i>לכך הזדמן לפניו לילך לדרך</i> – להעיר מפירוש הבעש\"ט עה\"פ מה' מצעדי גבר כוננו בס' מאור עינים פ' ויקהל בד\"ה קחו (מב, סע\"ב). ובאור המאיר פ' צו ד\"ה בפסוק ולבש (צב, ד). וכן בדמ\"א פ' מסעי רד\"ה עי\"ל ויכתוב. וראה לקמן בהוספות סי' קפד.\n<i>או לדבר עם בני אדם</i> – ראה לעיל סי' צג-ג, ולקמן סס\"י שב-א ושסו."]]],[300010267,"רכ-ב\n\n<b>כלל</b> גדול, גול אל ה' מעשיך<i>[ftnref_1_לט]</i> ויכונו מחשבותיך, שכל דבר שיזדמן לו יחשוב שהוא מאתו ית'.\n<b>וגם</b> שיבקש מהשי\"ת שיזדמן לו תמיד מה שהשי\"ת יודע שהוא לטובתו, ולא מה שנראה לאדם טובה ע\"פ שכלו, כי אפשר מה שבעיניו הוא טוב, הוא רעה לו, רק ישליך הכל, כל עניניו וצרכיו, עליו ית', כמ\"ש השלך על ה' יהבך.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ג (סי</b>'<b> קפא) [צוה</b>\"<b>ר סי</b>'<b> ד]</b>\n<i>גול אל ה' גו'</i> – משלי טז, ג. <i>השלך גו'</i> – תהלים נה, כג.\n----- שולי הגליון -----\n[ftn_1_לט]) <i>בכל דפוסי הכש\"ט שראיתי כתוב </i>\"<i>גול על ה' דרכיך</i>\"<i> ע\"פ תהלים לז</i>,<i> ה עם הסיפא ויכונו מחשבותיך ע\"פ משלי טז</i>,<i> ג</i>.<i> ונראה שזהו פליטת הקולמוס וצ\"ל הפסוק דמשלי</i>,<i> שכן הוא בצוה\"ר ובלקו\"י</i>.\n----- הערות וציונים -----\n<i>שבכל דבר שיזדמן לו כו'</i> – ראה לעיל סי' רכ-א ושם בהערות ד\"ה וכל דבר.\n<i>מה שהשי\"ת יודע שהוא לטובתו כו'</i> – להעיר ממטבעת תפילות חז\"ל הטוב בעיניך עשה (ברכות כט, ב). וראה נדה לא, א עה\"פ אודך ה'. ספר העיקרים מ\"ד פי\"ג ופכ\"ד. וראה חובה\"ל שער הבטחון פ\"ד. ועיין בהערות לצוה\"ר סי' ד."]]],[300010268,"רכ-ג\n\n<b>פעמים</b> האדם כשיכור מחמת שמחת התורה שבוער בלבו אהבה גדולה, <span data-k=\"sm\">[ויגע בעצמו]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ג (סי</b>'<b> קפב)</b>\n----- הערות וציונים -----\nלהעיר מזו\"ח בראשית ה, ד."]]],[300010269,"רכ-ד\n\n<b>פעמים</b> יכול לומר התפלה במהירות מאוד, מחמת שבוער בלבו אהבת השם מאד והתיבות יוצאים מפיו בעצמם.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ג (סי</b>'<b> קפג) [צוה</b>\"<b>ר סי</b>'<b> לו]</b>\n----- הערות וציונים -----\n<i>יכול לומר התפלה במהירות כו'</i> – ראה צוה\"ר סי' לב.\n<i>והתיבות יוצאים מפיו מעצמם</i> – ראה לעיל סי' ריז-ג."]]],[300010270,"רכא\n\n<b>האדם</b> צריך ללמוד גאוה ולא יתגאה, כעס ולא יכעוס, וכן כל המדות, כי האדם צריך להיות שלם בכל המדות <span data-k=\"sm\">[שיש להבורא ית']</span>, &lt;כי גם אצלו&gt; <span data-k=\"sm\">[ובהבורא]</span> יתברך יש דין ורחמים.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ג (סי</b>'<b> קפד)</b>\n----- הערות וציונים -----\n<i>ללמוד גאוה ולא יתגאה</i> – ראה לעיל סי' סח, ולקמן סי' שצג. צוה\"ר סי' צא. וראה חובה\"ל שער הכניעה פ\"ו ד\"ה והששי וד\"ה והשביעי, ושם פ\"ט.\n<i>כעס ולא יכעוס</i> – ראה רמב\"ם, הלכות דעות פ\"ב ה\"ג. שו\"ע הרב או\"ח סי' קנו ס\"ג. תניא, אגה\"ק סי' כה קרוב לסופו (נחזור לענין ראשון בענין הכעס) ע\"פ זו\"ח נח (מדה\"נ) כא, סע\"א. ולהעיר מסוף הקדמות הרח\"ו לס' ע\"ח, ערך בקש שלום וערך סור מרע אות ג, והאריך בזה בריש שער רוה\"ק ד\"ה גם מדת הכעס (לג, ב ואילך), וכתב שם שהאריז\"ל היה מקפיד בענין הכעס יותר מכל שאר העבירות אפילו כשהוא כועס בשביל מצוה כו' עיי\"ש. ולהעיר שע\"פ המבואר בסימן זה יש לתווך דברי הרמב\"ם הנ\"ל עם מש\"כ שם בהלכות דעות פ\"א ה\"ד.\nוראה בלקו\"א המיוחס להרמ\"מ כט, ב (ובשנויים קלים באור האמת ק, סע\"ב): בגמרא (מגילה כח, א) מימי לא הקפדתי בתוך ביתי, שפעמים שצריך להראות כעס למירמא אימתא אאינשי ביתא, אבל בתוך ביתי שהוא בפנימיות גופי ונשמתי לא הקפדתי ולא בי בעצמי כעס, ולפעמים צריך להראות (גסות) [גבהות] כו' (כבצוה\"ר סי' צא הנ\"ל)."]]],[300010271,"רכב\n\n<b>בשם</b> <i>ריב\"ש</i>, כאשר בא לאדם מ\"ז בתפלה או בלימוד, ישבור המ\"ז <span data-k=\"sm\">[ההיא]</span> וידבק עצמו בבורא ית', ובזה מתקן ניצוץ קדוש שיש במחשבה ההיא. והוא משל, האדם שהיה מונה מעות, והיה בנו בשביה, ובא אצל אביו וא\"ל הרי יש לך מעות פדני מהשביה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ג (סי</b>'<b> קפה)</b>\n----- הערות וציונים -----\nראה לעיל סי' לט ובהערות שם.\n<i>פדני מהשביה</i> – ראה לעיל סס\"י נג וסס\"י קס, ולקמן סס\"י רפז."]]],[300010272,"רכג\n\n<b>כשמתענה</b> אדם אפילו משבת לשבת, ויהיה לו פניה אפילו קטנה, שיאמר בלבו שהוא עושה דבר גדול שעינה את עצמו כ\"כ הרבה, ויזדכך מאד בזה, זה התענית בא לסט\"א. רק יחשוב בלבו, מה מעשי נחשבים נגד עבודת המלאכים שעבודתם בתמידות להש\"י, ואני טפה סרוחה וסופי לעפר.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ג (סי</b>'<b> קפח) [צוה</b>\"<b>ר סי</b>'<b> עז]</b>\n----- הערות וציונים -----\nראה צוה\"ר סי' מג-ב. מדל\"י סי' קצו (רו). ולהעיר מלקמן סי' רעח."]]],[300010273,"רכד\n\n<b>יהיה</b> זהיר מאד לקום תמיד בחצות הלילה, ואם אינו קם שלא מחמת אונס הוא בנידוי למעלה.\n<b>ויהפוך</b> הלילות לימים, ויישן ביום כמה שעות כדי שיספיק לו מעט שינה בלילה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ג (סי</b>'<b> קפט) [צוה</b>\"<b>ר סי</b>'<b> כו</b>-<b>כז]</b>\n----- הערות וציונים -----\n<i>יהיה זהיר מאד לקום כו'</i> – עיין טושו\"ע או\"ח סי' א ובנו\"כ שם. ובסידור אדה\"ז, בסוף סדר תקון חצות, מפתח קצר לקצת מאמרי הזוהר בענין זה. ועיין ר\"ח שער הקדושה פ\"ז. וראה צוה\"ר ריש סי' טז ושם סי' פג.\n<i>אם אינו קם כו'</i> – ראה זח\"ג כג, ב. וכן זח\"א ריז, א (הובא בר\"ח שם).\n<i>ויהפוך הלילות לימים כו'</i> – ראה רמב\"ם הלכות ת\"ת פ\"ג ה\"ה. טושו\"ע או\"ח סי' רלח ויו\"ד סס\"י רמו. הלכות ת\"ת לאדה\"ז פ\"ד ה\"ח והמקורות אשר הובאו שם. וכן בדוכתי טובא בזוה\"ק.\n<i>ויישן ביום כו'</i> – ראה עירובין סה, א יזיף ביממא כו' ופי' ר\"ח שם. ועיין היטב מה שהאריך בזה בלקוטי שיחות חי\"ב ע' 254 הערה 50 – הובא בצוה\"ר בביאורים לסי' כו-כז."]]],[300010274,"רכה\n\n<b>סיג</b> לחכמה שתיקה, שכשהוא בשתיקה יכול הוא לדבק עצמו בעולם המחשבה שהוא חכמה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ג (סי</b>'<b> קצ)</b>\n<i>סיג כו'</i> – אבות פ\"ג מי\"ג. <i>המחשבה שהוא חכמה</i> – זח\"ב כ, א. תקו\"ז יז, א.\n----- הערות וציונים -----\nראה צוה\"ר סי' קלג. וראה תו\"א לאדה\"ז פ' לך יב, ד החכמה בחי' ביטול וזהו השתיקה. להעיר מאו\"ת להרה\"מ סי' תעח. ועיין בהמשך תרס\"ו לאדמו\"ר מוהרש\"ב סי' מה (ד\"ה ביום השמע\"צ)."]]],[300010275,"רכו\n\n<b>ארז\"ל</b> אור אלו מעשיהם <span data-k=\"sm\">[של צדיקים]</span> כו', פי' כי אדם החכם יכול לאכול דברים טובים ושארי תענוגים, ומ\"מ יכול הוא לסגף עצמו בהם, וכן לראות בכל מקום שירצה ולא להסתכל חוץ לד' אמות, לראות תמיד בשם בן ד' שיש באותו דבר, בסוד שויתי ה' וגו', בסוד אל תסתכל בקנקן אלא במה שיש בו, דעיקר כל דבר שבעולם הוא הרוחניות שבו הבא מהשי\"ת שנותן בו טעם ומקיימו. <span data-k=\"sm\">[וכן בדיבור כנ\"ל, יכול לדבר אפילו דברים בטילים באיזה פעם, ולהיות דבוק בהשי\"ת]</span>.\n<b>וכן</b> בתפלה, יכול לעבוד עבודת התפלה להשי\"ת שלא יהיה עבודתו נראה בפני בני אדם כלל, שלא יעשה שום תנועה באיברים, רק בפנימיות בנשמתו יהיה בוער בלבו ויצעוק בלחש, מחמת התלהבות, בענין שתהא עבודתו בפנים יותר גדולה משתהא עבודתו נראית באיברים, &lt;כמ\"ש צעק לבם כו'&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> סע</b>\"<b>ג (סי</b>'<b> קצב)</b>\n<i>אור אלו כו'</i> – בר\"ר ב, ה. <i>שויתי ה' גו'</i> – תהלים טז, ח. <i>אל תסתכל כו'</i> – אבות פ\"ד מ\"כ. <i>צעק לבם גו'</i> – איכה ב, יח.\n----- הערות וציונים -----\n<i>ולא להסתכל חוץ לד' אמות לראות </i>. .<i> בשם בן ד'</i> – ראה ר\"ח שער הקדושה פ\"ח: טעם שלא להסתכל חוץ לד\"א כי צריך להשוות מדתו למדת רבו, כי כמו שבעיניו ית' כתיב עיני ה\"א בה (עקב יא, יב) ומדתה הם ד' אמות כמנין ד' אותיות אדנ\"י, כן צריך לנהוג בעצמו, בהיות האדם נוהג במדה זו הוא מייחד שם יאהדונה\"י, כי בעין יש בו שם הוי' כמבואר לעיל, ובהיותו מסתכל בארץ שהוא אדנ\"י נמצא מייחד כו' עיי\"ש.\n<i>דעיקר כל דבר כו'</i> – ראה לעיל סי' ריח ובהערות שם. צוה\"ר סי' צ. ולהעיר מלקמן סי' רעט.\n<i>וכן בדיבור כו'</i> – ראה לעיל סי' קג, ולקמן סי' רלו (בשוה\"ג), שא-ב<i>-ד</i> ושסו.\n<i>אפילו דברים בטלים</i> – עיין לקמן סי' רלו אך סכנה יש כו'. ועיי\"ע מדל\"י סי' צח (קז).\n<i>וכן בתפלה כו'</i> – ראה לקמן סי' רלג.\n<i>ויצעק בלחש כו'</i> – ראה לעיל סי' קסו."]]],[300010276,"רכז\n\n<b>יחשוב</b> שבתפלתו הולך מהיכל להיכל, וכשנופלת לו מחשבה זרה מגרשין אותו מן ההיכל, כי דנין אותו בכל היכל אם ראוי ליכנוס<i>[ftnref_1_מ]</i>. ויראה וישגיח על המ\"ז ההיא<i>[ftnref_2_מא]</i>, אם &lt;ח\"ו חשב&gt; באהבה רעה כגון ניאוף <span data-k=\"sm\">[יביא אותה אל שורשה שהיא אהבת השם]</span><i>[ftnref_3_מב]</i>, יתחרט תיכף ויאמר בלבו מה עשיתי שלקחתי חלק מעולם המחשבה והולכתי אל מקום הטנופת, ובזה יכנע וישוח עד לעפר, ויביא זאת המחשבה למדת אין, ואח\"כ תבוא אל עולם אחר <span data-k=\"sm\">[נ\"א: עולם האהבה]</span> בזכרו אם אני אוהב את הדבר הרע הזה, כמו אשה שהיא טפה סרוחה, כמה יש לאהב את הש\"י. וכן אם שומע א' מדבר בדברי שחוק, ועי\"ז נולד לו איזה שמחה, יאמר בלבו הלא זה החלק מעולם האהבה. וכן אם רואה או אוכל דבר שיש לו תענוג ממנו, יחשוב בלבו הלא זה חלק מעולם התענוג ויראה מאד שלא יגשם התענוג ההוא <span data-k=\"sm\">[כי אז מקרי אז תתענג על ה', כביכול למעלה מהשם]</span>, אלא <span data-k=\"sm\">[ישים כל עצמותו אל התענוג ההוא לאמר הלא הוא חלק מעולם התענוג ו]</span>יבוא גם הוא אל עולם התענוג, נמצא הוא יושב כאן ואוכל, <span data-k=\"sm\">[והוא]</span> בעולם התענוג של הש\"י. וכן בהתפארות, אם מפארים אותו, ואם בא לו באמצע התפלה התפארות כמה אני מתפלל בכוונה, יחזיק א\"ע בהתפארות של עולם התפארת כנ\"ל. ואם בא לו איזה יראה רעה, &lt;כגון שמתירא ליתן צדקה שלא יעני&gt; יחזיק א\"ע ביראה הקדושה שהוא בושה מהש\"י. ואם בניצוח, ינצח את המדה הזאת &lt;ויחזק א\"ע במדת נצח העליון&gt; <span data-k=\"sm\">[או כמו שמבין יחזיק בעצמו ניצוח ה']</span>. וכן בהודיה. וכן בהתקשרות, שלא יהיה מקושר רק בהש\"י עצמו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י טז</b>,<b> ד (סי</b>'<b> קצד) [צוה</b>\"<b>ר סי</b>'<b> פז]</b>\n<i>מגרשין כו' כי דנין כו'</i> – זח\"ב רמה, ב. <i>במדרש הנעלם</i> – זח\"א פו, ב. <i>אברהם מדת אהבה</i> – ישעי' מא, ה. ס' הבהיר סי' קלה. זח\"ג שב, א. <i>ישמעאל אהבה רעה</i> – ר' זח\"ג ר\"מ קכד, א. שם רמו, ב. <i>יצחק מדת גבורה יראה</i> – זח\"ג שב, א. <i>עשו יראה רעה</i> – ר' זח\"ג ר\"מ קכד, א. שם רמו, ב. <i>אז תתענג גו'</i> – ישעי' נח, יד. <i>למעלה מה'</i> – זח\"ב פג, רע\"א.\n----- שולי הגליון -----\n[ftn_1_מ]) <i>בצוה\"ר מוסיף כאן</i>: ואם אינו מתפלל בהתלהבות יתחיל להתפלל בכח, ואם מתפלל בהתלהבות אזי יראה על מ\"ז <i>(וכו' כבפנים)</i>.\n[ftn_2_מא]) <i>בצוה\"ר מוסיף כאן</i>: מה הוא.\n[ftn_3_מב]) <i>בלקו\"י ובצוה\"ר יש המשך</i>: שיש ז' מיני מחשבות ולא יותר, וזהו ז' ימי הבנין, ובכל אחת יש בה ערב ובוקר, ערב לשון תערובות, שחושב מחשבות חיצוניות, ובוקר לשון ביקור, שמבקר את השם יתברך ודורשו, ואלו הם: אהבת השם, ואהבת העבירות, ויראת השם, ויראה רעה כגון שנאה, ותפארת השם שמפאר את השם יתברך, ורעה שמפאר את עצמו, וכן ניצוח, והודיה, ויסודות לשון התקשרות, וכל אחת כלול מעשר, ובכל מחשבה רעה מחיה הז' עממין.\nוזהו שאמרו במדרש [הנעלם] העולם הזה היה מתמוטט, אמר הקב\"ה הא אברהם זמין למיפק לעלמא, פירוש מדת אברהם מדת אהבה, הא ישמעאל זמין למיפק מיניה, פירוש אהבה רעה, נמצא כשמחשב באהבה רעה מחיה את ישמעאל ותשעה עממין שעמו, הא יצחק פירוש מדת גבורה [יראה], הא עשו, פירוש יראה רעה רציחה, נמצא כשמחשב ביראה רעה מחיה את עשו ותשעה שעמו.\nאמנם אם ח\"ו חשב באהבה רעה, יתחרט <i>(כבפנים)</i>.\n----- הערות וציונים -----\n<i>יחשוב כו' כי דנין כו'</i> – ראה לקמן סי' רפז ושפז. צוה\"ר סי' פט. וראה מדל\"י סס\"י פד (צה) בשם הבעש\"ט. ורג\"כ שם סי' ג (ד). ועיין שערי אורה להרי\"ג שלהי שער ב (ל, ב).\n<i>אם ח\"ו באהבה רעה כו'</i> – ראה לעיל סי' לט ובהערות שם.\n<i>שיש ז' מיני מחשבות כו'</i> – ראה לקמן סי' תו. ובאור המאיר, שה\"ש ד\"ה אקומה בשם הרה\"מ: כל פרטי מחשבות אדם אפילו המה אלפי אלפים עכ\"ז אינם בדרך כלל כ\"א שבעה מחשבות הנמשכים מז' ימי הבנין וכו'.\n<i>ואלו הם אהבת השם כו'</i> – לא מנה אלא ששה, ולא מנה בחי' מלכות. להעיר מקהלת יעקב, ערך גרגשי: וקבלתי ממורי החסיד מהר\"י סגל דגרגשי הוא בחי' מלכות דקליפה, וע\"כ ארז\"ל גרגשי פנה מאליו (ירושלמי, שביעית פ\"ו ה\"א), והענין כי כאשר מתקנים הו' מדות אז מדת מלכות ממילא מתוקנת כי היא כללות ו' הקודמין ולית לה מגרמה כלום כו' עיי\"ש. ובפרטיות בס' אגרא דכלה להרה\"ק מדינוב, פ' לך לך ד\"ה ויעבר אברם (ג\"כ בשם החוזה מלובלין): הכנענ\"י נגד חסד שבקליפה מורה לשון הכנעה [בספרי החוזה איתא כנעני לשון סוחר ותגר (פסחים נ, א) שנותן הקדושה בעד תאוה רעה לפי שעה]; החת\"י כנגד הגבורה שבקליפה מלשון חת\"ת אלהים (וישלח לה, ה); האמור\"י נגד תפארת שבקליפה כי האמורי לשון התפארות כמה דאת אמר את ה' האמרת וה' האמירך (תבוא כו, יז-יח); הפריז\"י נגד נצח שבקליפה כדרך המנצח היושב בערי הפריזי בלי פחד (ראה רש\"י ליחזקאל לח, יא); החו\"י נגד הו\"ד שבקליפה מלשון חוויא (ראה ירושלמי קידושין פ\"ד ה\"א) כי גם בקדושה עיקר החורבן והצרות הם באלף החמישי והודי נהפך עלי למשחית (דניאל י, ח) כל היום דוה (איכה א, יג); היבוס\"י נגד יסוד שבקליפה מלשון הכתוב תבו\"ס נופת (משלי כז, ז) והבן, (ול\"נ מלשון דריכה לשון יבו\"ס צרינו (תהלים ס, יד) והדריכה יכונה לזיווג מלשון גבר בעלמה (משלי ל, יט)); גרגש\"י כנגד מלכות שבקליפה כמ\"ש רז\"ל ואתה מושל בכל (דה\"א כט, יב) אפילו גרגותנא מן שמיא מוקמי ליה (ברכות נח, א) וגרגשי מלשון גרגותני (חגיגה כב, א) (ול\"נ שהוא מלשון רגוש עפר, כי הוא בסוד עפר המקבל מג' יסודות אמ\"ר, והבן) ע\"כ הגרגשי עמד ופנה מעצמו (ירושלמי שביעית פ\"ו ה\"א), כי מלכות\"ך מלכות כל עולמים (תהלים קמה, יג) ואפילו המלכות שבקליפה יתנו הדר למלך הכבוד, והבן כי הדברים עתיקים, ע\"כ דברי פה קדוש הנ\"ל ודפח\"ח.\n<i>וכל א' כלול מעשר</i> – ראה לקמן סס\"י שסו וש\"נ.\n<i>ובכל מחשבה רעה מחיה ח\"ו הז' עממין</i> – ראה מדל\"י סי' קמז (קנה). ועיין צוה\"ר סי' יד ובהערות שם.\n<i>במדרש הנעלם</i> – מבואר בלקו\"י לו, ד (סי' רפ).\n<i>ויביא זאת המחשבה למדת אי\"ן</i> – ראה לקמן סי' רכח. וראה מדל\"י סי' קמז (קנה), וכן שם סי' צח (קז) ורלב (רמו).\n<i>אז תתענג על ה' כ\"י כו'</i> – ראה מדל\"י סוף סי' קנט (קסז) ושם סי' קסח (קעה). להעיר מזח\"ב פג, רע\"א."]]],[300010277,"רכח\n\n<b>צריך</b> אדם לידע כלל גדול, כאשר בא לו מ\"ז מן ז' ימי הבנין, ר\"ל או התפארות רעה או אהבה רעה או יראה &lt;כנ\"ל&gt; <span data-k=\"sm\">[רעה]</span>, וכן מכל ז' ימי הבנין, צריך לקשר אותה כ\"א בשרשה. כיצד יעשה, ימאס הדבר ההוא, ואז הרע נופל למטה והטוב יקח ממנו, ר\"ל שיבוא עליו צירוף אחר. למשל כשבא לאדם במחשבתו אותיות של ניאוף, ישבר המחשבה הזאת ויבוא עליו צירוף אחר. וזהו פירוש כשבא אל הבינה נמתקין הדינין, וד\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יז</b>,<b> ד (סי</b>'<b> ריב)</b>\n<i>כשבא אל הבינה כו'</i> – זח\"א קנא, א ובמ\"מ שם.\n----- הערות וציונים -----\nראה לעיל סי' רכז ובהערות שם."]]],[300010278,"רכט\n\n<b>התפלה</b> כשהיא בשמחה גדולה בוודאי יותר חשוב ומקובל לפניו יותר מהתפלה בעצבות ובכיה. ומשל על זה, כשעני שואל ומבקש ומתחנן לפני המלך בשר ודם בבכיה גדולה, אעפ\"כ אין נותן לו אלא דבר מועט, אבל כשהשר מסדר לפני המלך <span data-k=\"sm\">[שבח המלך ב]</span>שמחה גדולה ומתוך השבח מבקש גם בקשתו, אז נותן לו המלך מתנה מרובה כמו שנותנין לשררות.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יז</b>,<b> ד (סי</b>'<b> רו) [צוה</b>\"<b>ר סי</b>'<b> קז]</b>\n----- הערות וציונים -----\nעיין מש\"כ בביאור סימן זה בס' דברי תורה לבעל מנח\"א מהד\"ט אות כט.\n<i>התפלה שהיא בשמחה כו'</i> – ראה ברכות לא, א. זח\"א רכט, ב. זח\"ב קסה, א. ספר חסידים ריש סי' יח. ועיין פע\"ח, שער עולם העשיה ספ\"א. ספר חרדים, מצות התשובה פ\"ד.\n<i>ומשל על זה כו'</i> – להעיר מזח\"ב קפד, ב ובהג' הרח\"ו שם. ושם ריח, סע\"ב ובהג' דרך אמת שם."]]],[300010279,"רל\n\n<b>והבוטח</b> בה' חסד יסובבנו, וכשהוא להיפך, שהוא מתירא תמיד ממדת ד' ומהעונש, אז הוא מתדבק עצמו בדינים, וח\"ו שלא יבוא לו רעה, כמ\"ש ומגורתם אביא להם. שבכל מקום שאדם &lt;הוא&gt; חושב <span data-k=\"sm\">[שם]</span> הוא מתדבק, ואם מחשב בדין הוא מתדבק בדין, וכשהוא בוטח בחסד, שם ידבק נשמתו והחסד יסובבנהו, ותמיד יטמין א\"ע כולו בשם יתעלה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יז</b>,<b> ד (סי</b>'<b> רז)</b>\n<i>והבוטח בה' גו'</i> – תהלים לב, י. <i>ומגורתם גו'</i> – ישעי' סו, ד.\n----- הערות וציונים -----\nלעיקר תוכן מאמר זה ראה של\"ה, שער הגדול כט, ב (כב, א): ובמדרש א\"ל הקב\"ה למשה . . כשם שאתה הווה עמי כך אני הווה עמך, וכן אמר דוד ה' צלך על יד ימינך . . מה צלך אם אתה מראה לו כו' עיי\"ש היטב. וכן ביאר פסוק זה הבעש\"ט כדלקמן בהוספות סי' עח וש\"נ. וראה לעיל סוף סי' קמה. לקמן סי' רעג-ב ובהערות שם. צוה\"ר סי' קמב. והוספות למדל\"י-או\"ת סי' יט. ועיין מדל\"י סי' מט (נו), ע\"פ הגירסא באוה\"א מז, א: כשהוא מדבר בנסים ובטוב הוא מעורר למעלה טוב, וכשהוא מדבר להיפך הוא מעורר ח\"ו להיפך.\n<i>וכשהוא להיפוך שהוא מתירא כו'</i> – ראה מדל\"י סי' מה (מח). ובס' דרכי צדק אות נד בשם הרה\"מ.\n<i>שבכל מקום שאדם הוא חושב כו'</i> – ראה לעיל סי' נו ובהערות שם.\n<i>וכשהוא בוטח בחסד כו'</i> – ראה מדרש תהלים סי' לב אות ג: אפילו רשע בוטח בה' חסד יסובבנהו. וראה דרשות הר\"ן, בסוף הדרוש הששי בשם הר\"ר יונה ז\"ל. רג\"כ מש\"כ בהערות לסי' שפב."]]],[300010280,"רלא\n\n<b>מריב\"ש</b> ע\"ה, כאשר גופו חולה גם נשמתו נחלשת ואינו יכול להתפלל כראוי אע\"פ שהוא נקי מעבירות. לכך צריך האדם לשמור בריאות גופו מאד.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יז</b>,<b> ד (סי</b>'<b> רח) [צוה</b>\"<b>ר סי</b>'<b> קו]</b>\n----- הערות וציונים -----\n<i>כאשר גופו חולה גם נשמתו נחלשת</i> – ראה בהוספות למדל\"י-או\"ת סי' קצא, דברי הרה\"מ שחור קטן בגוף גורם לחור גדול בנשמה.\n<i>ואינו יכול להתפלל כראוי כו'</i> – ראה רמב\"ם הלכות דעות פ\"ג ה\"ג ושם רפ\"ד, והלכות תשובה פ\"ט סה\"א. מו\"נ ח\"ג פכ\"ז. ספר החינוך, מצוה עד. באר הגולה לשו\"ע חו\"מ סוף סי' תכז אות צ. טור ושו\"ע הרב או\"ח סי' קנה. וראה פירוש הבונה לע\"י ברכות מ, א ושבת פב, רע\"א."]]],[300010281,"רלב\n\n<b>וזהו</b> מדריגה גדולה לאדם שיראה תמיד בעין שכלו השי\"ת כמו שמסתכל על אדם א', ויחשוב שגם הבורא ית' מסתכל עליו כמו אדם אחר שמסתכל עליו, כ\"ז יהיה תמיד במחשבתו ובמחשבה זכה וברורה וצלולה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יז</b>,<b> ד (סי</b>'<b> רט) [צוה</b>\"<b>ר סי</b>'<b> קלד]</b>\n----- הערות וציונים -----\nראה לעיל סי' קסט (ובהערות שם). ורג\"כ לעיל סי' ר-א וצוה\"ר סי' קלז."]]],[300010282,"רלג-א\n\n<b>פעמים</b> יש לעבוד השי\"ת בנשמה לבד, דהיינו במחשבתו, <span data-k=\"sm\">[והגוף יהיה עומד במקומו כדי שלא יחלה כשישתמש בו הרבה]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יז</b>,<b> ד (סי</b>'<b> רי) [צוה</b>\"<b>ר סי</b>'<b> קד]</b>\n----- הערות וציונים -----\nראה לקמן סי' רלג-ב ובהערות שם."]]],[300010283,"רלג-ב\n\n<b>ולפעמים</b> יכול אדם לומר התפלה באהבה ויראה והתלהבות גדול בלי שום תנועה, ויהיה נראה לאדם אחר שהוא אומר אותן הדברים בפשוט בלי שום דביקות. וזה יכול אדם לעשות כשהוא דבוק מאד להשי\"ת, אז יכול לעבוד אותו בנשמה לבד באהבה רבה וגדולה. וזה העבודה היא יותר טובה והולכת במהירות יותר ומדבקת יותר להשי\"ת מהתפלה שנראה בחוץ על האיברים, ואין הקליפה אחוזה בזו התפלה שכולו הוא בפנימיות.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יז</b>,<b> ד (סי</b>'<b> ריא) [צוה</b>\"<b>ר סי</b>'<b> קה]</b>\n----- הערות וציונים -----\nראה לעיל סי' רכו. צוה\"ר סי' נח, נט וסח. רג\"כ לעיל סי' קסו."]]],[300010284,"רלד\n\n<b>גבורי</b> כח עושי דברו. פי' שצריך האדם להיות במדרגה זו שהדיבור יהיה לו עשיה, ר\"ל כשהוא בא אל הדיבור צריך לו לילך דרך ז' מדרגות, כי תחלה צ\"ל בבינה, לחשוב איך לדבר, ואח\"כ צ\"ל דרך אהבה ויראה, ואח\"כ דרך התפארת, כשהוא רוצה שתהיה תיבה שלימה אז נצטרפו האותיות ואז מתפארים בעיניו לדברם כך, ואח\"כ צ\"ל דרך הניצוח, שמנצח האותיות האחרים הרוצים לצאת בנענוע ה' מוצאות מנצח אותם ומדבר הדבר הצריך לו, ואח\"כ צ\"ל דרך הוד, ואח\"כ &lt;הרוצה לצאת&gt; דרך יסוד, דהיינו כשמחשבתו דבוק לדיבורו הוא נקרא יסוד, שהוא דביקות המחשבה בדיבור, ואח\"כ בא דרך הפה, והוא מלכות, והוא מדריגה התחתונה, וצריך האדם להיות במדריגה זו שיהיה דיבורו נחשב לו למעשה וד\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יח</b>,<b> סע</b>\"<b>א (סי</b>'<b> רטו)</b>\n<i>גבורי כח גו'</i> – תהלים קג, כ. <i>הפה והוא מלכות</i> – תקו\"ז יז, א.\n----- הערות וציונים -----\n<i>שהדיבור יהי' לו עשי'</i> – ראה לקמן סי' שיג.\n<i>דרך ז' מדרגות</i> – ראה לעיל סי' רכז ובהערות שם."]]],[300010285,"רלה\n\n<b>המהלך</b> בדרך יחידי &lt;ושונה ומפסיק ממשנתו כו', קשה דהל\"ל ומפסיק ממשנתו והוה ידעינן דהיה שונה, עוד קשה מעלה עליו הכתוב ולא מפרש איזה כתוב.\n<b>וי\"ל&gt;</b> הפי', &lt;כי ה&gt;הולך בדרך הישר, ואפילו הכי הוא יחידי שאינו דבוק בהשי\"ת, ושונה ומפסיק ממשנתו, ר\"ל מפסיק א\"ע מהש\"י מחמת משנתו, דהיינו שבאה לו גדלות והתפארות מחמת משנתו &lt;שסובר שהוא משנתו שלו&gt;, ואומר מה נאה אילן זה, ועל עצמו אומר כן בלבו, כמ\"ש כי האדם עץ השדה, &lt;ואומר דהוא אלנא די רבא ותקיף&gt;, ומה נאה ניר זה, כמ\"ש נירו לכם ניר, &lt;פי' שאומר שמכין לעצמו חלק לעוה\"ב ע\"י משנתו&gt;, מעלה עליו הכתוב &lt;פי' כתוב שנ' תמים תהיה עם ה' אלקיך, פי' אפי' כשתעסוק בתורה שנאמר בה תורת ה' תמימה, וז\"ש תמים תהיה, אפילו בעסק התורה תהיה עם ה' אלקיך, ולא תימא הלא התורה ממילא נקרא תורת ה', וז\"ש מעלה עליו הכתוב הזה, שכולל כל התורה&gt;, כאלו מתחייב בנפשו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יח</b>,<b> ב (סי</b>'<b> רטז)</b>\n<i>המהלך בדרך כו'</i> – אבות פ\"ג מ\"ד. <i>ושונה ומפסיק כו'</i> – שם מ\"ז. <i>כי האדם גו'</i> – שפטים כ, יט. <i>אלנא די רבא ותקיף</i> – ע\"פ דניאל ד, ח. <i>נירו לכם גו'</i> – ירמי' ד, ג. <i>תמים תהיה גו'</i> – שפטים יח, יג. <i>תורת ה' תמימה</i> – תהלים יט, ח.\n----- הערות וציונים -----\nראה לקמן סי' רעח.\n<i>שאינו דבוק בהשי\"ת כו'</i> – בענין דבקות בהשי\"ת בלימוד התורה ראה צוה\"ר סי' כט, ל, נד וקלט.\n<i>אלנא רבא ותקיף</i> – בטוי מצוי בכ\"מ בזוה\"ק, וראה שם זח\"ג נג, ב."]]],[300010286,"רלו\n\n<i>[ftnref_1_מג]</i> <b>הורני</b> ה' דרכך, &lt;פי' אפי' הדרך הכבושה בקשתי הורני&gt;, <span data-k=\"sm\">[ר\"ל הוריני שאדע הדרך הכבושה]</span> ואז &lt;אלך&gt; <span data-k=\"sm\">[אהיה יכול לילך]</span> בה מעצמי, ונחני באורח מישור, באורח שאוכל לטעות בה, בקשתי שתנחני בסיוע <span data-k=\"sm\">[וסעד]</span> ועזר שאלך במישור ולא בעקלתון, כי זולת העזר <span data-k=\"sm\">[שלך]</span> אוכל ח\"ו לטעות.\n<b>&lt;וז\"ש</b> בכל דרכיך, פי' דרכים הכבושים, דעהו מעצמך, והוא יתברך יישר אורחותיך, אפילו הדרכים שאינם כבושים&gt;<i>[ftnref_2_מד]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>קטע מלקו</b>\"<b>י יח</b>,<b> ב (סי</b>'<b> ריז) [צוה</b>\"<b>ר סי</b>'<b> קמ]</b>\n<i>הורני ה' גו'</i> – תהלים כז, יא. <i>דרך נקרא כו' ואורח כו'</i> – ראה זח\"ב רטו, רע\"א. זח\"ג פח, רע\"א. <i>בכל דרכיך דעהו וגו'</i> – משלי ג, ו.\n----- שולי הגליון -----\n[ftn_1_מג]) <i>תחילת המאמר במקורו</i>:\nהורני ה' דרכך כו'. הנה ידוע כי דרך נקרא דרך כבושה, ואורח נקרא שאינו כבושה ויכולים לפעמים לטעות לילך מתוכה למקום סכנה, מה שאין כן בדרך כבושה שאין יכולים לטעות מתוכה.\nכן באדם יש ב' ענינים אלו. יש לאדם דרך כבושה בעבודת הבורא ית' שילך תמיד בזה הדרך בודאי לא יטעה מתוכה, דהיינו אדם שפירש א\"ע מכל הענינים ואינו עוסק רק בתורה ובמצות יומם ולילה, ואינו מדבר רק דברים ההכרחיים ולא יותר. ויש ג\"כ דרך אחר שאינה כבושה, ונקרא אורח, דהיינו אדם שמדבר לפעמים עם בני אדם, אך הדיבורים הם לש\"ש, דהיינו שמדבר אלה הדברים שיבוא מהם איזה מוסר או אהבת השם או יראת השם וכיוצא, או אדם שיודע להעלות דיבורים למעלה בקדושה, כידוע מכמה ב\"א, נמצא שבוודאי מותר לדבר בדברים האלו, אך סכנה יש באלו הדברים כי אולי יתעה מדרך הטוב ויתחיל לדבר דברים בטלים ג\"כ כדרך המון עם. ועל זה צריך האדם להתפלל ולבקש מאתו ית' שיסייע אותו כשירצה לילך בזה האורח, כי בלתי סיוע מאתו ית' בקל יכול אדם לתעות באותו הדרך הנ\"ל. לכן צריך האדם לחגור מתניו בתפלה שלא יבוא לידי מכשול עבירה ח\"ו.\nוזהו פירוש הפסוק הורני ה' <i>(כבפנים)</i>.\n[ftn_2_מד]) <i>סיום המאמר במקורו</i>:\nוזה רמז ג\"כ בכל דרכיך דעהו והוא יישר ארחתיך, פירוש בכל הדרכים הכבושים צריך האדם בעצמו לידע הטוב איך ילך ויתנהג בהם, וזהו יכול האדם בעצמו לידע ולהתנהג. והוא, פירוש והוא ית', יישר ארחתיך, אפילו אותן הדרכים שאינן כבושים יישר לפניך ויהיה לך לסיוע ולעזר שלא תתעה.\n----- הערות וציונים -----\n<i>דרך כו' אורח כו'</i> – ראה מדל\"י סי' קצד (רד) ואו\"ת סי' רי.\n<i>להעלות דיבורים למעלה בקדושה</i> – ראה לעיל סי' רכו ובהערות שם ד\"ה וכן בדיבור.\n<i>אך סכנה יש באלו הדברים</i> – עיין מש\"כ בהערות לסי' לט.\n<i>בלי סיוע מאתו ית' כו'</i> – להעיר מסוכה נב, ב (אלמלא הקב\"ה עוזרו כו').\n<i>וזה רמז הפסוק בכל כו'</i> – להעיר שבלקו\"ת להאריז\"ל, ריש ס' משלי, פירש עד\"ז.\n<i>צריך האדם בעצמו לידע</i> – ראה צוה\"ר סוף סי' קלח."]]],[300010287,"רלז\n\n[<b>שמעתי</b> <span data-k=\"sm\">משל נפלא על]</span> עונש הצדיקים בעוה\"ז והם כאלו הקב\"ה מתרחק מהם ח\"ו &lt;כדי שיתקרבו יותר, מלה\"ד לבן קטן שאביו מלמדו לילך כו'&gt;. <span data-k=\"sm\">[דרך משל אדם שיש לו בן קטן ורוצה להרגיל אותו לילך, מעמידו על הארץ, ומתרחק ממנו מעט, וקוראהו שילך הקטן אצלו מעט, וכאשר בא התינוק אל אביו אז מתרחק אביו עוד ממנו, והולך התינוק עוד אצלו, ועושה האב כזה כמה וכמה פעמים עד שמרגילו לבא להליכה גמורה.</span>\n<b>ונבין</b> <span data-k=\"sm\">מזה המשל כי כל מה שמתרחק האב מן התינוק תמיד, הוא כדי שילך התינוק עוד להלן, מה שאין כן אם לא היה האב מתרחק מהתינוק כשבא אצלו בפעם ראשונה, היה התינוק עומד ונשאר במקום ההוא הראשון ולא היה הולך להלן עוד.</span>\n<b>והנמשל</b> <span data-k=\"sm\">מובן מאליו, שהקב\"ה רצונו תמיד שהצדיק יעלה תמיד ממדריגה למדריגה על ידי מעשיו, לכן הקב\"ה מתרחק תמיד ממנו ומענישו תמיד, ועל ידי זה מפשפש במעשיו, ומתחזק בעבודת בוראו, ועולה תמיד במדריגה יותר עליונה]</span>.\n<b>וריב\"ש</b> נתן סימן על זה והוא ינהגנו עלמות.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י יט</b>,<b> סע</b>\"<b>ב (סי</b>'<b> רמ)</b>\n<i>והוא ינהגנו עלמות</i> – תהלים מח, טו.\n----- הערות וציונים -----\n<i>עונש הצדיקים בעוה\"ז כו'</i> – להעיר מלעיל סי' ריד.\n<i>וריב\"ש נתן סימן על זה כו'</i> – ראה צוה\"ר סי' סד.\n<i>עלמות</i> – פירש כמלה אחת לשון עלם ועלמה (ראה רש\"י, אב\"ע ורד\"ק עה\"פ). המשל על זה הובא בקדושת לוי, פ' שמות בד\"ה וזה לך האות, בשם הבעש\"ט. ובצ\"פ פ' בשלח נא, ריש ע\"ב (קפו, א) בשם דשמעתי. לעיקר ענין המשל להעיר מלעיל סי' נא-ב וסו, וראה שם בהערות."]]],[300010288,"רלח-א\n\n<b>&lt;האדם</b> אע\"פ שיש בו גדלות וגאוה, ונדמה לו&gt; <span data-k=\"sm\">[האדם בגבהותו ומדמה לו]</span> שהוא למדן גדול ויחסן <span data-k=\"sm\">[ועשיר]</span> ובעל מדות &lt;טובות&gt; <span data-k=\"sm\">[ישרות]</span> וצדיק וירא ונעים ונחמד, ו<span data-k=\"sm\">[באמת]</span> לפי מעלתו היה ראוי &lt;שלא להתחבר ולפנות לשום אדם, רק שלא יחזיקוהו לבעל גאוה וסובר שמצוה להיות עניו, ע\"כ עושה א\"ע עניו&gt; <span data-k=\"sm\">[להיות גדול מכל עמו ולא לפנות אליהם ולא להתחבר אליהם, רק שזו מדה גרועה שמצד זה ימאס בעיני העולם שיחזיקוהו לבעל גאוה, ובאמת מצוה הוא ג\"כ להיות עניו ושפל ברך ולדבר עם כל ולהיות עלוב מכל, ע\"כ הוא עושה עצמו עניו]</span>. . .\n<b>&lt;ומלה\"ד</b> ליושב על עגלה&gt; <span data-k=\"sm\">[והשי\"ת הזמין לי משל אמת על זה, אדם נוסע בדרך בעגלה]</span> וישן ונוסע עמו בעל העגלה על הר <span data-k=\"sm\">[אחד]</span> גבוה, ואח\"כ כשהוא בא על ההר <span data-k=\"sm\">[ואז]</span> הדרך ישר, <span data-k=\"sm\">[כי כבר עבר הזקיפה והשיפוע]</span>, ואח\"כ אם נתעורר האדם הישן ואומרים לו שהוא על ההר אינו מאמין, מפני שאינו רואה שום סימן, <span data-k=\"sm\">[כי אילו ראה בראשונה השפוע שנסע ועלה עליו ידע, אבל כעת הוא שוה אליו מהיכי תיתי לו לומר שהוא בהר]</span>. אך יתודע לו כשירד מן ההר בשפוע הב' <span data-k=\"sm\">[היורדת מן ההר לבקעה יבחין שהיה מתחילה בהר]</span>.\n<b>&lt;וכן</b> האדם נולד על זה ההר שהוא הגבהות כו'<i>[ftnref_1_מה]</i>, ולא יבחין זה אלא כשירגיל א\"ע בתכלית הכניעה ע\"י שיכיר גדולת יוצר בראשית ושפלותו&gt; <span data-k=\"sm\">[ובאמת הגבהות נדמה לו להר גבוה, ואילו היה האדם מרגיש באמת שלבו מתגדל בקרבו בודאי היה מבחין זה שיש לו גבהות והוא עלה [להר], אבל האדם נולד על זה ההר שהוא הגבהות כמו שאמרו חז\"ל האדם מתגאה על כולם, ולפיכך דומה לו שאין לו גבהות ואינו בהר כלל, והאיך יבחין זה אם לא שירד מן ההר לגמרי לרגלי ההר על הבקעה ממש, דהיינו שירגיל א\"ע בכניעה ושפלות בלב ובמעשה, והעיקר בלב, ויתודע לו האמת]</span>. . .",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כ</b>,<b> ד (יד</b>\"<b>א ספ</b>\"<b>א ופ</b>\"<b>ב)</b>\n<i>האדם מתגאה על כולם</i> – תנחומא הקדום בשלח יד. ילק\"ש תהלים רמז תת\"ס.\n----- שולי הגליון -----\n[ftn_1_מה]) <i>משפט זה הוא ע\"פ מה שהובא במקורו לפני המשל</i>: באמת האדם מוטבע על זה ונולד בזה שיגבה לבו, כמ\"ש חז\"ל ד' מיני גאים בעולם ואדם מתגאה על כולם, וזה מצד קליפת נפש הרע שנתערבה בו.\n----- הערות וציונים -----\nבנ\"ד בגנות הגאוה וענוה פסולה ראה לעיל סי' לא ולקמן סי' שטו ושצג, וצוה\"ר סי' צב.\n<i>וכן האדם נולד על זה ההר כו'</i> – נראה שהוספה זו מיוסדת על מש\"כ שם ביד\"א לפני המשל: באמת האדם מוטבע על זה ונולד בזה שיגבה לבו כמ\"ש חז\"ל ארבעה מיני גאים בעולם ואדם מתגאה על כולם, וזה מצד קליפת נפש הרע שנתערבה בו."]]],[300010289,"רלח-ב\n\n<b>כי</b> א\"א למי שהוא דבוק בהש\"י באהבה ויראה שיבא לידי חטא <span data-k=\"sm\">[קל]</span>, ק\"ו <span data-k=\"sm\">[לחמור]</span>, ק\"ו שיהיה דבוק באיזה תאוה &lt;או גאוה&gt; ח\"ו, כי הלא הש\"י קדוש ומובדל מכל החומריות. &lt;וענין אהבת הש\"י ויראתו צ\"ל בלב האדם&gt; <span data-k=\"sm\">[אלא ודאי אינו צריך לפנים שענין אהבת הש\"י ויראתו הוא ענין אחר, שהוא בלב האדם]</span>, שיהיה &lt;לבו מלא&gt; <span data-k=\"sm\">[בלבו]</span> פחד ויראה מהש\"י תמיד, ויהיה בוער אהבתו בלבו תמיד, כמ\"ש הרמב\"ם סוף ס' המדע <span data-k=\"sm\">[בהלכות תשובה, וז\"ל]</span> כיצד הוא אהבה הראויה כו' ע\"ש. וזה &lt;א\"א לקנות&gt; <span data-k=\"sm\">[אין האדם קונה ומחובר בה]</span> כ\"א ע\"י התורה לשמה, <span data-k=\"sm\">[ועיקר מקודם ה]</span>תפלה בדביקות ובהתלהבות הלב, ובכפיות כל &lt;הכוחות&gt; <span data-k=\"sm\">[כוחותינו]</span> למחשבות זכות וטהורות להש\"י תמיד, ובפרישות כל התענוגים, ואצ\"ל פרישות עבירות קלות וחמורות, <span data-k=\"sm\">[וכל דקדוקים, ובנקיון כל האיברים, ושמירתם בהקדושה השייכה להם, כמ\"ש ספרי מוסר, וביותר בעל ראשית חכמה]</span>, אבל &lt;בנ\"א&gt; <span data-k=\"sm\">[כמו שהם נוהגים ו]</span>המזלזלים בתפלה האיך יהיה להם דבקות בהש\"י, ע\"י התורה. באמת אינם לומדים רק מצות אנשים מלומדה למען יחכמו, ועז\"א הכתוב הוי חכמים בעיניהם וגו', וזה קורא הזוהר חסד דעבדין לגרמייהו <span data-k=\"sm\">[כידוע]</span>. ועיקר התורה לשמה היא לבוא להתדבק במי שנעלם בה, להיות מרכבה אליו. וזה שארז\"ל דבר גדול ודבר קטן, דבר גדול מעשה מרכבה דבר קטן הויות דאביי ורבא, &lt;עמש\"ל&gt;<i>[ftnref_1_מו]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כב</b>,<b> שלהי ע</b>\"<b>ג (יד</b>\"<b>א פ</b>\"<b>ח)</b>\n<i>בהלכות תשובה</i> – פ\"י ה\"ג. <i>בעל ראשית חכמה</i> – ראה שם שער היראה פ\"ט ושער הקדושה ספ\"ז. <i>מצות אנשים </i>– ע\"פ ישעי' כט, יג. <i>הוי חכמים גו'</i> – ישעי' ה, כא. <i>הזוהר</i> – תקו\"ז ת\"ו כב, א. שם ת\"ל עג, ב. <i>דבר גדול ודבר קטן</i> – סוכה כח, א.\n----- שולי הגליון -----\n[ftn_1_מו]) עמש\"ל – <i>לעיל סי' קעד</i>,<i> שהוא המשך להמובא כאן בסי' רלח</i><i>ב</i>.\n----- הערות וציונים -----\n<i>ועיקר מקודם כל התפלה כו'</i> – ראה ר\"ח שער האהבה פ\"ט בביאור זח\"ב קלד, ב.\n<i>למחשבות זרות כו' ובפרישות כו'</i> – ראה ר\"ח שער האהבה שם, ופי\"א עה\"פ תהלים נא, יב."]]],[300010290,"רלט-א\n\n<b>&lt;במיעוט</b> תענוג, פי'&gt; <span data-k=\"sm\">[להדבק בהשי\"ת ע\"י התורה והמצוות צריך תנאים רבים . . . הקטן שבכולם להיות מופשט מתאוות הזמן . . .]</span> מחמת גודל התלהבות <span data-k=\"sm\">[לבו]</span> לתורה ולעבודת הש\"י למען שמו באהבה, לא יחשוב אליו התענוג &lt;של&gt; העוה\"ז <span data-k=\"sm\">[של אותו דבר]</span> כמו אם האדם שמח במשא ומתן שהרויח אינו מרגיש כלל בתענוג קטן של אכילה. וזהו במיעוט תענוג, ואינו אומר במעט תענוג, רק במיעוט, כי למעט אין צריך לומר, כי אפילו ההכרח ממעט, דהיינו שירבה תענוג וחשקות דביקות אלהי בלבו ע\"י התורה עד שיכבה כשרגא בטיהרא, ואם יהיה לו מעט תענוג אזי יהיה בזה כמו שארז\"ל הנאה הבאה לאדם בעל כרחו, והעיקר שיהיה לא אפשר ולא מכוין, ואפי' אפשר שרי, רק העיקר לא מכוון, כידוע הדין. וזה הכל בענין המותר לאכול ולשתות ומוכרח בו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כא</b>,<b> סע</b>\"<b>א (יד</b>\"<b>א פ</b>\"<b>ד)</b>\n<i>במיעוט תענוג</i> – אבות פ\"ו מ\"ו. <i>כשרגא בטיהרא</i> – חולין ס, ב. <i>הנאה הבאה לאדם כו'</i> – פסחים כה, ב.\n----- הערות וציונים -----\nראה לעיל סי' רלח-ב ולקמן סי' רלט-ב.\n<i>עד שיכבה כשרגא בטיהרא</i> – ראה לקמן סי' שצא.\n<i>כידוע הדין</i> – ראה רמב\"ם הלכות מאכלות אסורות פי\"ד הי\"ב ובכסף משנה שם."]]],[300010291,"רלט-ב\n\n<b>&lt;וזהו&gt;</b> עיקר התפשטות הגשמיות <span data-k=\"sm\">[יהיה בלבו]</span> שיהיו נמאסים &lt;בלבו ו&gt;בעיניו כל תאוות העוה\"ז, <span data-k=\"sm\">[אפילו ההכרח יהיה בו לא אפשר ולא מכוין, כמו שכתבתי לעיל</span><i>[ftnref_1_מז]</i><span data-k=\"sm\">, וכמו שכתב בס' המגיד מישרים שהזכיר המגיד להבית יוסף ז\"ל על זה תמיד, עיי\"ש]</span>, ומכ\"ש כל המדות רעות <span data-k=\"sm\">[התלויות בלב כנ\"ל]</span> ויהיה מופשט מכולם מחמת גודל תשוקתו לבורא ית\"ש. אשר כל תאוות וחמדת עוה\"ז ורהביו וקנאתו הבל הוא למי שזכה לטעום בנפשו חשוקה זו אפי' באפס קצהו שיהיה באמת, דהיינו שיהיה ביראה ובאהבה, כי בלתי יראה ופחד בלב אין זה רק חיצוניות אהבה <span data-k=\"sm\">[כמבואר בכתבים של הרב מו\"ה דוב בער זלה\"ה . . . וכמבואר בס' חסד לאברהם ג\"כ]</span>, כי כל מה שאדם עובד ה' ועוסק בתורה בלתי יראה, ר\"ל פחד הלב, ר\"ל שתפול עליו פחד בלב מן הש\"י, ובלתי זה הכל הוא מבחוץ, אבל ביראה נאמר זה השער לה', כי מי שבא בשער שהמלך בו נופל עליו יראה בטבע, כן האדם כשנופל עליו פחד הש\"י בלבו סימן &lt;הוא&gt; שנכנס במחשבתו בשער המלך, וזהו מדת מלכות, כי כן מדת המלכות בשר ודם, ק\"ו בן בנו של ק\"ו כו' מלכות הש\"י. וכשמרגיל א\"ע ביראה זו תמיד, אזי ממילא נמאסין בעיניו כל התאוות והמדות רעות מחמת בושה של הש\"י ופחדו ממנו. וזהו התפשטות הגשמיות והתגברות כח השכלי המבואר בשו\"ע אורח חיים סי' צ\"ח. &lt;וז\"ש יעקב מה נורא כו', ש\"מ וזה שער השמים&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כא</b>,<b> סע</b>\"<b>ד (יד</b>\"<b>א פט</b>\"<b>ו)</b>\n<i>בס' המגיד מישרים</i> – ר\"פ בשלח. <i>בס' חסד לאברהם</i> – מעין ד נהר מג. <i>ביראה נאמר כו'</i> – זח\"א ז, ב. <i>זה השער גו'</i> – תהלים קיח, יט. <i>מה נורא </i>. .<i> שער השמים</i> – ויצא כח, יז.\n----- שולי הגליון -----\n[ftn_1_מז]) <i>סימן רלט</i><i>א</i>.\n----- הערות וציונים -----\nראה לעיל סי' רלח-ב ורלט-א.\n<i>כמבואר בכתבים כו'</i> – ראה לקו\"י סי' מב. מדל\"י סי' צב (קא) [נעתק לקמן סי' שצא].\n<i>זה השער לה'</i> – ראה זח\"א יא, ב. וראה צוה\"ר סי' סו.\n<i>מי שבא בשער המלך כו'</i> – ראה לקמן סי' שצא.\n<i>התפשטות הגשמיות כו'</i> – ראה לעיל סי' קצט ובהערות שם."]]],[300010292,"רמ-א\n\n<b>יהיה</b> מופשט מגשמיות ותאוותיהם, כי אם הוא דבוק בגשמיות ובתאוות ומקבל תענוג מהם לרצונו, אזי בודאי אינו יודע כלל מאהבת הבורא ויראתו והתפארותו כו', כי לא טעמו כלל, והכתוב אומר טעמו וראו כי טוב ה', <span data-k=\"sm\">[וח\"ו יפול בשוחה עמוקה אם לא ישמור א\"ע מאד, וצריך להרחיק א\"ע בכל הרחקות הנמצאים בספרי מוסר]</span>.\n<b>&lt;ואם&gt;</b> <span data-k=\"sm\">[רק מי ש]</span>הוא מופשט מגשמיות ואפילו הכי מתעורר בלבו לפעמים אהבה רעה או יראה רעה, כי עדיין לא נברר ונפשט כל צרכו, והפסולת רוצה לאחוז בו ולהדפנו, <span data-k=\"sm\">[אזי הוא עצה שלו שיוציא יקר מזולל וילמוד קו\"ח, ו]</span>יתעורר על ידי זה באהבת הבורא ויראתו <span data-k=\"sm\">[יותר]</span>, &lt;ועי\"ז יברר ניצוצין קדישין מפסולת המאנין תבירין&gt;<i>[ftnref_1_מח]</i>. <span data-k=\"sm\">[ועי\"ז הוא העלאת ניצוצין משברי כלים, כי האהבות הרעות והיראות הרעות והתפארות הרע' שהם נמשכים לחומריות, בלתי להתקשר להשי\"ת, הם פסולת המאנין תבירין שלא נבררו]</span>.\n<b>כי</b> באמת לולי השבירה לא היה שום רע ושום חומריות בעולם, רק כל הברואים היו דביקים בבורא ית\"ש, כמו האופנים והשרפים וחיות הקדש, <span data-k=\"sm\">[ואפילו בהמות, וכמו שיהיה לעתיד בביאת משיח אי\"ה במהרה, שיברר הטוב, והסיג יכלה והרע יכלה, ואז יפצחו הרים רנה, וירננו עצי היער, וגר זאב עם כבש ולא ירעו ולא ישחיתו, (שגם) [לפי] שיתגלה הקדושה של השי\"ת מהקליפות, אפילו דומם וצומח ובעלי חיים לפי ערך נפשם יהיה להם ידיעות ודביקות בבורא ית\"ש, כ\"ש אנחנו, בני ישראל עם קרובו]</span>, אבל השבירה גרמה התרחקות והתעבות <span data-k=\"sm\">[ושכחה]</span> ופירוד מן השי\"ת, והכל למען נסותינו להטיבנו באחריתנו כשנזדכך במעשינו ונברר טוב מרע על ידי &lt;מצות הבורא של מאכלים כשירים וטהורים&gt; <span data-k=\"sm\">[דביקות הבורא]</span>.\n<b>ועיקר</b> הבירור <span data-k=\"sm\">[של השבירה]</span> א\"א להיות אם הוא דבוק ומתאוה ומתענג לתענוג החומריות ח\"ו, כי האיך יברור אם הוא חושק לפסולת ברצונו. אבל הבירור הוא על ידי שיהיה דבוק בהשי\"ת באהבה ויראה, ומביא &lt;הכל ע\"י מדת&gt; היראה לאין, הוא חכמה, ור\"ל שמבין <span data-k=\"sm\">[בהכרה גדולה ועצומה]</span> שתענוג &lt;הגשמי&gt; זה &lt;הוא&gt; הבל ונמאס בעיניו, וברצונו לא היה <span data-k=\"sm\">[עושה]</span> &lt;נהנה מ&gt;זה התענוג הגשמי, כמו אכילה ושתיה &lt;ומשגל&gt; <span data-k=\"sm\">[וזיווג]</span>, רק <span data-k=\"sm\">[הוא מוכרח מאת השי\"ת]</span> מחמת &lt;מצות הבורא, וגם&gt; שיש בזה ניצוץ מאהבת ותענוג הבורא <span data-k=\"sm\">[שנתגשם ונעשה פסולת וחומריות]</span>, והוא עי\"ז התענוג מפריד את עצמו מן הפסולת ונמאס בעיניו תאוות של הפסולת מחמת חכמה. כמו מי שהוא חכם ומביאים לו איזה דבר גרוע, מטבע או בגד, והוא צבוע בצבע טוב מאד, מי שהוא כסיל דומה לו שהוא טוב כולו, והחכם מבין שהצבע הוא טוב &lt;לבד&gt;, <span data-k=\"sm\">[אבל עצמותו רע, ומפריד בחכמתו הטוב מן הרע. ככה מי שהוא דבוק בבורא ית\"ש ע\"י יראה המביאה לידי חכמה . . .]</span> וזהו מ\"ש בזוהר הכל בחכמה אתברירו <span data-k=\"sm\">[ולפעמים אומר במחשבה אתברירו]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כב</b>,<b> ב (יד</b>\"<b>א פ</b>'<b> יז</b>-<b>יח)</b>\n<i>טעמו וראו גו'</i> – תהלים לד, ט. <i>יפצחו גו'</i> – ישעי' מד, כג. <i>וירננו עצי היער</i> – תהלים צו, יב. <i>וגר זאב עם כבש</i> – ישעי' יא, ו. <i>לא ירעו גו'</i> – ישעי' יא, ט. <i>בני ישראל עם קרובו</i> – ע\"פ תהלים קמח, יד. <i>למען נסותינו כו'</i> – ע\"פ עקב ח, טז. <i>לאין הוא חכמה</i> – תקו\"ז רתמ\"ב פא, ב. תקזו\"ח צח, רע\"א. <i>מ\"ש בזהר הכל כו'</i> – זח\"ב רנד, סע\"ב. ע\"ח שי\"ח פ\"ה. שם של\"ט פ\"א.\n----- שולי הגליון -----\n[ftn_1_מח]) <i>בהמשך בא כאן המשל המובא לעיל בסי' רז</i><i>א</i><i> עם ביאור הנמשל (בשינוי לשון)</i>,<i> בנ\"ד</i>,<i> ומסיים</i>: ועי\"ז הוא <i>(כבפנים)</i>.\n----- הערות וציונים -----\n<i>אם הוא דבוק בגשמיות כו'</i> – ראה לעיל סי' רלח ורלט.\n<i>יפול בשיחה עמוקה אם כו'</i> – להעיר מהמובא באור נערב להרמ\"ק ח\"א פ\"ו.\n<i>להרחיק א\"ע בכל הרחקות כו'</i> – להעיר מחובה\"ל שער התשובה פ\"ה ד\"ה והשני: כמ\"ש כו' שהיו פורשים מע' שערים משערי המותר מיראתם שער אחד משערי האסור כו'.\n<i>רק מי שהוא מופשט מגשמיות ואפילו הכי כו'</i> – ראה לעיל סי' לט ובהערות שם.\n<i>ניצוצין קדישין מפסולת המאנין תבירין</i> – ראה לעיל סי' צג וקיב, ולקמן סי' רפז ורצה.\n<i>ומביא היראה לאין הוא חכמה כו'</i> – ראה מדל\"י סי' לא (כז), עד (פה), ושם שלהי סי' צא (ק) ורלב (רמו).\n<i>בחכמה אתברירו כו'</i> – ראה מדל\"י סי' לא (כז) ושם סו\"ס קז (קיח) וקל (קלט), ומסיים כאן ביד\"א \"כל זה דברי הקדוש הנ\"ל\", ונראה שכונתו להרה\"מ שמזכירו תיכף לפני התחלת פיסקה זו עיי\"ש. ולהעיר שאחרי פיסקה זו ממשיך: ולא כמו חסירי השכל שבזמנינו הלומדים קבלה וסוברים שיוכלו לברר הניצוצות באכילה ע\"פ כוונת האכילה, והאיך אפשר זה אם אינם במדריגה הנ\"ל שיהי' להם יראה המביאה לחכמה הנ\"ל, במחשבתם יחשבו כוונות ואעפי\"כ יענגו בה, כמ\"ש הקדוש מו' מנחם זלה\"ה שבאכילה מתוך לשמה באין שלא לשמה כמו שידעת, אבל העיקר כנ\"ל. (ולהעיר על זה מהמובא בצוה\"ר סי' סה עיי\"ש)."]]],[300010293,"רמ-ב\n\n<b>&lt;החכמה</b> נקרא נסתר, פי' כי נסתר&gt; <span data-k=\"sm\">[חכמת הנסתר, ששמעתי מפה קדוש מו' מנחם מענדל שנסתר]</span> נקרא &lt;מה&gt; <span data-k=\"sm\">[דבר]</span> שאין אדם יכול &lt;להשיגו&gt; <span data-k=\"sm\">[להבינו]</span>, כמו טעם של המאכל אי אפשר לספר לאדם שלא טעם טעם זה מעולם, א\"א לפרש לו בדיבור איך ומה, ונקרא זה דבר סתר. כמו כן ענין אהבת הבורא ויראתו ית\"ש אי אפשר לפרש לחבירו איך הוא האהבה בלב, וזה נקרא נסתר. אבל מה שהם קוראים נסתר חכמת הקבלה, האיך הוא נסתר, הלא כל מי שרוצה ללמוד הספר לפניו, ואם אינו מבין הוא עם הארץ, ולפני איש כזה גמרא ותוס' ג\"כ נקרא נסתר. אלא ענין הנסתרות שבכל הזוהר וכתבי האריז\"ל הכל בנויים על פי דביקות האלקות <span data-k=\"sm\">[למי שזוכה להדבק ולהיות צופה במרכבה העליונה. . .]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כג</b>,<b> ג (יד</b>\"<b>א פכ</b>\"<b>ב)</b>\n<i>החכמה נקרא נסתר</i> – תקו\"ז יז, א. שם ת\"י כה, ב.\n----- הערות וציונים -----\n<i>אהבת הבורא ויראתו ית\"ש כו'</i> – ראה זח\"ג רכג, ריש ע\"ב. תקוזו\"ח קא, סע\"ב."]]],[300010294,"רמא\n\n<b>פי'</b> הפסוק נעשה אדם בצלמנו, למשל אדם שיש לו בן, אף שהבן עבר מכנגד פניו והלך מאתו, עם כל זה נחקקה הצורה של הבן במחשבת האב, אך מי שלא היה לו בן מעולם לא שייך בו לומר שיהא נחקק במחשבתו צורת הבן שיהא לו אח\"כ, כי עדיין לא ראה אותו ולא הכיר צורתו, זהו דרך בני אדם. אבל בהש\"י שייך זה לומר אף קודם שנבראו ישראל היה נחקק צורתם במחשבה, כמו שאמרו רז\"ל ישראל עלו במחשבה, כי אצלו ית' העבר והעתיד אחד.\n<b>וז\"ש</b> נעשה אדם, ר\"ל ישראל הנקרא אדם, בצלמנו, פי' באותו צלם וצורה שהיה נחקק במחשבה, וזהו כדמותנו, ר\"ל באותו דמיון שהיה במחשבה קדומה, &lt;נעשה אדם עתה&gt; <span data-k=\"sm\">[עתה נעשה אותו]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י לא</b>,<b> סע</b>\"<b>ד (סי</b>'<b> רמט)</b>\n<i>נעשה אדם גו'</i> – בראשית א, כו. <i>ישראל עלו במחשבה</i> – זח\"א כד, א. בר\"ר א, ד. <i>ישראל הנקרא אדם</i> – יבמות סא, א.\n----- הערות וציונים -----\nראה מדל\"י סי' רה (רטו)."]]],[300010295,"רמב\n\n<b>כי</b> תורה חדשה מאתי תצא, וקשה הלא לא יחליף ולא ימיר דתו כו', אלא ה\"פ, לפי שעתה נתלבשה התורה בספורי מעשיות, כגון דלבן ובלעם, ולעתיד לבא יפרש איך דבר הכל מאתו, מבנין עולמות העליונים והתחתונים. וז\"ש תורה חדשה מאתי תצא, אפשר הפי' איך מדבר הכל מאתי<i>[ftnref_1_מט]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>קיצור לקו</b>\"<b>י לב</b>,<b> רע</b>\"<b>א (סי</b>'<b> רנ)</b>\n<i>כי תורה חדשה כו'</i> – ויק\"ר יג, ג ע\"פ ישעי' נא, ד. <i>לא יחליף כו'</i> – פיוט יגדל. הל' יסוה\"ת פ\"ט. <i>באורייתא ברא כו'</i> – זח\"א ה, א. <i>שגם בתורה יש כ\"ז</i> – ר' זח\"א קלד, ב. <i>בגמרא</i> – עירובין כא, ב. <i>ולהג גו'</i> – קהלת יב, יב. <i>ותגיד לב\"י</i> – יתרו יט, ג. <i>התחיינה גו'</i> – יחזקאל לז, ג.\n----- שולי הגליון -----\n[ftn_1_מט]) <i>לפי הנראה סימן זה קיצור תוכן ס' רנ בס' לקו\"י</i>:\nכי תורה חדשה מאתי תצא, כי הנה ידוע באורייתא ברא קב\"ה עלמא, והנה יש בעולם עור ובשר וגידין ועצמות, ומוכרח הוא שגם בתורה יש כל זה, כי בהכרח שיהיה בפועל מה שהוא בנפעל, כי כח הפועל בנפעל, אך כי באמת יש כל אלה בתורה, כי פשטיות התורה הוא סוד עור, ובשר התורה על דרך מה שאמרו בגמרא על פסוק ולהג הרבה יגיעת בשר, בכל פעם שהוא לומד טועם בו טעם בשר, וגידין הוא מרומז בלשון ותגיד לבני ישראל, כמו שכתב רש\"י שם, אך העצמות של התורה אין אנו יכולין להשיג עתה רק לעתיד, וזהו סוד הפסוק ביחזקאל התחיינה העצמות האלה, ואמר ה' אלהים אתה ידעת, ר\"ל אם ההתקשרות יהיה ממך אז יהיה מושג ומובן העצמיות, והסוד הוא למה באמת אינו מובן עתה העצמיות של התורה, ואין משיגים אותה, ולמה הוא כך, אך לפי שאין עתה התורה אלא רק מה שנלקח מבני אדם, קצת תורה נלקחה מלבן, כלומר מהסיפורים שלו, וקצת מסיפורי בלעם, וקצת מסיפורי שאר בני אדם הכתובים בתורה, אך לעתיד יהיה התקשרות קוב\"ה בתורה, ועתידים אנו להשיג גם העצמיות, וזהו שאמר כי תורה חדשה מאתי תצא, ר\"ל [מעצמיותי] ולא כמו עתה שהתורה היא רק מהסיפורים כנ\"ל.\n----- הערות וציונים -----\nבשנויים במדל\"י סי' ו, וכן באו\"ת סי' שטו.\n<i>כי תורה חדשה כו'</i> – ראה לעיל סי' פד ד\"ה ותירץ, עיין חסד לאברהם מעין ב פ' יא-יב."]]],[300010296,"רמג\n\n[<b>עיקר</b> <span data-k=\"sm\">הכונה היא שבירת הלב בהכנעה ודביקות להש\"י, כמ\"ש]</span> בכתבים בשם ר' בער ז\"ל, משל על זה הענין, שיש לכל מסגר מפתח שפותח בכיון, ולפי המסגר כן מכוין המפתח, ויש גנבים שפותחים בלי מפתח, דהיינו ששוברים המסגר. כן הענין יש לכל דבר נעלם מפתח, והיא הכונה המכוונת לאותו דבר, אבל עיקר המפתח הוא להיות כגנב ששובר הכל, דהיינו לשבור הלב היטב בהכנעה גדולה ויושבר המסך המבדיל למעלה שעל ידו הוא ההסגר לאדם.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כח</b>,<b> ריש ע</b>\"<b>ב (יד</b>\"<b>א ספמ</b>\"<b>ב)</b>\n----- הערות וציונים -----\n<i>כמ\"ש בכתבים כו'</i> – ראה אור האמת יד, ב. וכן הובא המשל בשם הרה\"מ בס' תורי זהב להר\"ב מזאלאזיץ, במאמרים לר\"ה, וממשיך: כן הראשונים היו פותחים כל השערים הננעלין לאחר חורבן במפתחות, דהיינו בכוונות ידועות לכל שער ושער, משא\"כ דורות האחרונים שאין כח הכוונות בידינו צריכים אנו לשבר כל המנעולים בלי מפתחות רק בשבירת לבנו הרע. ולהעיר מצוה\"ר סי' קיח."]]],[300010297,"רמד\n\n<b>בשם</b> <i>ריבעש\"ט</i>, הזהר בגחלתן שלא תכוה וכו' שכל דבריהם כגחלי אש, והקשה ממה נפשך, אם גחלת סתם פירושו לוחשות, למה לי כגחלי אש, ואם סתם גחלת משמע עוממות, קשה מה שאמר הזהר בגחלתן שלא תכוה, הלא סתם גחלת הם עוממות.\n<b>ואמר</b> ז\"ל, כי הנה לפעמים צדיק גמור נופל ממדריגתו ועובד להש\"י בקטנות, דהיינו שאינו מתפלל בכונה גדולה, וגם הולך בטל לפעמים, יהרהר אדם הרואה את הצדיק במדריגה כזו ושאין &lt;תורתו ותפלתו&gt; <span data-k=\"sm\">[תפלתו ולימודו]</span> כ\"כ בכונה, שגם הוא יעשה כן, מה אם זה שהוא צדיק וחסיד עושה כך מכל שכן הוא. ולזה הזהיר התנא שלא ידמה א\"ע להת\"ח וצדיק, כי צדיק זה כשיתעורר <span data-k=\"sm\">[משינתו]</span> ויתחיל ללמוד ולהתפלל &lt;בכונה עצומה&gt;, יעלה כל הדברים בטילים שדיבר, וכל המעשים שעשה עד הנה, <span data-k=\"sm\">[כקודם יעלה הכל למעלה]</span>, כידוע מסוד העלאת ניצוצין אף מדברים בטילים. אבל אתה אדם הרואה, אדם פשוט שאינך יודע כלל מסוד עבודת הבורא ית', איך מלאך לבך לדמות א\"ע אליו. וזהו הזהר בגחלתן, ר\"ל בשעה שנפל ממדריגתו ונקרא אז גחלת עוממות, דהיינו שמדבר דברים בטלים ושאר מעשים, הזהר שלא תלמוד מהם, שכל דבריהם, אפילו דברים בטלים שלהם, כגחלי אש כנ\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י לב</b>,<b> א (סי</b>'<b> רנב) [צוה</b>\"<b>ר סי</b>'<b> צו]</b>\n<i>הזהר בגחלתן כו'</i> – אבות פ\"ב מ\"י.\n----- הערות וציונים -----\nראה לקמן סי' שסו.\n<i>אם כו' והקשה כו' לוחשות כו' עוממות כו'</i> – ראה הסוגיא בפסחים עב, ב.\n<i>לפעמים צדיק גמור נופל כו'</i> – בסוד כי שבע יפול צדיק וקם (משלי כד, טז). ראה צוה\"ר סי' סד. ותורת הבעש\"ט במאור עינים, פ' שמות ד\"ה וזהו רבות. מדל\"י סי' סח (פ) – וגם זה מהבעש\"ט כמפורש באו\"ת פ' תצא סי' קעה, ועוד שם סס\"י קעז (קפג). לקו\"י סי' ריג ורנג. ראה עוד קדושת לוי, שה\"ש ד\"ה לריח שמניך, ומה שהביא שם בשם הבעש\"ט והרה\"מ.\n<i>יהרהר אדם הרואה כו'</i> – ראה לקו\"י סס\"י רפד. ולהעיר משם סי' קיג.\n<i>ויתחיל ללמוד ולהתפלל יעלה כו'</i> – ראה זח\"ב רמה, ב ובמ\"מ שם. שערי אורה להרי\"ג שער ב (ל, סע\"ב ואילך). והובא בתניא ספל\"ט ושם קו\"א סי' ג. וראה לקמן סי' שנו."]]],[300010298,"רמה\n\n<b>והאלהים</b> נסה את אברהם, &lt;וקשה&gt; <span data-k=\"sm\">[ויש לדקדק]</span> מה הלשון את אברהם, הוה ליה למימר נסה אברהם. ויובן עפ\"י הידוע כי מדת אברהם הוא חסד, כמ\"ש חסד לאברהם, וארז\"ל שיש מלאכים שאין אומרים שירה כי אם פעם אחת בשבוע, וי\"א פעם אחת ביובל, ומה שאומרים אומרים בקיצור, יש שאומרים קדוש, ויש שאומרים ברוך, ויש אומרים פסוק א', כמ\"ש על מלאכים ידועים שאומרים פסוק א' מן מזמור הודו לה' כי טוב כי לעולם חסדו וכיוצא. והנה לאיש הישראלי הורשה לומר ולקלס בכל עת וזמן ולהאריך בכל מיני קלוסין ושירות ותשבחות.\n<b>ולהבין</b> זה, משל למלך שבאו כל עבדיו ושריו לומר &lt;שירה&gt; <span data-k=\"sm\">[הימנון]</span> לפניו לקלסו, והנה לכל אחד ואחד יש זמן ושיעור לקילוסו לפי ערכו וחשיבותו, וכל זה הוא כאשר יש רצון לפני המלך. אבל אם פני המלך ח\"ו בכעס, אזי יראים הם לקלסו כל עיקר, כמ\"ש מה לקלס המלך בעת הזעם, ומחמת חשש זה שהם מסופקים אולי ח\"ו המלך בכעס <span data-k=\"sm\">[עתה, ואולי יכעוס]</span> בשביל איזה דבר, לכן דרכם לקצר בכל היכולת ותיכף לצאת מאת פניו. והנה בבוא בן המלך חביבו ואהובו לקלס המלך, הנה הבן אינו חושש לכל &lt;זה&gt;, דאפי' אם המלך הוא בכעס, כאשר רואה בנו חביבו נכנס שמחה ותענוג לאביו. והנה בבוא השמחה ואהבה, נסתלק הכעס והזעם &lt;פי' שנמתקים הדינים בשרשם&gt;, <span data-k=\"sm\">[וצריך להבין זה איך נסתלק ולאיזה מקום נסתלק הכעס, הגם שהוא כך טבעיות מ\"מ צריך להבין ענינו. ונראה לומר שכאשר האהבה והשמחה גוברות וגורמות להכעס והזעם שיעלה למעלה אל שרשו, ושם הוא נמתק, כידוע שהדינים אינם נמתקים אלא בשורשם]</span>.\n<b>וזהו</b> פי' הפסוק והאלהים נסה את אברהם, ר\"ל אלהי\"ם, שהוא הדינים, במה נסה, נתעלו ונסתלקו למעלה ונמתקו, ולמה, את אברהם &lt;בשביל אברהם&gt;, כלומר מכח האהבה והחסד שהוא אברהם, שהוא נמשל לבן המלך כנ\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>קטע מלקו</b>\"<b>י לב</b>,<b> ד (סי</b>'<b> רסד) [צוה</b>\"<b>ר סי</b>'<b> קלב]</b>\n<i>והאלקים נסה גו'</i> – וירא כב, א. <i>הל\"ל נסה אברהם</i> – זח\"א קיט, ב. <i>מדת אברהם הוא חסד</i> – זח\"ג שב, א. ס' הבהיר סי' קלה. <i>חסד לאברהם</i> – מיכה ז, ב. <i>וארז\"ל שיש מלאכים כו'</i> – חולין צא, ב. <i>כמ\"ש על מלאכים כו'</i> – סידור האריז\"ל לרש\"ר שחרית לשבת (ע, ב). <i>מזמור הודו לה'</i> – תהלים קלו. <i>מה לקלס כו'</i> – קינות לתשעה באב ד\"ה על חרבן ביהמ\"ק, אות ז. <i>שהדינים אינם נמתקים אלא בשורשם</i> – ע\"ח שי\"ג פי\"א. פע\"ח שער השופר פ\"א. <i>אלהי'ם שהוא הדינים</i> – ספרי ר\"פ ואתחנן פ' כו. בר\"ר לג, ד. זח\"ג סה, א.\n----- הערות וציונים -----\n<i>במה נסה נתעלו</i> – נסה לשון נס, רוממות ועליה כמו (ישעיה סב, י) הרימו נס (זח\"א קמ, א; וראה רש\"י יתרו כ, יז ע\"פ המכילתא שם), וכן הובא בלקו\"י בריש דרוש זה.\n<i>ונמתקו כו' מכח האהבה והחסד שהוא אברהם</i> – ראה זח\"ג לא, א ושם רג, רע\"א. ולהעיר מזח\"ב נז, סע\"א."]]],[300010299,"רמו\n\n<b>כי</b> שמש ומגן ה' אלהים, &lt;פי'&gt; <span data-k=\"sm\">[וידוע]</span> כי שם הוי' נקרא שמש, וז\"ש שמש ומגן, &lt;פי' כמו מחיצה המגין בעד אור השמש&gt; הוא הדמיון כמו ה' אלהים, ר\"ל כמו שא\"א להסתכל בשמש מגודל אור בהירתו אם לא ע\"י מגן ומסך המבדיל שהוא המגן בעד אור השמש שיוכלו &lt;חלושי הראות&gt; ליהנות מאורו, כך הוא שם הוי' ב\"ה שאורו רב מאד מגודל אור בהירותו <span data-k=\"sm\">[אור החסד והרחמים שבו, אם לא היה לאורו הגדול מסך המבדיל לא היו יכולים העולמות לקבלו]</span>, לכך הוצרך לצמצמו ולהגבילו בתוך שם אלהים &lt;גי' הטבע&gt;, שהוא המגן.\n<b>וזשארז\"ל</b> לע\"ל הקב\"ה מוציא חמה מנרתיקה <span data-k=\"sm\">[והרשעים מתלהטין בה והצדיקים מתרפאין]</span> כו', <span data-k=\"sm\">[רמזו להנ\"ל]</span>, פי' שלע\"ל יוציא שם הוי' מנרתיקו שהוא שם אלהים &lt;גי' הטבע&gt;, שעתה הוא מלובש בתוכו, &lt;וצדיקים מתרפאין בה&gt; <span data-k=\"sm\">[כי אז כח הצדיקים רב]</span>, ויקויים בהם והיו עיניך רואות את מוריך &lt;ויהיה ההנהגה עמהם למעלה מהטבע&gt;, ויוכלו לקבל בהירותו ורחמיו הגדולים <span data-k=\"sm\">[וחסדיו המרובים ומתרפאים בהם]</span>. אבל לא כן הרשעים אלא מתלהטין, כמ\"ש הנביא ה' כגבור יצא, כלומר ה' אע\"פ שהוא &lt;מדה\"ר&gt; <span data-k=\"sm\">[רחמים גמורים]</span>, עכ\"ז כשיוציא שם הוי\"ה מנרתיקה ילבוש נקם כגבור &lt;כו'&gt; <span data-k=\"sm\">[כמו מדת הדין, ויפרע מן האומות]</span>, &lt;שיתהפך לרשעים מדה\"ר למדה\"ד, כמ\"ש וה' הכה כל בכור, ויאמר ה' אמחה כו'&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>קטע מלקו</b>\"<b>י לה</b>,<b> ג (סי</b>'<b> ערה)</b>\n<i>כי שמש גו'</i> – תהלים פד, יב. <i>שם הוי' נקרא שמש</i> – זח\"ב רכד, ב. <i>א-להים גי' הטבע</i> – פרדס רמונים שי\"ב פ\"ב. ר\"ח שער האהבה פ\"א, רפ\"ח, ושלהי פי\"א. של\"ה, שער האותיות ע' קדושה. <i>לע\"ל הקב\"ה כו'</i> – ע\"ז ג, סע\"ב. <i>והיו עיניך גו'</i> – ישעי' ל, כ. <i>ה' כגבור יצא</i> – ישעי' מב, יג. <i>ה' </i>. .<i> מדה\"ר</i> – ספרי ר\"פ ואתחנן פ' כו. בר\"ר לג, ד. זח\"ג סה, א. <i>שיתהפך לרשעים כו'</i> – בר\"ר לג, ג. <i>וה' הכה גו'</i> – בא יב, כט. <i>ויאמר ה' אמחה גו'</i> – בראשית ו, ז.\n----- הערות וציונים -----\nלתוכן דרוש זה ראה בלקו\"י שם הרישא, ולקמן סי' רמז. תניא, שהיוה\"א פ\"ד.\n<i>ילבוש נקם</i> – ע\"פ ישעיה נט, יז.\n<i>ויפרע מן האומות</i> – ראה ילקוט המכירי לישעיה נט, יז (בשם מדרש שה\"ש). פסדר\"כ פ\"א דשוש אשיש (קמט, א).\n<i>שיתהפך לרשעים כו'</i> – להעיר מזח\"ג רצז, ריש ע\"ב.\n<i>וה' הכה</i> – להעיר מבר\"ר נא, ב (וש\"נ) כל מקום שנאמר וה' הוא ובית דינו, וכ\"כ בתנחומא הקדום פ' בא יז על פסוק זה. ברם בתנחומא הקדום פ' וארא כג דרש וה' המטיר אמר רשב\"נ אוי להם לרשעים שהם גורמים למקום של רחמים ליעשות מקום של פורענות כנ\"ל."]]],[300010300,"רמז\n\n<b>ויאמר</b> אלהים יהי אור ויהי אור, כלומר ויאמר הש\"י מכח מדת אלהים, שהוא מדת גבורה המצמצם האור מחמת זה יהיה אור המתקיים &lt;שיוכל העולם לסובלו&gt;. <span data-k=\"sm\">[וגם אמרו רז\"ל כל מקום שנאמר ויהי אינו אלא לשון צער, וז\"ש ויהי אור, ר\"ל מכח הצמצום שהוא נראה כמו צער לעולם מפני שהוא כמו מסך ומאפיל האור הגדול, ולעולם הוא נראה צער, ואדרבא ממנו נעשה האור האמיתי וקיום העולם, כמו ויתרון האור מן החושך, לכן נאמר ויהי אור כנ\"ל]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י לז</b>,<b> סע</b>\"<b>ב (סוף סימן רפ)</b>\n<i>ויאמר אלקים גו'</i> – בראשית א, ג. <i>א</i>-<i>להים שהוא מדת גבורה</i> – זח\"ג יא, ב. שם סה, א. <i>כל מקום שנאמר ויהי כו'</i> – מגילה י, ב. <i>ויתרון האור גו'</i> – קהלת ב, יג.\n----- הערות וציונים -----\nראה לקו\"י ריש סי' ערה, ולעיל סי' רמו. וראה מדל\"י סי' קטו (ריש קכו). תניא פמ\"ח, ושם שהיוה\"א פ\"ד ופ\"ו.\n<i>לשון צער וז\"ש ויהי אור כו'</i> – ראה זח\"א טז, סע\"ב ובמ\"מ שם."]]],[300010301,"רמח\n\n<b>י\"ז</b> תנאי המצות מבוארים בס' חרדים, ואלו הם תנאי השמירה מעבירה, כל העובר עבירה א' קונה לו קטיגור א'.\n<b>התנאי</b> הא', לחקור בכוונה עד היכן מגיע פגם העבירה שרוצה לעבור, ונגד מי מורד, ומי הרואה אותו אפי' במסתרים, ובאיזה זמן, האם הרשות נתונה לבטל זה הזמן מעבודת הש\"י, כ\"ש למרוד בו.\n<b>התנאי</b> הב', העצבות הגדול, דע\"י עבירה זו הוא משחית דיוקנו של מלך, והוא כפוי טובה, שבחיות שנתן לו הוא מורד ודורנא הוא משדר לסט\"א, ונסיון הוא דשדר לי' קב\"ה.\n<b>התנאי</b> הד', שלא יעשה מהעבירה לא כולה ולא מקצתה.\n<b>התנאי</b> הה', הדקדוק הגדול בעבירה, להזהר מכל פרטיה ודקדוקי'.\n<b>התנאי</b> [ה]ו', הניס' והבריחה וההמלטה מעבירה, כמרז\"ל ובורח מן העבירה, וירץ לעשות מצוה, כמרז\"ל הוי רץ למצוה קלה, ונאמר דרך מצותיך ארוץ, פי' צדקה וטבילה.\n<b>התנאי</b> הז', שלא יעשה העבירה לא ע\"י עצמו ולא ע\"י שלוחו.\n<b>התנאי</b> הח', עבירה שתבוא לידו ידחנה, וישגיח שלא יכשל בעבירה אחרת, מפני שעבירה גוררת עבירה.\n<b>התנאי</b> הט', לא יעשה ב' עבירות יחד, והרי בעבירה יש שני עבירות, אחת העבירה נגד הקב\"ה, ב' שמשחית נפשו ורוחו כו'.\n<b>התנאי</b> הי', שתהא העבירה בזוי' מאד בעיניו.\n<b>התנאי</b> הי\"א, לא יאמין בעצמו ולא יתעלם תמיד ממנו המורא הגדול והשמירה פן יבוא לידי עבירה ח\"ו, וזהו ירא חטא.\n<b>התנאי</b> הי\"ב, שיבזה ויטול עצמו ויבכה על רוע מזלו שבא לידו הרהור עבירה, ואבל יחיד יעשה לו קודם עשייתה, כמו שמתאבל אדם על קרוביו, כ\"ש דאדם קרוב אצל עצמו, והרי ע\"י העבירה ממית עצמו.\n<b>התנאי</b> הי\"ג, שיתבונן מה הוא מאבד בעונו עולם מלא, כמרז\"ל לא זכה אוי לו שהכריע עצמו וכל העולם כולו לכף חובה שנאמר וחוטא אחד יאבד טובה הרבה, ולפיכך נברא אדם יחידי, ללמדך שכל המאבד נפש א' מישראל כאלו איבד עולם מלא, כ\"ש נפשו של עצמו ובניו, שנאמר פוקד עון אבות על בנים.\n<b>התנאי</b> הט\"ז, כשיסיתנו היצה\"ר לעבירה, ירוץ אל מקום הרבה בני אדם, כי שם יתבייש, ויבוש על שלא בוש מהבורא ית\"ש.\n<b>התנאי</b> הי\"ז, שיתבונן שיתנו לו עונש על העבירה, כי אין הקב\"ה ותרן, ויתבונן במרירות העונשי' או בתשובת המשקל, ויהי' תמיד לבו נשבר בתשובה על העבירות שכבר עבר ויהי' כל ימיו בתשובה ושב ורפא לו.\n<b>תם ונשלם בעזרת ה'</b>"],[300010302,"הסכמה\n\n<b>הסכמת</b>\n<b>הרב הגאון הגדול מוהר\"ר</b> <b>משה צבי הירש</b> <b>מקהלתינו פה זאלקווא</b>\n<b>להגיד</b> שבחו של אהרן שלא שינה מדברי קדשו של הרב הקדוש מוהר\"ר ישראל בעל שם טוב זלה\"ה, אשר כבר הדפיס קונטרס אחד נקרא בשם כתר שם טוב, ה\"ה כבוד הרבני המופלג והמופלא מוהר\"ר אהרן במוהר\"ר צבי הירש הכהן מק\"ק אפטא, כהן וחורז חרוזות מרגליות דברי חכמה וצניעות בנגלה ונסתר, הסתר מן התורה, ולפעלא טבא אמרין ישר כחו וחילו לאורייתא כי דבריו נתקבלו באהבה, רבים שתו הלכו לאורו אור הבהיר, וכעת הוסיף שנית ידו, ידים הבאים מחמת ספר, מחדושי הרב הנ\"ל תוספת מרובה על העיקר, אמרתי כל מן דין סמוכן לנא, מגישים טעם לעלות הדברים אל מזבח הדפוס ויקבענו כיון, וחלילה לעשות במתכונתו למהדרא לדפוס קמא בלתי רשות המדפיס מוהר\"ר אהרן הנ\"ל, הן חלק שני זה הן חלק ראשון מסתיי' דליקום בארור מסיג גבול רעהו, אשרי אדם שומע לי ישכון בטח ושאנן עד ביאת ינון, פי המדבר לכבוד התורה היום יום ג' א\"ך אלול תקנ\"ד.\n<b>ה\"ק משה צבי הירש מייזליש </b>פה זאלקווא",[["","","----- מקורות ומראה מקומות -----\n<i>י\"ז תנאי המצות </i>. .<i> בס' חרדים</i>: <b>בהקדמה שם.</b>\n<i>העובר עבירה א' כו'</i> – אבות פ\"ד מי\"א. <i>ובורח מן העבירה</i> – אבות פ\"ד מ\"ב. <i>דרך מצותיך ארוץ</i> – תהלים קיט, לב. <i>הוי רץ כו'</i> – שם. <i>עבירה גוררת כו'</i> – אבות שם. <i>לא יאמין בעצמו</i> – ע\"פ אבות פ\"ב מ\"ד. <i>אדם קרוב אצל עצמו</i> – סנהדרין ט, סע\"ב. <i>ע\"י העבירה ממית עצמו</i> – ר' תקו\"ז ת\"ה קמב, ב. זח\"ג פו, ב. שם קנט, ב. <i>כמרז\"ל אוי לו כו'</i> – קידושין מ, ב. <i>וחוטא אחד גו'</i> – קהלת ט, יח. <i>ולפיכך נברא אדם יחידי כו'</i> – סנהדרין לז, א. <i>פוקד עון גו'</i> – יתרו כ, ה. <i>אין הקב\"ה ותרן</i> – ב\"ק נ, סע\"א. תנחומא תשא כו. <i>כל ימיו בתשובה</i> – שבת קנג, א. זח\"ג לג, סע\"א. <i>ושב ורפא לו</i> – ישעי' ו, י.\n----- הערות וציונים -----\nחסרים כאן תנאי הי\"ד ותנאי הט\"ו.\n<i>(ב) העצבות כו'</i> – ראה לקמן בהוספות סי' רה. צוה\"ר סי' טו, מד ומו, והנסמן שם בהערות. ולהעיר מסוף הקדמות הרח\"ו לע\"ח, ערך השגת החכמה, דמדת עצבות מגונה עד מאד. ורג\"כ בריש שער רוה\"ק לג, ב מש\"כ על זה.\n<i>(ט) ע\"י העבירה ממית עצמו</i> – ראה זח\"ג קנט, ב. סוף תקו\"ז ת\"ה קמב, ב. ולהעיר מספרי פ' תצא פי' רנב.\n<i>(טז) ירוץ אל מקום הרבה בני אדם כו'</i> – להעיר מברכות כח, ב."]]],[300010303,"רמט\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; במדרש ויהי ערב אלו מעשיהם של רשעים ויהי בקר אלו מעשיהם של צדיקים ואיני יודע באיזה מהם חפץ, כשהוא אומר וירא אלקים את האור כי טוב הוי אומר במעשיהם של צדיקים חפץ יותר. והוא תמוה, וכי ס\"ד שחפץ במעשיהם של רשעים. וביאר <span data-k=\"sm\">[.</span><span data-k=\"sm\"> . </span><span data-k=\"sm\">.]</span><i>[ftnref_1_נ]</i>\n<b>כי</b> יש מעשי הרשעים אכילה ושתיה ושמחה ושחוק וכיוצא, ויש מעשי &lt;צדיקים&gt; תענית וצום ובכי ומספד וכיוצא. אמנם כשנתגברה חולי המרה שחורה ע\"י עצבות וסיגופים וכיוצא אז צריך לאחוז במדת הרשעים לאכול ולשתות ולשמוח להסיר החולי הנ\"ל. ולפעמים כשרואה שיצה\"ר מתגבר בו ילבש שחורים ועצבות. וכל זה צריך לשקול במאזני שכלו. וז\"ש ואיני יודע באיזה מהם חפץ וכנ\"ל, ואם אין לו דעת להכריע איזה דרך הטוב ילך לת\"ח שהם רופאי הנפשות, וכמ\"ש הרמב\"ם פ\"ב מה' דיעות יעו\"ש.\n<b>ובזה</b> יובן איש כי תשטה אשתו, שהוא החומר והגוף שעל ידו נטה ושטה מדרך הישר ואינו יודע באיזה דרך יבחר וכנ\"ל, אז והובא אל הכהן, שהם הת\"ח רופאי הנפשות. וז\"ש ולקח הכהן מים קדושים, הם דברי תורה, אל כלי חרש, ר\"ל להלביש במשל ומליצה ויאמר לו תוכחת מוסר שיהיה לו רפואה ע\"י מאזני שכלו הקודש. אמנם אם יתגאה בזה שוב אין דבריו נשמעים, לכך עצה היעוצה, מן העפר אשר יהיה בקרקע המשכן יקח הכהן וגו', ר\"ל שיקח הכהן מדת השפלות כעפר שבקרקע המשכן ויתן אל המים של תורה ומוסר, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ תרומה קד</b>,<b> רע</b>\"<b>ג ושם סע</b>\"<b>ג (שסו</b>,<b> ב ושם שסז</b>,<b> א)</b>\n<i>במדרש</i> – בר\"ר ב, ה. <i>ויהי ערב גו'</i> – בראשית א, ה. <i>וירא אלקים גו'</i> – בראשית א, ד. <i>ילבש שחורים כו'</i> – מו\"ק יז, א. <i>פ\"ב מהל' דעות</i> – ה\"א. <i>איש כי גו'</i> – נשא ה, יב. <i>אשתו שהוא החומר כו'</i> – תקו\"ז תכ\"א סא, א. <i>והובא אל הכהן</i> – ע\"פ נשא ה, טו (והביא האיש גו' אל הכהן גו'). <i>ולקח הכהן גו'</i> – נשא ה, יז. <i>מים </i>. .<i> תורה</i> – ב\"ק יז, א.\n----- שולי הגליון -----\n[ftn_1_נ]) <i>זהו קטע מסי' קפח דלעיל עיי\"ש</i>.<i> ובמקורו בצ\"פ כתב</i>: נראה לי לבאר פסוקי פרשת נשא כי תשטה אשתו וגו' והביא האיש את אשתו אל הכהן וגו' ולקח הכהן מים קדושים בכלי חרש ומן העפר יקח אשר יהי' בקרקע המשכן יקח הכהן ונתן אל המים וגו'. ושמעתי ממורי זללה\"ה פירוש בזה על פי ביאור משנה דאבות <i>(וממשיך במש\"כ לעיל סי' קפח</i>,<i> ואח\"כ</i>:<i>)</i> ונחזור לביאור <i>מורי</i> זללה\"ה בפסוק הנ\"ל, כי יש . . . (<i>כבפנים כאן</i>).\n----- הערות וציונים -----\n<i>כשנתגברה חולי המ\"ש ע\"י כו'</i> – ראה לקמן סי' שב-ג וצוה\"ר סי' נו.\n<i>אז צריך כו' להסיר החולי הנ\"ל</i> – ראה צ\"פ קיח, א (תטו, א): כי צריך הצדיק להתלבש לפעמים במדת הרשעים לשם שמים כמ\"ש במ\"א בשם מורי ומה בין תלמידיו של בלעם הרשע לתלמידיו של א\"א ע\"ה וכו' עיי\"ש. ראה לעיל סי' סח, וכן סי' סג. ובאורך בכתונת פסים פ' צו ז, ב.\n<i>ילבש שחורים ועצבות</i> – להעיר ממו\"ק יז, א ופירוש ר\"ח שם.\n<i>להלביש במשל ומליצה כו'</i> – להעיר מדמ\"א ר\"פ תצוה ד\"ה ואתה תצוה (הב'): ששמעתי מאא\"ז זללה\"ה ע\"פ שמן תורק שמך ע\"כ עלמות אהבוך שצריך לפעמים להלביש התורה בלבושין כדי להכניס בלבבות ב\"א, משל לרופא שרואה שהחולה אינו יכול לקבל הרפואה כי היא מר בעיניו צריך ללבוש הרפואה במיני מתיקה כדי שיקבל, וזה שמן תורק שמך ע\"כ עלמות אהבוך וד\"ל וכו' עיי\"ש. בענין משל זה להעיר מלקמן סי' שב-ג.\n<i>אם יתגאה בזה כו'</i> – ראה לעיל סי' קלא (נשנה לקמן סי' רנא-ב). וראה שם עוד סי' קיג."]]],[300010304,"רנ\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה. כל העושה מצוה אחת מטיבין לו ומאריכין לו ימיו כו' מ&gt;דמצינו שלא אמר &lt;הקב\"ה&gt; רק מצות עשה אחת במפורש, אנכי ה' אלקיך, והיינו לכוונה זו דגם בקיים &lt;מ\"ע&gt; <span data-k=\"sm\">[מצוה]</span> אחת כראוי סגי. ובאמת יש סברא ברורה לזה על פי החקירה שכתבו הראשונים בראוי לידע סוד אחדותו ית', כי בכל מקום שאני תופס ואוחז בקצה וחלק מחלק האחדות הרי אני תופס כולו, וכן שמעתי <i>ממורי</i> והבן.\n<b>והנה</b> מאחר שהתורה והמצות נאצלו מעצמותו ית' שהוא אחדות האמיתי, א\"כ כשמקיים מצוה א' על מכונה ובאהבה שהוא הדביקות בו, ותפס במצוה זו חלק האחדות, א\"כ כולו בידו כאלו קיים כל המצות שהם כללות אחדותו פרצוף שלם כביכול והבן, ודפח\"ח. <span data-k=\"sm\">[וכן כתב בזוהר נשא דף קכ\"ד במקיים מצוה אחת על מתכונתו סגי]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י יתרו מט</b>,<b> ב (קפב</b>,<b> א)</b>\n<i>כל העושה כו'</i> – קידושין לט, ב. <i>רק מ\"ע אחת במפורש</i> – מכות כד, א. <i>אנכי ה' גו'</i> – יתרו כ, ב. <i>החקירה שכתבו הראשונים</i> – פי' הר\"י יעב\"ץ למס' אבות פ\"ד מ\"ב ד\"ה הוי רץ. ס' חרידים, בסוף מע' מצוות התלויות בא\"י.\n----- הערות וציונים -----\n<i>ע\"פ החקירה כו'</i> – מכאן ואילך כבר הובא לעיל סי' קיא-א ועיי\"ש בהערות. ורג\"כ לעיל סי' סה."]]],[300010305,"רנא-א\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; ויגש אליו יהודה [<span data-k=\"sm\">.</span><span data-k=\"sm\"> . .</span>] &lt;פי'&gt; כי יש ב' סוגים אנשים, א' המתנהג על פי הטבע, שהוא גי' אלקים, הנקרא יהודה מלכות, ב' המתנהג למעלה מהטבע, בחינת צדיק מושל ביראת אלקים שהוא מבטל גזירת אלקים, וזה נקרא יוסף הצדיק. וכאשר אחד באחד יגשו ונתחברו ב' סוגים הנ\"ל נעשה הכל בחינה אחת כנודע, כי זה כסא לזה <span data-k=\"sm\">[כאשר שמעתי מפי </span><i>מורי</i><span data-k=\"sm\"> הרבה בזה, כמו שמצינו ב' אנשים שאחד נעשה לבוש וכסא לחבירו, כמו זה שמתנהג ע\"פ המדריגה שהיא למעלה מהטבע ומכל מקום כל דרכיו נעשה ע\"פ בני אדם המתנהגים בטבע, אם כן נעשה זה כסא לזה]</span>, ובהתחברם אחד באחד יגשו ונעשה הכל אחד <span data-k=\"sm\">[והבן]</span>.\n<b>וז\"ש</b> ויגש אליו יהודה, ר\"ל שנגש ונתחבר בחינת יהודה אל בחינת יוסף, ויאמר בי אדני, פי' בי נקראת אדון למעלה מהטבע כמו אברהם <span data-k=\"sm\">[שהי' ראש מאמינים, ומ\"מ כל דרכיו נגמר ונעשה ע\"י מלכות יהודה והוכן בחסד כסא. . .]</span>",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י משפטים נו סע</b>\"<b>ב (רט</b>,<b> א)</b>\n<i>ויגש גו'</i> – ויגש מד, יח. <i>הטבע שהוא גי' אלקים</i> – פרדס רמונים שי\"ב פ\"ב. ר\"ח שער האהבה פ\"א. שם פ\"ז. ריש פ\"ח. שלהי פי\"א. של\"ה, שער האותיות ע' קדושה. <i>צדיק מושל גו'</i> – ש\"ב כג, ג. <i>שהוא מבטל כו'</i> – מו\"ק טז, ב. <i>אחד באחד יגשו</i> – איוב מא, ח. בר\"ר צג, ב. <i>ויאמר בי אדני</i> – ויגש מד, יח. <i>אברהם שהיה ראש מאמינים</i> – ראה שמו\"ר כג, ה (ופי' מהרז\"ו שם). <i>והוכן בחסד כסא</i> – ישעי' טז, ה.\n----- הערות וציונים -----\n<i>יש ב' סוגים כו'</i> – ראה מזה בתוי\"י שם לפני דיבור זה. וכן שם פ' מקץ לא, א (קיא, ב) ביאור הבעש\"ט להרבה עשו כרשב\"י, ועוד שם ס\"פ שמות לז, ד (קמ, א) בענין דן ונפתלי.\n<i>וכאשר אחד באחד יגשו כו'</i> – ראה תוי\"י פ' וישב כט, ב (קה, א) מורי ביאר פסוק כל אשר תמצא ידך לעשות בכחך עשה כי כשעושה מעשי גשמי ומקשר עם המחשבה למעלה בדעת העליון נעשה יחוד קבה\"ו וכו' עיי\"ש (ראה לעיל סי' מב, צא וקפט), ונודע כי מלכות מקנן בעשיה (ראה תקו\"ז ת\"ו כג, א) ונק' יהודה (זח\"ב קד, רע\"א) ועולם המחשבה והדעת נק' יוסף (ראה לקו\"ת להאריז\"ל פ' וישב) כמ\"ש בקו\"א בשם מורי כי משיח הוא סוד הדעת והוא סוד התחי\"ה כו' (הובא לעיל סי' קנח. וראה לקמן סי' שע), ובזה יובן ויגש אליו יהודה שמלכים נועדו יחדיו (תהלים מח, ה) לעשות מעשה הגשמי שהיא מל' הנק' יהודא ולקשרו עם הדעת הנקרא יוסף אז עברו יחדיו שנמחל עונות וכמו ששמעתי ממורי שעי\"ז יוכל לבטל כל גזירות רעות כשמקשר המלכות הנק' אני עם המחשבה הנק' אין (ראה לעיל סי' קפט-ב) והבן. (ובהמשך שם, דף ד', ע\"ד ב' הסוגים הנ\"ל, וגם שם בקשר למאמר הרבה עשו כרשב\"י).\n<i>כי זה כסא לזה</i> – ראה בהערות לסי' קפח וש\"נ."]]],[300010306,"רנא-ב\n\n<b>&lt;וז\"ש&gt;</b> <span data-k=\"sm\">[ונראה דשמעתי בשם הרב המגיד מו' מנחם מענדל מ\"ש בזוהר]</span>, זכאה מאן דאחיד בידא דחייבא, כי באומר מוסר לבני עירו יראה לקשר א\"ע תחלה בו ית' ואח\"כ יראה לקשר א\"ע עמהם מצד האחדות והתכללות, כי שורש אחד לראשי הדור עם בני דורו, וכשעושה כך אז ה' אלקיו עמו ויעל עמהם לדבק אותם בו ית\"ש. וז\"ש דאוחז בידם להעלותם וא\"כ עושה פעולה מיד באמירתו תוכחה ומוסר לעם בני ישראל <span data-k=\"sm\">[ודפח\"ח]</span>, וכן שמעתי זה הדרך <i>ממורי</i> בענין התפלה להעלותם ג\"כ.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י משפטים נט</b>,<b> ב (ריט</b>,<b> ב)</b>\n<i>זכאה מאן דאחיד כו'</i> – זח\"ב קכח, ב. <i>ה' אלקיו עמו ויעל</i> – דה\"ב לו, כג.\n----- הערות וציונים -----\nכבר הובא לעיל סי' קיג עיי\"ש."]]],[300010307,"רנב\n\n<b>שמעתי</b> <i>ממורי</i> ענין וידוי אשמנו &lt;עפ\"י משל&gt; שהמלך בעצמו כסות ולשון שינה ובא לכבוש המלכה כו' <span data-k=\"sm\">[ודי בזה למבין]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויקהל סז</b>,<b> סע</b>\"<b>ג (רנ</b>,<b> ב)</b>\n----- הערות וציונים -----\nעיין לעיל סי' קטו בריש ההערות, שם העתקתי מש\"כ במקורו לפני דיבור זה ולאחריו. ועיי\"ע לקמן סי' רצז (ושם בסופו: וזה סוד הוידוי)."]]],[300010308,"רנג\n\n<b>&lt;מהבעש\"ט</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> מופת על &lt;ענין&gt; מחשבות זרות שבאין לאדם באמצע התפלה &lt;כי הם&gt; מסוד השבירה ורפ\"ח ניצוצין שצריך האדם לברר בכל יום, והם באין לתקן אותם ולהעלותם, ואין מ\"ז של יום זה דומה למחשבה של מחר, והוא בחון למי שנותן לב.\n<b>&lt;וז\"ש</b><i>[ftnref_1_נא]</i> אשר ראיתם את מצרים, שהם המ\"ז של היום שהם המצירים לאדם, לא תוסיפו לראותם עוד עד עולם&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויקהל סז</b>,<b> ד (רנא</b>,<b> א)</b>\n<i>אשר ראיתם גו' לא תספו גו'</i> – בשלח יד, יג. <i>מבואר בכתבי האר\"י זלה\"ה</i> – פע\"ח שער התפלה פ\"ז. שער הכונות, סדר שבת, בתחילתו.\n----- שולי הגליון -----\n[ftn_1_נא]) <i>מכאן ואילך כתב המחבר בסגנונו הוא מה שהובא לפני ריש סימן זה</i>,<i> שנשאל בעל תוי\"י היתכן לומר</i> \"שיש גם עכשיו גלות מצרים והא כתיב כאשר ראיתם את מצרים היום לא תוסיפון לראותם עוד עד עולם, ותשובתי הי' כי מבואר בכתבי האר\"י זלה\"ה שאין בחי' תפלה של יום זה דומה לתפלת יום מחר עד ביאת המשיח . . . ושמעתי בשם <i>מורי</i> מופת על זה מן המ\"ז\" <i>(כנ\"ל בתחילת הפיסקא)</i>.\n----- הערות וציונים -----\nכבר הובא לעיל סי' קיב במילואו עיי\"ש. וראה בהערות לסי' לט."]]],[300010309,"רנד\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; איך שומע אדם ליצה\"ר לעשות עבירה, היה לו ללמוד מיצה\"ר עצמו שעושה רצון קונו תמיד &lt;וז\"ש&gt; <span data-k=\"sm\">[וכאשר שמעתי בשם </span><i>מורי</i><span data-k=\"sm\"> זלה\"ה ביאור פסוק]</span> כי תצא למלחמה על אויבך ונתנו ה' אלקיך בידך ושבית שביו <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י פקודי ע</b>,<b> ב (רס</b>,<b> ב)</b>\n<i>מיצה\"ר עצמו שעושה כו'</i> – זח\"ב קסג, א. <i>כי תצא גו'</i> – כי תצא כא, י.\n----- הערות וציונים -----\nראה לעיל סי' קלד ולקמן סי' שעב."]]],[300010310,"רנה\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה בענין&gt; <span data-k=\"sm\">[שהקשה </span><i>מורי</i><span data-k=\"sm\"> על]</span> משרז\"ל בכל יום בת קול יוצאת מהר חורב ומכרזת כו', &lt;והקשה&gt; ממה נפשך אם א\"א לשום אדם לשמוע הכרוז הזה א\"כ למה יוצא בת קול כלל, ואם אפשר <span data-k=\"sm\">[להם]</span> שישמע <span data-k=\"sm\">[אם כן]</span> מ\"ט לא נשמע <span data-k=\"sm\">[שאם יאמר אדם ששמע ידונו אותו כנביא שקר]</span>. וביאר כי למעלה אין אומר ואין דברים רק עולם המחשבה, א\"כ מה שמגיע לאדם מהרהורי תשובה הוא מן הכרוז וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>ולכך</b> אין רשע שאין לו הרהורים טובים בכל יום מכח הכרוז הנ\"ל, ובבוא הרהורים טובים מפנה ומעבירן מלבו ומפנה לבו לבטלה, ובודאי מתחייב בנפשו שניתן לו אוצר טוב והוא בורח מהמלך. כמו ששמעתי משל בשם <i>מורי</i> למלך שהיה ממנה על אוצרו ד' שרים ונטלו האוצר וברחו, א' נתיישב בדעתו וחזר מעצמו, ב' נתיעץ עם חכם א' ודיבר על לבו מה ראה על ככה וחזר, הג' הגיע למקום שדנין בני אדם על כיוצא בזה וחזר מחמת מורא, ד' לא שב כלל. והמלך לזה שחזר מעצמו נתן לו יותר גדולה מאחר שנתיישב בטוב שכלו לחזור, משא\"כ להשני אמר אלו לא מצא חכם שיעצו כך לא היה חוזר, והג' שחזר מחמת שראה שדנין לבני אדם מינהו המלך להיות ממונה שם לראות זה הצער. ואמר <i>מורי</i> &lt;זלה\"ה&gt; זה על עצמו והבן &lt;ודפח\"ח&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י צו עה</b>,<b> ב (רפא</b>,<b> ב)</b>\n<i>בכל יום בת קול כו'</i> – אבות פ\"ו מ\"ב. <i>אין אמר ואין דברים</i> – תהלים יט, ד. <i>ומפנה לבו לבטלה כו'</i> – אבות פ\"ג מ\"ד.\n----- הערות וציונים -----\n<i>בת קול יוצאת כו'</i> – ראה לעיל סי' קמו ובהערות שם, ולקמן סי' שס.\n<i>ששמעתי משל בשם מורי כו'</i> – המשל כבר הובא לעיל סי' קיז, ולהעיר שמשל זה הובא בחובה\"ל שער התשובה פ\"ו, ומשם בתוספת ביאור בעוללות אפרים מאמר רלו – ומשם בתוי\"י ר\"פ נשא קיח, ריש ע\"ב (תמג, א) עיי\"ש."]]],[300010311,"רנו\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה פי'&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כל העולם ניזון בשביל חנינא בני, &lt;פי'&gt; שהוא פתח הצנור ושביל השפע לעולם <span data-k=\"sm\">[ודפח\"ח]</span>. . .\n<b>והנה</b> שמעתי <i>ממורי</i> ענין הנס הוא שנתחדש הדבר בפעם הראשון על הטבע נקרא נס, ואח\"כ נעשה זה טבע ג\"כ <span data-k=\"sm\">[וכו']</span>. וכמו ששמעתי בשם הרב הבית יוסף שטרח ויגע עד &lt;שבא על&gt; <span data-k=\"sm\">[שמצא]</span> פירוש איזה מאמר, ואח\"כ שמע אותו פירוש מאחרים ג\"כ ונצטער &lt;ואמר&gt; <span data-k=\"sm\">[והשיב]</span> לו האר\"י זלה\"ה שאתה פתחת הצנור.\n<b>&lt;וז\"ש&gt;</b> <span data-k=\"sm\">[ובזה יובן]</span> אם בחקותי תלכו, &lt;פי'&gt; כי אחר שפתח צנור החכמה שגורם צנור השפע, כמו ששמעתי <i>ממורי</i> <span data-k=\"sm\">[פירוש תפילה לעני כי יעטוף וכו' יעו\"ש]</span>, והוא הדין כשפתח צנור היראה ועבודת ה' נעשה זה טבע, וצריך שלא יהיה חק קבוע שישאר במדריגה זו, כ\"א שילך ממדריגה למדריגה עליונה לחדש ולפתוח עוד צנור חדש. וז\"ש אם בחקותי תלכו וגו', וזה גורם לחדש צנור השפע והברכה ג\"כ, לכך ונתתי גשמיכם בעתם וגו' <span data-k=\"sm\">[וק\"ל]</span>.\n<b>ובדרך</b> זה שמעתי בשם <i>מורי</i> פירוש הפסוק תקעו בחודש שופר וגו' כי חק לישראל הוא <span data-k=\"sm\">[משפט לאלהי יעקב]</span>, והקשה דהוי ליה למימר תקעו שופר בחודש, &lt;ותירץ דה\"פ&gt; <span data-k=\"sm\">[והעולה מדבריו]</span> כי יראה שיהיה בחודש, ר\"ל לחדש שלא יהיה כמו חק קבוע, וז\"ש כי חק לישראל &lt;הוא, אז משפט לאלקי יעקב עמו על זה&gt; וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י צו עז</b>,<b> ב (רפט</b>,<b> א)</b>\n<i>כל העולם כו'</i> – ברכות יז, ב. <i>אם בחקתי גו' ונתתי גשמיכם גו'</i> – בחקותי כו, ג-ד. <i>תפלה לעני גו'</i> – תהלים קב, א. <i>תקעו גו' כי חק גו'</i> – תהלים פא, ד-ה.\n----- הערות וציונים -----\n<i>כל העולם נתון כו'</i> – ראה לעיל סי' ה ובהערות שם.\n<i>ענין הנס</i> – ענין הנס (עד נעשה זה טבע ג\"כ), וסוף הסימן (פי' תקעו בחודש שופר) כבר הובא לעיל סי' קיט.\n<i>ששמעתי בשם הרב הבית יוסף כו'</i> – כן הובא ג\"כ בשבחי הבעש\"ט ע' קמט (ועיי\"ש מפי' הרח\"ו לבטוי השגור בזוה\"ק – פתח ר\"ש. וראה עוד מזה בריש ס' אוה\"ח לזח\"א א, א (דף א, ע\"ד) ד\"ה והרא\"ג כתב (והובא במדבר קדמות מערכת א' אות ז\"ך). ולהעיר שהרא\"ג כתב זה בשם רבו הרמ\"ק. ובשער מאמרי רז\"ל, בסוף מאמרי מדרשי רז\"ל (נו, ב) הובא ממש כמו שכתב הרא\"ג). עיין לקו\"י טז, ג (סי' קפז), ושם כמו שאמר המגיד לבית יוסף (וכן הוא בחומת אנ\"ך להחיד\"א משלי ג, יג, ובמדבר קדמות בסוף מערכת יו\"ד אות ח\"ן, ושם הביא העובדא מסוף ס' אורים גדולים להרא\"י זאבי – והוא שם בחלק אור לישרים). ואולי הכונה להא דאיתא בס' מגיד מישרים פ' כי תצא בד\"ה אור ליום שבת כ\"ד לניסן מש\"כ שם דבתר דאתא שמואל הוו מתנבאים בכל דוכתא עיי\"ש. ועיי\"ע בהוספות למדל\"י-או\"ת סי' צח (והובא במאמרי אדה\"ז – הקצרים, ע' תסד) ביאור אדה\"ז להנהגת הרה\"מ. ולהעיר מיבמות צב, ב אי לאו דדלאי לך חספא כו'.\n<i>פירוש תפלה לעני כו'</i> – פירוש הבעש\"ט על פסוק זה הובא לעיל סי' צז (ובקיצור סי' ס). ועיין המבואר בתוי\"י פ' שלח קלג, ד (תקט, א) – ושם קלד, רע\"ג (תקי, סע\"א), הובא לקמן סי' רעו – על פסוק זה.\n<i>שילך ממדרגה למדרגה עליונה כו'</i> – ראה לעיל סוף סי' רז-ב.\n<i>שיהיה בחודש כו'</i> – השוה מש\"כ באו\"ת סי' רסא על פסוק זה."]]],[300010312,"רנז\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[קבלתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כי יש עשר ספירות באדם הנקרא עולם קטן, כי המחשבה נקרא אבא ואחר הצמצום להחליט נקרא אימא וכו', עד והאמנה נקרא תרי &lt;סמכי&gt; <span data-k=\"sm\">[ירכי]</span> קשוט, ותענוג בעבודת הש\"י נקרא יסוד צדיק ברית המילה וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י מצורע פו</b>,<b> א (קדשים שנד</b>,<b> ב)</b>\n<i>באדם הנקרא עולם קטן</i> – תנחומא פקודי ג.\n----- הערות וציונים -----\nראה לעיל סי' יא ופח ובהערות שם, ולקמן סי' תח.\n<i>יסוד צדיק ברית המילה</i> – ראה תקו\"ז יז, א."]]],[300010313,"רנח\n\n<b>שמעתי</b> <i>ממורי</i> כמו שיש אבות בקדושה כך יש במרכבה הטמאה וכו'.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י אחרי פז</b>,<b> סע</b>\"<b>ב (שכז</b>,<b> ב)</b>\n----- הערות וציונים -----\nעיין צוה\"ר סי' קלט. להעיר מזח\"ג מא, ב ושם ע, א. וראה לעיל סי' לא, לקמן סי' תג, וצוה\"ר סו\"ס קכד."]]],[300010314,"רנט\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> בענין תפלת היום שיהיה על דרך אני מעורר השחר ואין השחר מעורר אותי, &lt;פי'&gt; שיטרח וייגע &lt;הרבה&gt; בהדרגה עד ברוך שאמר שהוא נגד עולם העשיה שהוא למטה מקום הקליפות, ואח\"כ יכוין יותר מברוך שאמר עד ישתבח שהוא יצירה ואין שם קליפות כל כך כמו בעשיה, ומישתבח עד עמידה יכוין יותר, ובעמידה הוא החיבוק וזיווג האמתי יפשיט א\"ע מהגשמיות כמ\"ש בש\"ע א\"ח סי' צ\"ח <span data-k=\"sm\">[יעו\"ש]</span>, ואז נעשה תחלה מ\"נ ואח\"כ באו מ\"ד ויולדת זכר. משא\"כ כשבא לאדם התעוררות מעצמו, אז ח\"ו מורה על הצרה בסוד ותפלתו תהיה לחטאה, והתקנה כשיעלה על לבו זאת ויתחרד בחרדה גדולה ויתפלל יותר מעומק הלב [. . .] וז\"ש מצא אשה תחלה ואח\"כ מצא טוב, אז ויפק רצון מה' &lt;ודפח\"ח&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י אחרי פח</b>,<b> ג (של</b>,<b> א)</b>\n<i>אני מעורר כו'</i> – ירושלמי ברכות פ\"א ה\"א. <i>עד ברוך שאמר כו'</i> – פע\"ח שער התפלה פ\"ד ואילך. <i>סי' צ\"ח</i> – סעיף א. <i>ויולדת זכר</i> – ע\"פ תזריע יב, ב. <i>ותפלתו תהי' גו'</i> – תהלים קט, ז. <i>מצא אשה גו'</i> – משלי יח, כב.\n----- הערות וציונים -----\nעיין לעיל סי' קכ. וראה בפ\"י, דרוש לש\"ת שנת תקכ\"א, קטו, סע\"ג: דכתב בטור או\"ח סי' א יתגבר שיהא הוא מעורר השחר ואין השחר מעורר אותו כמ\"ש דוד המלך ע\"ה עורה הנבל וכנור אעירה שחר (תהלים נז, ט ושם קח, ג) אני מעיר השחר ואין השחר מעיר אותי וכו', והקשה הט\"ז (או\"ח סי' א אות ב') הסיפא למה לי ותירץ שיש ב' מיני התעוררות שתחילה מתעורר מלמטה ואח\"כ בא לו התעוררות העליון לסייעו ודוד אמר שאין צריך וכו' אבל אנו וכו' יעו\"ש. ולי נראה לתרץ דהוצרך הסיפא לענין זה דיש ב' מיני התעוררות בענין אחר כי ב' מיני התעוררות שכ' הט\"ז הוא ענין א' שמתעורר הוא תחלה בתשובה וכיוצא בדבר טוב ואח\"כ מסייעין אותו מלמעלה כדין הבא לטהר מסייעין אותו (שבת קד, א), התעוררות ב' שאינו נותן לב מעצמו לשוב בתשובה או לעשות טוב כ\"א ע\"י שמעוררין אותו מלמעלה תחלה אז מתעורר למטה לעשות תשובה, והנפקותא בין ב' התעורר' אלו שמעתי ממורי זלה\"ה בסוד האשה מזרעת תחלה יולדת זכר שהוא רחמים (ר' זח\"ב עט, ב) ובהפך הוי דינא, ושפיר צריך הסיפא על ב' התעוררות הנ\"ל שיהא מבחי' שנזכר ברישא ולא מבחי' הנז' בסיפא וז\"ש ואין השחר מעיר אותי תחלה כאמור והבן.\n<i>וזיווג האמיתי</i> – ראה זח\"ב ר, ב ושם רטז, ב. וראה לעיל סי' טז ולקמן סי' שסב.\n<i>יפשיט א\"ע מהגשמיות כו'</i> – ראה לעיל סי' קצט-א (ובהערות שם) ורלט.\n<i>בסוד ותפלתו תהיה לחטאה</i> – ראה לעיל סי' קכ וקנט."]]],[300010315,"רס\n\n<b>שמעתי</b> <i>ממורי</i> שנשלח בן המלך מעל פניו וכו' ולא החזירו ע\"י שר כי אם ע\"י איש המוני כמו שנעשה הבן.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צא</b>,<b> סע</b>\"<b>ב (שמב</b>,<b> ב)</b>\n----- הערות וציונים -----\nראה לעיל סי' קמד, ושם סוף סי' קלו."]]],[300010316,"רסא\n\n[<b>משל</b>] שמעתי <i>ממורי</i> שפעם א' נזדמן מלחמה כבידה, והיה בדור ההוא גבור עריץ <span data-k=\"sm\">[מאד]</span> והי' העם מובטחין בגבורת הגבור ולא אזרו חיל לעמוד בקשרי המלחמה גם הם אתו עמו, והגבור הי' לו כמה מיני כלי זיין, ובתוך הזמן שהסדיר כלי זיינו לפניו שיהיו מוכנים, והשונא שכנגדו התחכם בתחבולות רשע וגנב מהגבור כלי זיינו אחד לאחד עד שלא היה לו במה להלחם <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צב</b>,<b> ד (שמה</b>,<b> ב)</b>\n----- הערות וציונים -----\nראה לעיל סי' קלג ובהערות שם. ורג\"כ לעיל סי' לה."]]],[300010317,"רסב-א<i>[ftnref_1_נב]</i>\n\n<b>מהבעש\"ט</b> זלה\"ה. שיוכיח מצד אהבה, כמ\"ש אשר יאהב ה' יוכיח וכיוצא. אבל הרוצה להתגדל ח\"ו עי\"ז, או להנאת ממון, שאינו לש\"ש, ולזה מעורר בקול בכי, כמ\"ש היתה לי דמעתי לחם, ושמעתי <i>ממורי</i> שגורם עי\"ז מדנים בין ישראל לאביהם שבשמים.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צד</b>,<b> סע</b>\"<b>א (שנא</b>,<b> א)</b>\n<i>אשר יאהב גו'</i> – משלי ג, יב. <i>היתה לי גו'</i> – תהלים מב, ד.\n----- שולי הגליון -----\n[ftn_1_נב]) <i>סימן זה הוא קיצור תוכן סי' קלא דלעיל</i>,<i> עיי\"ש</i>.\n----- הערות וציונים -----\nהמאמר במילואו לעיל סי' קלא."]]],[300010318,"רסב-ב\n\n[<b>בראש</b> <span data-k=\"sm\">השנה הזמן גורם לזה לפתוח פיו במוסר. וכן שמעתי </span><i>ממורי</i><span data-k=\"sm\"> מפורש וכו', רק שיהי' המוסר בבחינה ממוצעת]</span>, כי הלא יש ג' בחינות זהב וכסף ונחושת, והנה נחושת הם נחשים השרפים <span data-k=\"sm\">[אשר נאמר עליהם וישלח ה' בעם את הנחשים השרפים]</span>, מוכיחים המעוררים ח\"ו דין <span data-k=\"sm\">[על בני העולם וכאשר כתבתי מזה ג\"כ על פסוק לא תלך רכיל בעמך וכו']</span>, נמצא הם נחושת לשון נחש <span data-k=\"sm\">[וכמו שאמרו חז\"ל ויעש משה נחש נחשת לשון נופל על הלשון]</span>. ויש בחי' כסף &lt;של רחמים&gt; <span data-k=\"sm\">[שהוא כולו רחמים מלהתעורר במוסר שהוא קצת דין, וכמ\"ש מוסר ה' בני אל תמאס ואל תקוץ בתוכחתו. אבל בחינה ממוצעת היא זהב, שהוא לומר דברים נחמדים וכמ\"ש הנחמדים מזהב וגו' גם שהוא דין, כי מצפון זהב יאתה, והיינו לעורר לבבות ישראל שישובו בתשובה אל אבינו שבשמים בדברי כבושים הנכנס בלב כאו\"א לפי בחינתו, ואז יש תועלת גדול שגורם להמשיך שפע, וכמ\"ש בתיקונים יט דף ט\"ל ע\"א. . .</span>] –",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צג</b>,<b> א (שמו</b>,<b> ב)</b>\n<i>וישלח ה' גו'</i> – חקת כא, ו. <i>לא תלך רכיל גו'</i> – קדשים יט, טז. <i>ויעש משה גו'</i> – חקת כא, ו. <i>לשון נופל על לשון</i> – בר\"ר לא, ח. <i>מוסר ה' גו'</i> – משלי ג, יא. <i>כסף רחמים </i>. .<i> זהב דין</i> – זח\"ב קמח, א. <i>הנחמדים מזהב גו'</i> – תהלים יט, יא. <i>מצפון זהב יאתה</i> – איוב לז, כב.\n----- הערות וציונים -----\nראה לעיל סי' קיג-ב (רנא-ב) וקלא."]]],[300010319,"(רסג)\n\n<b>והוא</b> ע\"פ משל ששמעתי <i>ממורי</i> ששלח המלך בנו כו' &lt;ומבואר בכתר שם טוב חלק ראשון<i>[ftnref_1_נג]</i>&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צד</b>,<b> ריש ע</b>\"<b>ב (שנא</b>,<b> א)</b>\n<i>בכש\"ט חלק ראשון</i> – סי' קלא.\n----- שולי הגליון -----\n[ftn_1_נג]) <i>לעיל סי' קלא</i>,<i> בהמשך לסי' רסב</i><i>א</i>.\n----- הערות וציונים -----\nראה הערות וציונים לעיל סי' רסב-א."]]],[300010320,"רסד\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי בשם </span><i>מורי</i><span data-k=\"sm\">]</span> אתה הוא אלהינו, &lt;קשה&gt; דבתחלה אמר לנוכח ואח\"כ נסתר כו', &lt;ופי'&gt; שאם סובר האדם שהוא דבוק בו ית' והוא נוכח פני ה' ית' אז הוא רחוק ממנו ית', ואם סובר שהוא רחוק אז הוא קרוב, וא\"כ <span data-k=\"sm\">[זהו שאמר]</span> מי שסובר את\"ה אינו אלא הוא, ומי שסובר הו\"א אז &lt;הוא&gt; אלהינ\"ו <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ קדשים צט</b>,<b> סע</b>\"<b>ד (שעד</b>,<b> א)</b>\n<i>אתה הוא כו'</i> – פיוט אין כאלקינו.\n----- הערות וציונים -----\nראה לעיל סי' כט. ורג\"כ לעיל סי' נא ונה. ולהעיר מאו\"ת סי' קטו (מ, ריש ע\"ד בביאור נדה יג, א)."]]],[300010321,"רסה\n\n<b>ששמעתי</b> <i>ממורי</i> זלה\"ה ענין שחיטת מלאך המות &lt;לע\"ל&gt; הוא להוציא ממנו חלק הרע שישאר מלאך קודש ונעשה מן נב\"ל לב\"ן &lt;ודפח\"ח&gt; <span data-k=\"sm\">[וזה שנאמר ואת רוח הטומאה אעביר מן הארץ]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בהר קט</b>,<b> ד (תיג</b>,<b> ב)</b>\n<i>שחיטת מלה\"מ לע\"ל</i> – סוכה נב, א. <i>ואת רוח הטומאה גו'</i> – זכרי' יג, ב.\n----- הערות וציונים -----\nעיין לעיל סי' קכח ובהערות שם. רג\"כ הערות לסי' קטו.\n<i>ונעשה מן נבל לבן</i> – עיין לעיל סי' פז ובהערות שם."]]],[300010322,"רסו\n\n<b>&lt;שמ\"מ</b> ע\"פ דגל מחנה דן צפונה הוא דן מאדני כי מצפון תפתח הרעה&gt;<i>[ftnref_1_נד]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נשא קיח</b>,<b> רע</b>\"<b>ג (תמד</b>,<b> א)</b>\n<i>דגל מחנה דן צפונה</i> – במדבר ב, כה. <i>את הגוי אשר גו'</i> – לך לך טו, יד. <i>מצפון תפתח גו'</i> – ירמי' א, יד.\n----- שולי הגליון -----\n[ftn_1_נד]) <i>במקורו בתוי\"י</i>: \"דגל מחנה דן צפונה, כמש\"כ ואת הגוי אשר יעבודו דן אנכי, שכבר שפטו ודנו במה ששעבדו את ישראל כמו ששמעתי ממורי, והוא מצפון תפתח הרעה\".\n----- הערות וציונים -----\n<i>דן מאד'</i> – כלומר בחי' דין.\n<i>שכבר שפטו ודנו כו'</i> – ראה לקמן סי' שט ובהערות שם.\n<i>והוא מצפון כו'</i> – להעיר מזח\"א רמג, ב. לקו\"ת להאריז\"ל פ' ויצא, שלהי ד\"ה סוד יעקב וב' נשיו."]]],[300010323,"רסז\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה ע\"פ&gt; <span data-k=\"sm\">[לפי שאמרו כל העדה לרגום אותם באבנים לכך אמר השי\"ת]</span> עד אנה ינאצוני &lt;ועד אנה לא יאמינו בי&gt;, כי עד עכשיו אף שנאצו אותי כמה פעמים אין מקום לעונש לחול עליהם, משא\"כ עתה עד אנה לא יאמינו בי דייקא, כי האמנה היא דביקות <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה, ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ שלח קכט</b>,<b> א (תפט</b>,<b> א)</b>\n<i>שאמרו כל העדה גו'</i> – שלח יד, י. <i>עד אנה גו'</i> – שלח יד, יא.\n----- הערות וציונים -----\n<i>כי האמונה היא דביקות</i> – ראה לקמן סי' שי ובהערות שם."]]],[300010324,"רסח\n\n<b>לא</b> יכוין בתיקון למעלה וגם למטה לעצמו, כי הוי כמו קוצץ בנטיעות לעשות פירוד <span data-k=\"sm\">[כאשר שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span>. &lt;כ\"א יעשה הכל עבור&gt; <span data-k=\"sm\">[המכוין לתקן למעלה]</span> חסרון השכינה, וממילא &lt;יתוקן הכל, אף&gt; <span data-k=\"sm\">[נתקן]</span> לעצמו חסרון למטה בתיקון שרשו למעלה, כי הכל למעלה ולמטה אחדות א' <span data-k=\"sm\">[הוא]</span><i>[ftnref_1_נה]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שלח קלד</b>,<b> סע</b>\"<b>ד (תקט</b>,<b> א)</b>\n----- שולי הגליון -----\n[ftn_1_נה]) <i>הפך סדר הדברים</i>;<i> במקורו תחילה</i> \"המכוין לתקן . . . אחדות א' הוא. על כל פנים לא יכוין\" <i>(כבפנים ברישא דסימן זה)</i>.\n----- הערות וציונים -----\nראה לעיל סי' פ וקעו. ורג\"כ לעיל סי' כ וש\"נ בהערות."]]],[300010325,"רסט\n\n<b>&lt;שמ\"מ&gt;</b> מאין באת ולאן אתה הולך, <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> כי העושה מצוה גדולה או למד תורה הרבה והתפלל בכוונה לא יכנוס בלבו שום התפארות שהוא עשה זאת כ\"א מלכות שנק' אנ\"י מן אדנ\"י היא עשתה זאת, ובאם לאו גורם ח\"ו שמסתלק י' מן אנ\"י ונשאר אן <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קרח קמג</b>,<b> ד (תקלג</b>,<b> ב)</b>\n<i>מאין באת כו'</i> – אבות פ\"ג מ\"א. <i>מלכות שנק' אני</i> – זח\"א רס, ב. שם רסא, ב.\n----- הערות וציונים -----\nראה לעיל סי' נה ובהערות שם."]]],[300010326,"ער\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[והנה שמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> כי תיקון בעלי תשובה העיקר הוא ע\"י גדולי הדור שיכול להעלותו ולקשרו בשרשו וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קרח קמד</b>,<b> א (תקלד</b>,<b> ב)</b>\n----- הערות וציונים -----\nנשנה לקמן סי' שצז. וראה דמ\"א פ' שמיני ד\"ה ויקרב: אא\"ז זללה\"ה אמר שעיקר תיקוני התשובה א\"א בלא הצדיק רק על ידו יוכל להתעלות כו' עיי\"ש. ועיי\"ש עוד פ' תזריע רד\"ה וטהרה ור\"פ מצורע ד\"ה זאת תהיה. ועיי\"ע לקו\"י לז, שלהי ע\"ג (סי' רפא סד\"ה וכבר אמרנו. באו\"ת ר\"פ נח סי' טו (ה' ריש ע\"ד) כי כל הרהורי תשובה שהרשעים מהרהרין בתשובה בכל יום הכל בא להם ע\"י הצדיק כו', עיי\"ש הביאור באורך; וכן שם סי' קטז (באו\"ת סי' תפז), ומדל\"י סוף סי' קעז (קפב)."]]],[300010327,"רעא\n\n<b>שמעתי</b> <i>ממורי</i> &lt;על&gt; <span data-k=\"sm\">[ביאור]</span> פסוק אחור וקדם צרתני ותשת עלי כפיך, כי החיות רצוא ושוב, וחיות האדם הוא בסוד קטנות וגדלות, וכאשר יתן דעתו לידע שהוא בקטנות ע\"י דעת זה נמתקים הדינים בשרשן, כי ה' גבורות מנצפ\"ך בדעת ז\"א כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י חקת קמו</b>,<b> ג (תקמג</b>,<b> א)</b>\n<i>אחור וקדם גו'</i> – תהלים קלט, ה. <i>החיות רצו\"ש</i> – יחזקאל א, יד. <i>ה' גבורות מנצפ\"ך כו'</i> – ע\"ח ש\"ה פ\"ג. שם שכ\"ה פ\"ב.\n----- הערות וציונים -----\nכבר הובא לעיל סי' קלט ועיי\"ש בהערות."]]],[300010328,"ערב\n\n<b>&lt;מהר\"י</b> בעש\"ט זלה\"ה&gt; כל המענג את השבת ר\"ל ש' בת, <span data-k=\"sm\">[ונבאר מ\"ש בזוהר פ' נשא דף קמח]</span> ויחשבה לו צדקה כי צדק אע\"ג דדינין מתערין מינה הוא חשבה צדקה רחמי <span data-k=\"sm\">[יעו\"ש]</span>, והוא דשמעתי <i>ממורי</i> &lt;הבעש\"ט זלה\"ה&gt; לקשר מלכות במחשבתו עד אתר דאתנטילת מתמן המחשבה זו שהיא שרשה, ועי\"ז נתבטל כל גזירות &lt;רעות&gt; <span data-k=\"sm\">[קשות. . .]</span> ודפח\"ח.\n[<b>ובזה</b> <span data-k=\"sm\">יובן כי נודע בת הי' לאברהם ובכל שמה, א\"כ אברהם ויחשבה לו לקו החסד בחינת אברהם, ונעשה צדקה רחמי, קשרה בשרשה ע\"י מחשבתו והבן. ובזה יובן כל המענג את השבת]</span>, ר\"ל ע\"י תענוג שבת שיש במלכות הנק' בת וקשרה אל ג' אבהן הנק' ש', וז\"ש אז תתענג על ה', נותנין לו נחלת יעקב בחיר שבאבות שהוא בגמר ש' משולש, והבן והש\"י יכפר.\n<b>ועד\"ז</b> שמעתי <i>ממורי</i> &lt;הבעש\"ט זלה\"ה&gt; פי' הש\"ס הנהו תרי בדחי שהם בני עוה\"ב, שהיו מייחדין כל עניני בני אדם שהיו רואין בהם, והם ייחדו במלכות מעשה הזה וקשרו אותה למעלה בשרשה, ומי שהיה עצב שלא יכלו לקשרו למעלה שמחו אותו בדברים עד שייחדו וקשרו כל המדריגות שהן במלכות בשרשן כו' והבן, וע\"פ שאלה נאמר לו והש\"י יכפר.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נשא קכ</b>,<b> ג (תנא</b>,<b> ב)</b>\n<i>כל המענג כו' נותנין לו נחלה כו'</i> – שבת קיח, א. <i>השבת ש' בת</i> – זח\"ב רד, א. <i>נשא דף קמח</i> – ע\"א. <i>ויחשבה לו צדקה</i> – לך לך טו, ו. <i>בת הי' לאברהם כו'</i> – ב\"ב טז, ב. <i>קו החסד בחינת אברהם</i> – זח\"ג שב, א. <i>במלכות הנק' בת</i> – זח\"ג רנו, ב. תקו\"ז ת\"ע קלג, ב. ראה זח\"ב פה, ב. <i>ג' אבהן הנק' ש'</i> – זח\"א ב, ב. שם כג, סע\"ב. זח\"ב רד, א. <i>אז תתענג גו'</i> – ישעי' נח, יד. <i>יעקב בחיר שבאבות</i> – בר\"ר עו, א. <i>הנהו תרי בדחי כו'</i> – תענית כב, א.\n----- הערות וציונים -----\n<i>לקשר מלכות במחשבתו כו'</i> – ראה לעיל סי' סז-א והנסמן שם בהערות.\n<i>אתר דאת נטילת מתמן כו'</i> – ראה זח\"ב קכו, ב.\n<i>ועי\"ז נתבטל כל גזירות קשות</i> – ראה לעיל סי' קפ וקפט.\n<i>במלכות כו' וקשרה כו'</i> – ראה מדל\"י סו\"ס קכו (קלה).\n<i>הנהו תרי בדחי כו'</i> – ראה לעיל סי' לז ונח ובהערות שם."]]],[300010329,"רעג-א\n\n<b>בכל</b> תנועה נמצא הבורא יתברך, שאי אפשר לעשות שום תנועה ושום דיבור בלי כח הבורא יתברך וזהו מלא כל הארץ כבודו.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י לח (מא)</b>\n<i>מלא כל גו'</i> – ישעי' ו, ג.\n----- הערות וציונים -----\nראה לעיל סוף סי' ר-א."]]]]});
